with nuevas(numero,viejo,sec) as (values
(33,'ab4d2b425ee6e573491bfdca7b925250',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìwòrì trae solución para la esterilidad de la mujer y del hombre y para la impotencia. Es un momento muy propicio para quedar embarazada. También pide ofrecer en grande para que la vida sea bella y placentera hasta el final."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pregunta por un embarazo o por hijos (relato de las palomas Eyẹlé y Adaba).", "Le preocupa un problema sexual o para tener hijos (relato de Oromina).", "Quiere saber si su vida mejorará y si podrá disfrutar lo que espera (relato de Wáléọlá).", "Una etapa terminó en conflicto y necesita aprender a cuidar a quienes dependen de él.", "Busca apoyo mutuo en la pareja sin que el deseo de tener hijos se vuelva motivo de culpa."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fertilidad para la mujer y para el hombre.", "Un embarazo en buen momento.", "Una vida bella y rica hasta el final.", "Paz mental."]}, {"titulo": "Ibi y advertencias", "puntos": ["Fracasar en la intimidad por no ofrecer.", "Vivir con la duda de si la vida será buena."]}, {"titulo": "Enseñanza principal", "texto": "La paloma y el palomo ofrecieron los dos, y los dos fueron fértiles: la descendencia es tarea de la pareja. Y quien ofrece en abundancia, vive en abundancia."}, {"titulo": "Relatos reunidos", "puntos": ["La paloma y el palomo. Ọ̀yẹ̀kúbìrì consultó para la paloma y le dijo que sería fértil si ofrecía doscientos frijoles y 2,000 cauríes. Cumplió y fue fértil. También consultó para el palomo, que hizo su ofrenda y también fue fértil.", "Oromina va a la lucha. Los adivinos Ọ̀yẹ̀kú y Ìwòrì consultaron para Oromina, el miembro viril, cuando iba a pelear en la ciudad de Ajatiri, y le advirtieron que si no ofrecía no lograría entrar. Le marcaron tres carneros, tres chivos, tres perros machos, tres gallos, tres jicoteas machos y 6,600 cauríes. Cumplió y logró entrar.", "Wáléọlá, el que trae riqueza a casa. La Tierra se traga todo lo que se le da como regalo. Así se consultó para Wáléọlá, hijo de Àsàńléèyere, que preguntaba si la vida le sería placentera hasta el final. Le pidieron una ofrenda enorme; la dio en grande, cumplió los ritos y su vida fue placentera. Wáléọlá es el sobrenombre del hombre blanco: nadie ha sido tan rico como él, y gasta su dinero siempre fresco.", "El espectro que bajó del cielo. 'Ọ̀yẹ̀kú gira para acá, Ọ̀yẹ̀kú gira para allá, y la cara de la bandeja de Ifá se llena hasta el borde.' Así se consultó para el espectro que venía del cielo a la tierra, para que dejara de preguntarse si la vida le sería buena. Ofreció, hizo los regalos a Èṣù y encontró la paz. Las bendiciones se encuentran al pie del rey de los Òrìṣà."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La paloma: doscientos frijoles y 2,000 cauríes. El palomo: su ofrenda.", "Oromina: tres carneros, tres chivos, tres perros machos, tres gallos, tres jicoteas machos y 6,600 cauríes.", "Wáléọlá: una ofrenda abundante.", "El espectro: ofrenda y regalos libres a Èṣù."]}, {"titulo": "Relaciones espirituales", "texto": "La Tierra recibe los regalos. Èṣù recibe la parte libre. El rey de los Òrìṣà es donde se encuentran las bendiciones."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Frijoles, jicoteas, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 33.1 (yorùbá): Qyèkúbìri: / li o dífá f'Ẹyẹlé. / Wọ̀n ni: \"Eyẹlé a rẹ\", / nitorinaa ki ó rúbọ: / Igbá eree, egbèwá owó. / Ó gbọ̀ ó rú. / Eyẹlé rẹ. / Wọ̀n dá f'Adaba. / Wọ̀n niki Adaba rúbọ. / Adaba rúbo. / Ó rẹ.", "Verso 33.2 (yorùbá): Ọ̀yẹ̀kú-awo-omodé, / Ìwòrì-awo-àgbàlagbà, / Bi oyin kobaṣeerẹ-ofufu-liafiitini'di: / wọn dífa fOromina / nlọ jagun ilu Ajatiri / Wọ̀n ni: \"bi ko ba rúbo koniile wọle\" / Ebọ: Agbo méta, / òbúkọ mẹta, ako-ajá mẹta, / akuko-adiyẹ, ako-ájapá mẹta / ati egbaa mẹtaelógbòn owó. / Ó gbọ̀ ó rú. / Ó wọle. / Oromina oruko ti aipe okó.", "REZO: OYEKUN WORI ADIFAFUN OKUNI ELEGBARA OWO KAFEREFUN OSHUN, LODAFUN ORUNMILA.", "REZO: EPANDIKI O EFANDIKI ESHANDIKI OKO SHAMBAKIRAN. ADIFAFUN ORUNMILA OFANDIKI OKO SHAMBA KIRAN. ADIFAFUN ORUNMILA.", "REZO: INSHO ADIFAFUN KETA ABOÑU, IÑA KOYEBEFA, IÑI ONU OKUNI OJUN OYEKUN IWORI PITI PITI LODAFUN ELEGBA, KAFEREFUN ORUNMILA.", "REZO: OSUN OKAN SHOSHE ADIFAFUN LOBO ASHO PUPUA ASHO FUN FUN LEBO.", "REZO: APUANDIKI, APUANDIKI ONI SHAMBA KIRIN LOYO ONI SHAMBA INAN, ADIFAFUN ORUNMILA BARABANIREGUN.", "REZO: OYEKUN WORI OKO OWO KOLLELEBO LODAFORRIMU BORI KOYULO INBARI EYELE MEYO BUYE AKUKO EKU EYA OBI OWO LA MEYO OUYO. ORIRU BODIYO KETAOKOAYE KUN OPADO OYU MEYI OKI ORI APADE ETU MEYI APADO IRU MEY APADO OYU MEYI OKI ORI APADO ETU MEYI APADO EMU MEYI APADO IRU MEYI APADO IRO MEYO.", "REZO: OSUN OKAN SHOSHE ADIFAFUN LOBO ASHO PUPUA ASHO FUN FUN LEBO.", "SUYERE: OJA OSUN LOFIN KITUNIBA KAMARIKU KAMARI ANO, KAMARI EYO, KAMARI OFO, ETC.", "REZO: INSHO ADIFAFUN KETA ABOÑU, IÑA KOYEBEFA, IÑI ONU OKUNI OJUN OYEKUN IWORI PITI PITI LODAFUN ELEGBA, KAFEREFUN ORUNMILA."]}]$q$::jsonb),
(34,'b43fa04090ff7be0f16a2cf690990e56',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìdí, en buena fortuna, anuncia éxito personal, de dinero y con las mujeres, y éxito en un viaje. En mala fortuna pide ofrecer para alejar a la muerte. Advierte que poner demasiado énfasis en la vida sexual amenaza la salud. La persona será popular y rica, vencerá muchos obstáculos y debe ser muy honesta."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pasa por escasez y necesita recuperarse poco a poco.", "Va a viajar por trabajo o por una relación y espera un buen resultado (relato de Ọ̀rúnmìlà en la ciudad).", "Busca éxito en el amor o en el dinero, cuidando que sus decisiones íntimas no le hagan daño.", "Teme una enfermedad o una pérdida grave (relato de Ikú y Àrùn de visita).", "Trabaja muchísimo y anhela descanso y reconocimiento (relato de Ayílórùlé Òjòpò Òrà).", "Necesita actuar con honestidad para sostener lo que mejoró."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Éxito y felicidad en un viaje de trabajo.", "Popularidad y riqueza; descanso y paz mental.", "Vencer obstáculos grandes, como Ògún venció a los monos rebeldes.", "Protección de la casa contra la muerte y la enfermedad."]}, {"titulo": "Ibi y advertencias", "puntos": ["La muerte y la enfermedad preguntan por la casa.", "Excesos en la vida sexual que dañan la salud.", "Faltar a la honestidad."]}, {"titulo": "Enseñanza principal", "texto": "La paciencia y la astucia vencen a la fuerza. Ògún se hizo pasar por muerto y atrapó a los dieciséis monos que ningún ejército pudo vencer. Hay que saber esperar el momento."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà en la ciudad de las mujeres. Bi oyin bi Ado consultó para Ọ̀rúnmìlà cuando iba de viaje de adivinación a la ciudad de las mujeres, y le dijo que ahí tendría mucho éxito y felicidad si ofrecía dieciséis palomas y 32,000 cauríes. Cumplió.", "La muerte pregunta por la casa. Ogidol'Egbá y Sagamo, el adivino de Eṣa, consultaron para Ọ̀rúnmìlà el día que la muerte y la enfermedad andaban preguntando dónde vivía. Le dijeron que si no ofrecía, moriría. Le marcaron dos perros negros y 4,400 cauríes. Cumplió.", "Ayílórùlé, el que compra y compra. Ifá consultó para Ayílórùlé Òjòpò Òrà, que compraba una y otra vez y llegó a comprar seis siervos en un día. Preguntó si la vida le sería placentera; ofreció una parte de su dinero y le llegaron una riqueza inmensa, la paz y el descanso. Desde entonces la paloma, cuando arrulla, dice su nombre.", "Ògún y los dieciséis monos. El rey de Ọ̀yọ́ estaba en guerra con dieciséis monos mandriles que lo atacaban sin parar. Su amigo Òdùyè lo llevó con el adivino, y este le dijo que buscara a Ògún. Ògún consultó a Ifá y Ọ̀rúnmìlà le pidió ofrecer su morral, su arco y sus flechas, su sueño, un trozo de carne guisada ya masticada y bastante maíz, y le dijo que no se pusiera nervioso. Ògún se tiró en la entrada del camino como si estuviera muerto, con el morral de almohada y el arco de bastón. Llegó el jefe de los monos y cantó: 'Veo al cazador muerto en el camino; usa su morral de almohada; el muerto no come carne guisada; saltaré por encima de él'. Uno a uno, los dieciséis monos fueron saltando sobre Ògún. Cuando saltó el último, Ògún abrió los ojos, lo agarró por la cola y fue capturándolos a todos, y se los llevó al rey. Desde entonces el rey de Ọ̀yọ́ no viaja ni emprende nada sin el consentimiento de Ògún."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà (viaje): dieciséis palomas y 32,000 cauríes.", "Contra la muerte y la enfermedad: dos perros negros y 4,400 cauríes.", "Ayílórùlé: una parte de su dinero.", "Ògún: su morral, su arco y flechas, carne guisada masticada y bastante maíz."]}, {"titulo": "Relaciones espirituales", "texto": "Ògún es quien vence a los enemigos del rey y se consulta antes de cada viaje. Ọ̀rúnmìlà indica la ofrenda. Ikú y Àrùn, la muerte y la enfermedad, rondan la casa."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Maíz, carne guisada, perros negros, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 34.1 (yorùbá): Bi oyin bi Ado / li o difá fÖrúnmilà / Ifá nṣawo lọ silu obirin. / Wọ̀n ni: / \"ayé a ye Ọ̀rúnmìlà lohun papoju / nitorinaa ki ó rúbo\": / Ṣyẹlé mẹrindilógún / ati egberíndilógún owó-ẹyo / Ó gbọ̀ ó rú.", "Verso 34.2 (yorùbá): Ogidol'Ẹ̀gbá, / Sagamo awo Eṣa: / wọ̀n difá fỌ̀rúnmìlà, / nijọ ti Ikú nfi ilé rẹ lọ, / ti Àrùn nfi ilé rẹ lọ. / Wọ̀n ni bikoba rúbọ I yoo kú. / Ebọ: ajá dúdú Méjì / ati egbejielógún owó. / Ó gbọ̀ ó rú.", "REZO: OYEKUN DI ORUNMILA ADIFAYOKO OLO U YUEKO ORUGBO ORUGBO, AKUKO, EURE YARAKO, AYA, EBEYO, OWO IWA, BOGBO INKAN ARAYE EBEBIKAN LONLE ILE OLOFIN.", "REZO: OYEKUN DI OLORUN LATIKU ORUN KANTARI OYEKUN DI.", "REZO: OYEKUN DI LERI NI BOGBO ORISHA PINU OLOFIN KURI LATINO ORISHA LERI BOGBO KO KOGNA LENI ELERI NI AWO ORUNLA ESI ELERI NI OMO MINU OLODUMARE MODDU KUESUN LO ALODO IRE.", "REZO: OLLOCUNDI ILO TIN UN OLORUN ALLECUIDI. ORUNMILA ADIFALLOCO OLO ILUOCUO ORUBO OQUE EURE YARAKO EKU, EYA, EBELLO EGUE IGUABOBO INCARALLE EBICAN LOALO ILA OLOFIN. OLLATUN OCU OLORUN OTI OLLECUIDI ELEUN AGUORIEBIARI OBA OCUN ANIALLE A LA ILU OCUN AGUORI.", "REZO: OYEKUN DIDI ADIFAFUN ALLE TONLOCO ODA ADIE EYELE LEBO. ALLOILUN ECUN AWO RIRE AWO RIRE BIERI OLALLE ALOLLUN A EKUN AWO RIRE.", "REZO: OYEKUN DI LERI NI GBOGBO ORISHA PINU OLOFIN KURI LATINO ORISHA LERI BOGBO KO KOGNA LENI ELERI NI AWO ORUNMILA ESI ELERI NI OMO MINU OLODUMARE MODDU KUESUN LO ALODO IRE.", "REZO: OYEKUN DI ILO TIN UN OLORUN ALLECUIDI. ORUNMILA ADIFAYOKO OLO ILUOKUO ORUBO OQUE EURE YARAKO EKU, EYA, EBELLO EWE IGUABOBO INCARALLE EBICAN LOALO ILA OLOFIN. OYATUN OCU OLORUN OTI OLLECUIDI ELEUN AGUORIEBIARI OBA OKUN ANIALLE A LA ILU OKUN AGUORI.", "REZO: OYEKUN DIDI ADIFAFUN ALLE TONLOCO ODA ADIE EYELE LEBO. ALLOILUN ECUN AWO RIRE AWO RIRE BIERI OLALLE ALOLLUN A EKUN AWO RIRE."]}]$q$::jsonb),
(35,'ab5c3992a450e713795d83d2b4e7f403',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìrosùn habla de obedecer a Ifá para tener éxito y evitar la muerte. Un buen pensamiento lleva a buenas acciones. Pide formar o unirse a un grupo de ahorro (èésú) para reunir riqueza, no ser avaro ni codicioso, y respetar a los adivinos aunque sean jóvenes."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Empieza una etapa nueva y teme desperdiciar la oportunidad por cerrar mal la anterior.", "Quiere mejorar su economía juntando de poco en poco con otros (relato del grupo de Èésú).", "Piensa en formarse o comprometerse en lo espiritual.", "No toma en cuenta el consejo de alguien más joven o de menor rango (relato de Ọlọ́fin).", "Espera prosperar con un conocimiento o práctica tradicional (relato de Gbẹrẹfu y sus ikines).", "Un malentendido en una reunión o con bebida genera un problema (relato de Òyè Ògosùn y Ṣàngó).", "Debe vigilar la codicia y dejar claros los acuerdos con quienes comparte recursos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Los ikin de Ifá enriquecen a la persona.", "Riqueza reunida poco a poco en un grupo de ahorro.", "Paz y una vida provechosa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Faltarle al respeto a un babaláwo, aunque sea joven.", "Provocar la ira de Ògún o de Ṣàngó.", "Mantener en alto los recipientes vacíos: aparentar lo que no hay.", "La avaricia y la codicia."]}, {"titulo": "Enseñanza principal", "texto": "No hay adivino pequeño. Ọlọ́fin despreció el consejo de uno joven y lo pagó con la vida. Y cuando se acaba el vino, se voltean los recipientes: aparentar que hay cuando no hay provoca la ira de los que esperan."}, {"titulo": "Relatos reunidos", "puntos": ["Gbẹrẹfu y sus ikin. Ajaweṣola consultó para Gbẹrẹfu, el hijo mayor de Ọ̀rúnmìlà, y le dijo que sus ikin lo harían rico. Le marcaron una rata, un pescado y una chiva. Cumplió.", "Ọlọ́fin y el adivino joven. Awokekeré-ilé-ẹni-kotan'nijẹ consultó para Ọlọ́fin y le pidió un perro, ñame asado, vino de palma y 6,600 cauríes para no ver la ira de Ògún. Ọlọ́fin no hizo caso y Ògún lo mató. Ifá advierte: a ningún babaláwo se le falta al respeto, aunque sea un adivino joven.", "El grupo de ahorro. Ifá consultó para la gente de Ẹgbàá Èésú, que estaba tratando de entender cómo se junta la riqueza. Les marcaron bastante dinero y una paloma vieja. Ofrecieron, y cada uno empezó a aportar una pequeña cantidad al grupo. Al cabo de un tiempo se repartieron lo reunido, tuvieron paz y sus vidas se volvieron ricas. Cantaron: '¿Quién hizo tanta ofrenda? El pueblo de Ọ̀yè rùsùrùsù'.", "Ọ̀yè Ògosùn y la sed de Ṣàngó. Ọ̀yè Ògosùn y su gente se tomaron cuarenta recipientes de vino. Ṣàngó pasó un día con mucha sed y no encontraba vino en ninguna parte, hasta que llegó con ese grupo que tenía los recipientes en alto. Se quedó esperando a que lo invitaran, sin saber que el vino ya se había acabado, y nadie lo llamó. Furioso, sacó de su bolsa su piedra de rayo (ẹdùn) y los fulminó a todos. Al tomar los recipientes descubrió que estaban vacíos y gritó: '¿Por qué los mantenían en alto si estaban vacíos?'. Desde entonces, cuando se acaba la bebida, el recipiente se pone boca abajo en el suelo para que todos sepan que ya no hay."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Gbẹrẹfu: una rata, un pescado y una chiva.", "Ọlọ́fin (rechazado): un perro, ñame asado, vino de palma y 6,600 cauríes.", "Ẹgbàá Èésú: bastante dinero y una paloma vieja.", "Al beber: derramar un poco en el suelo antes de empezar, y al terminar dejar el recipiente de lado en el suelo; ofrecer bebida a las visitas."]}, {"titulo": "Relaciones espirituales", "texto": "Ògún castiga el desprecio al adivino. Ṣàngó castiga la apariencia y la tacañería con la bebida. Los ikin de Ifá son fuente de riqueza para el hijo de Ọ̀rúnmìlà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Vino de palma, ñame asado, rata, pescado."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 35.1 (yorùbá): Ajaweṣola, / Atẹ-iyẹ̀-iròsù-ṣe-ola: / li o difá fún Gbẹrẹfu / tiiṣe arẹmo Ọ̀rúnmìlà. / Wọ̀n ni: / \"Ikin rẹ niyoo gbe e la\", / wọ̀n niki ó rú: / Eku, eja, ati ewúré. / Ó gbó ó rú.", "Verso 35.2 (yorùbá): Awokékeré-ilé-ẹni-kotan'nijẹ: / li o difá f'Ọlófin / Ó niki ó rúbọ: / ajá, ẹsun-iṣu, ẹmu / ati egbẹtalélógbọ̀n owó, / ki o ma baa ri ijà-Ogún. / Ó gbọ̀ kò rú. / Ogún pa a. / Ifá ni: / \"ki a mafi ojú di Babaláwo kan pe / ko nilaari tabi o keré\".", "REZO: OYEKUN BIROSO AWO OTI OLOFIN TULO SHWO SADU MERIN OTI OWO IWOKO, EBEYO ALA, ERI, BOGBO INTORI AYE KURBO OTIBE EYELE ABO INTORI IKU.", "REZO: OYEKUN IROSO, OGUO OTI OGUO IGUOBO ABOLLE ALA ORI GOGO INTORI ALLO CURBO OTIBO ALBA LEBO INTORI IKU.", "REZO: OYEKUN BIROSO AWO KOMO OWOBIA ABANIRE AWO KOMO AKONE RI IKU AWO KOMO AYE ADIE DUN DUN, BANIRE KOMO AWO PARALDO OBARISHAWO KOMO AWO IKU ABERIKUNLO ONA BENIREGUN AWO KOMO AWO AYO IKU AWO KOMO AWO OYEKUN BIROS ABONI ORUNMILA OMO KOMO ABUYA IFA AWO NO ORUN.", "REZO: ABITI OMO INLE ABEYI AWO ADIFAFUN LODAFUN ORUNMILA.", "REZO: OYEKUN BIROSO AWO KOMO OWOBIA ABANIRE AWO KOMO AKONERI IKU AWO KOMO AYE ADIE DUN DUN, BANIRE KOMO AWO OPARALDO OBARISHAWO KOMO AWO IKU ABERIKUNLO ONA BENIREGUN AWO KOMO AWO AYO IKU AWO KOMO AWO OYEKUN BIROSO ABONI ORUNMILA OMO KOMO ABUYA IFA AWO NO ORUN.NOTA: AQUI NACIO EL GRAN PODER DEL HIJO DE IKU Y EL GRAN PODER DEL HIJO DE IFA Y EL OPARALDO.", "REZO: ABITI OMO INLE ABEYI AWO ADIFAFUN LODAFUN ORUNMILA.", "SUYERE BBO LASHE EBBO LASHE ONI IGBA OMO IKUN EBBO LASHE OJOKORO ANGBE IKA."]}]$q$::jsonb),
(36,'ff338bb55d935fee12e6585bdcea59a9',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀wọ́nrín da remedio para las consecuencias del adulterio y para los peligros de los viajes lejanos. Las acciones descuidadas, indiscretas o sin pensar bloquean los negocios y el trabajo. Pide una ofrenda eficaz para no perder lo heredado de los padres; algo maravilloso viene en camino."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Actuó con prisa o fue indiscreto, y eso complica un negocio o una relación.", "Hay un pleito familiar que conviene hablar antes de que duela más.", "Hay un secreto o falta de confianza en la pareja (relato de Lawẹ́nibu).", "Se acerca una salida al monte o un viaje lejano por agua (relatos del cazador y de Ọ̀rúnmìlà).", "Un cambio inesperado le obliga a preparar recursos y explicar bien sus planes.", "Vive una angustia fuerte y necesita apoyo de gente cercana a tiempo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Conservar lo que se heredó de los padres frente a quienes lo quieren quitar.", "Regresar con vida de un viaje lejano o por agua.", "Algo maravilloso que viene a su encuentro.", "Ser elegido entre muchos por saber pedir ayuda."]}, {"titulo": "Ibi y advertencias", "puntos": ["Un adulterio que puede costar la vida si se descubre.", "Actuar sin pensar y bloquear los propios asuntos.", "Enemigos que conspiran para sacarlo de su lugar."]}, {"titulo": "Enseñanza principal", "texto": "Lo que es de la familia se defiende con la ofrenda, no con la fuerza. El cocodrilo siguió en las aguas de su padre y ningún enemigo pudo sacarlo."}, {"titulo": "Relatos reunidos", "puntos": ["Lawẹnibu confiesa. Okitibi-aketekiitan-nidi-ọ̀pẹ consultó para Lawẹnibu y le marcó una chiva para que pudiera confesar su adulterio sin que la mataran. Cumplió. Ifá dice que a la mujer a quien sale este Odù se le está viendo un adulterio.", "El cazador y Ọ̀rúnmìlà van lejos. Los adivinos consultaron para el cazador que iba al bosque de Olikorobojó y le marcaron seis gallos y 14,000 cauríes para no morir ahí; cumplió. También consultaron para Ọ̀rúnmìlà, que viajaba muy lejos cruzando el agua, y le marcaron un recipiente de aceite de palma, nueve gallos, nueve chivos, nueve ratas, nueve pescados y palomas. Cumplió.", "El cocodrilo en las aguas de su padre. Ifá consultó para el cocodrilo, que vivía en las aguas profundas que habían sido de su padre en Ìrágbìjí. Algunos se confabularon para sacarlo de ahí. Le marcaron un chivo viejo, o tres gallos, y bastante dinero. Ofreció, y ningún enemigo pudo con él: siguió estirándose a gusto en sus aguas. '¿Quién va a sacar ahora al cocodrilo de las aguas de sus padres?'.", "Ajíbówú, el herrero de la luna. Olódùmarè reunió a los herreros del mundo y les pidió crear toda clase de cosas, buscando al más hábil. Ajíbówú, herrero de Ògèlé, fue con los babaláwo porque lo que pedía el Supremo superaba lo que él sabía. Le dijeron que sirviera a las Madres, las Ancianas. Cumplió, y ellas le dieron la luna. Le dijeron que la tallara y la pusiera en un recipiente àdèmú, y que durante dieciséis días lo fuera destapando poco a poco. La gente veía cómo la luna creciente aparecía día a día, hasta que el último día la luna llenó el recipiente. Después la fue tapando de nuevo. Así nació la luna creciente."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Lawẹnibu: una chiva.", "El cazador: seis gallos y 14,000 cauríes.", "Ọ̀rúnmìlà: un recipiente de aceite de palma, nueve gallos, nueve chivos, nueve ratas, nueve pescados y palomas.", "El cocodrilo: un chivo viejo (o tres gallos) y bastante dinero.", "Ajíbówú: servir y ofrecer a las Madres (Ìyàmi)."]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè convoca a los herreros. Las Madres (Ìyàmi), las ancianas, entregan la luna a quien las sirve. Ọ̀rúnmìlà ofrece antes de cruzar el agua."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, recipiente àdèmú, gallos, ratas, pescados."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 36.1 (yorùbá): Okitibi-aketekiitan-nidi-ğpẹ / li o difa fun Lawẹnibu, / a niki ó wa rúbo, / kiosi wa ka'ką biobawipe ki oun ma kú. / Ewúrẹ kan li ebọ / tiobawipe ki oun ma kú ikú òràn naa. / Ó gbọ̀ ó rú. / Ifá nwipe: Obirin ti a da'fá yi fún ndoką.", "Verso 36.2 (yorùbá): Jafirijafi, Kẹmkẹjakẹ, / Agadagidiwonu-odo-ef'arabo-omi: / li o dífá fOdẹ. / Ó dífá f'Ọ̀rúnmìlà. / Odẹ nre igbó Olikorobojó, / wọ̀n niki ó rúbọ / kioma baa kus'ohun: / akuko-adiyẹ méje ati ẹgbàáje owó. / Qdẹ rúbo. / Ọ̀rúnmìlà nlọ s'ajo / ti o jin gbungbungbun bi omi. / Wọ̀n niki ó wa rúbọ / kioma baa Kus'ohun: / ata (ikoko) epo, / akuko-adiyẹ mésàn, / obúko mẹsàn, / eku mésàn, / ẹja mẹsăn ati ẹyẹlé. / Ọ̀rúnmìlà gbọ̀ ó rúbọ.", "REZO: OYEKUN JUANI BADAWA IFA OBA MAYIRE ELEGBARA BADAWA FA AYORE LOKUN OBA YORE OBA LOKUN ELEGBARA IFA LAYE BEITA IRE ASHEGUN OTA LESE ELEGBARA UN BATI AWO BOGBO OUN BAYE OLUWO.", "REZO: INTORI ARAYE OUKO ELEBO INTORI IWABOBO AKUTA ELEBO AIKU NIARE.", "REZO: OYEKUN ONIGUA ADIFAFUN OBINI INTORI ELLO IKOKO EFUN KUPA EYELE LEBO ADIE.", "REZO: IYERE O BABA ETIKA OSHEGUN FUN KOLOSHEGURE COBO OMASHE LONI ESETONSHE AKUKO ADIE AGUTAN EBEFA OWO.", "REZO: ORUNMILA ADIFAYOKO ODAFUN A IKU OWO NI ORIN.", "REZO: ADIFAFUN OBATALA LERI OMO ILEWA INTORI ARAYE LATI ILE OYEKUN OJUANI OBATALA UNLO ILE IÑA LOFEKEBA YOKO SHILEKUN ILE ARAYE IÑA KURUMA SHANGO OGGUN ATI OSHOSI IFA NI KAFEREFUN ORUNMILA.", "REZO: BADAWA IBA OBA OMAYERE ELEGBARA BADAWA EFA ELE OYERE LEKUN OBAYERE OBALEKUN ELEGBARA UMBATI AYE UNBATE AWO WAWA GBOGBO CABAYE OLUO FARE.", "REZO: IGUI INTORI OYO LAYO OPA KOFIADENO AYA ARUBO ORUN ONA NI ADA GBOGBO TENUYEN YOURO ABITI LARI LORUBO EKU, EYA, EPO, OWUNKO, MEDILOGUN OWO.", "REZO: ADIFAFUN OBATALA LERI OMO ILEWA INTORI ARAYE LATI ILE OYEKUN OJUANI OBATALA UNLO ILE IÑA LOFEKEBA YOKO SHILEKUN ILE ARAYE IÑA KURUMA SHANGO OGGUN ATI OSHOSI IFA NI KAFEREFUN ORUNMILA.", "REZO: BADAWA IBA OBA OMAYERE ELEGBARA BADAWA EFA ELE OYERE LEKUN OBAYERE OBALEKUN ELEGBARA UMBATI AYE UNBATE AWO WAWA GBOGBO CABAYE OLUO FARE.", "REZO: IGUI INTORI OYO LAYO OPA KOFIADENO AYA ARUBO ORUN ONA NI ADA GBOGBO TENUYEN YOURO ABITI LARI LORUBO EKU, EYA, EPO, OWUNKO, MEDILOGUN OWO."]}]$q$::jsonb),
(37,'c067ab50924a56e87c220ef3455990bd',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀bàrà da la oportunidad de librarse de las consecuencias de malas acciones o decisiones equivocadas del pasado, y rompe ataduras, deudas e impedimentos que bloquean la libertad. La persona pide lo bueno de la vida y le llegará; nunca estará sola."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Arrastra una deuda u obligación sin resolver y debe decidir cómo cumplirla (relato de Awun y Esi).", "Quiere evitar las consecuencias de algo que hizo antes.", "Se siente solo y se pregunta si tendrá apoyo (relato de Orí, al que se le unen las partes del cuerpo).", "Cuida de un hijo o de alguien que depende de él y teme un trato injusto (relato del caballo Eṣin).", "Usa la astucia para salir ganando y debe ver si con eso respeta a los demás.", "La impaciencia puede echar a perder un cambio que ya venía (relato del mono de Ìdèrè)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Liberarse de una deuda o de una atadura.", "Compañía: nunca estará solo.", "Honra y admiración.", "Lo bueno de la vida llega a su lado."]}, {"titulo": "Ibi y advertencias", "puntos": ["Que los hijos sufran castigos por no haber ofrecido completo.", "Ofrecer solo por lo que gusta y olvidar lo que protege.", "Problemas en el día a día por no atender la ofrenda."]}, {"titulo": "Enseñanza principal", "texto": "La ofrenda se hace completa. La yegua ofreció para ser admirada pero no para no ser azotada, y hoy la montan y la golpean a ella y a sus hijos."}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga y su deuda con Esi. La tortuga (Awun) trabajaba como sirviente de Esi para pagarle una deuda. Le marcaron 3,600 cauríes y una cabra para no tener que pagar el préstamo, y cumplió. Después se quedó cinco días en su casa sin reportarse. Envolvió un paquete de piedras con una cuenta de coral y lo dejó en casa de Esi. Esi, al volver, tiró el paquete al monte. Awun le preguntó si había visto lo que le dejó, y cuando Esi dijo que lo había tirado, gritó: '¡Tiraste mis cuentas de coral al monte!'. Fueron con los ancianos que hacían de jueces, Esi resultó culpable y tuvo que aceptar las cuentas que tiró como pago del préstamo.", "Orí y las partes del cuerpo. El adivino de la Cabeza consultó para Orí cuando venía del cielo a la tierra. Siempre había estado solo, y preguntaba si encontraría quién lo acompañara. Le pidieron ofrecer y cumplió. Cuando decidió partir, los ojos se pararon frente a él y dijeron que lo seguirían; la boca dijo que iría con él a donde fuera; la nariz dijo 'no te dejaré solo'; y las orejas, las piernas, los brazos y todas las partes del cuerpo se fueron con él, y él quedó como su líder. Por eso esta persona no estará nunca sola.", "La yegua y los azotes. El adivino del caballo consultó para la yegua (Ẹṣin) cuando venía del cielo, y al llegar a la tierra le pidieron ofrecer otra vez: para ser honrada y admirada, y también para no ser azotada. Solo ofreció para ser admirada; no dio los dieciséis fuetes de àtòòrí, doscientos garrotes, un chivo y 2,600 cauríes que la protegían del castigo. Cuando tuvo a su cría fue a Ọ̀yọ́, y Èṣù pidió que la gente se montara en ella. La gente dijo que acababa de parir, y Èṣù respondió que eso no le impedía caminar y que llevaran fusta. Desde entonces la montan y la golpean, a ella y a sus hijos. Se lamentó: 'Ọ̀yẹ̀kú pabala, pabala', que es el sonido de su trote recordando al adivino."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La tortuga: 3,600 cauríes y una cabra.", "Orí: ofrenda para tener compañía.", "La yegua (no ofreció completo): dieciséis fuetes de àtòòrí, doscientos garrotes, un chivo y 2,600 cauríes."]}, {"titulo": "Relaciones espirituales", "texto": "Orí es el líder del cuerpo y la cabeza de la persona. Èṣù hace cumplir la palabra de Ifá en el relato de la yegua. Los ancianos de la ciudad actúan como jueces."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Àtòòrí (fuetes), cuentas de coral (iyùn), piedras."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 37.1 (yorùbá): Ọ̀yẹ̀kú-Pabala, / Ọ̀yẹ̀kú-Pabala: / li o dífá f'Awun, / nigba ti o nṣe olofa / fún Esi™ wọ̀n ni biobarú, / Egbejidilógún owó ati ewúrẹ li ebọ. / A je owó ohun gun. / Ô gbọ̀ ó rú.", "Verso 37.2 (yorùbá): Ọ̀yẹ̀kú-Pabala, / Ọ̀yẹ̀kú-Pabala awo Ẹṣin: / li o dífá fún Ẹṣin / wọ̀n niki ó wa rúbọ / nitoripe nigbati o ba bimo / ki iyà ma baa jẹẹ: / igba opa, òbúko ati egbètalá owó. / Ẹṣin gbọ. Ẹṣin ko rú.", "REZO: OYEKUN BARA ALORDAFUN OSHUN LO OSAIN OÑI SHANGO SHEBE SHINTILU OSUSHE MUTI ESHIN NILOKO SHISHE IFA SHEMI OSHUN LONSHE OLUFINA OPOLOPO OTI OÑI SHANGO.", "REZO: OYEKUN BARA OLODOFA ESHU LOQUI MALU NI MALU AKUSHEWI TI OSHI MI BOKOSHISHE BI TONSHENILA FASHE NIBA ABALE NI TISHE OBINI AMBIMU PAWALE NO KITIM IYA LONA AKUKO UN BERESI MI PAMALE LONDE OMO OLOFIN. OYEKUN BARA MOFOKO SHOKUOLLO KAFEREFUN OBATALA, KAFEREFUN ESHU.", "REZO: ADIFAFUN IFA IKU YOYE ADIFAFUN ITA LUBA OLEFANA SOFA NIKUA MAMETA LODO SHEDE LADE SHOKA LUDO EKUN, ADIE DUN DUN, ISHERI META, EWEFA OWO LOKE OMA AYE RERE OMA AYE KERE OMA AYE IKUPA KEKE IKUPA MAKI ASHEBO PASHAN ELEBO, KAFEREFUN OZAIN, LODAFUN OBATALA.", "REZO: OYEKUN BARA LODAFUN ESHIN LO OZAIN SHANGO SHINTILU OSUSHE MUTI ESHIN NILOKO IFA SHOMI OSHUN LONSHE MAMU OLUFINA OPOLOPO OTI OGU WERE NINSHE OMO OLOFIN LODAFUN OZAIN KAFEREFUN ABOÑO OÑI SHANGO.", "SUYERE: ESHIN KIKO, ORO ASARELE ONI SHANGO WERE WERE NI TO SUN.", "REZO: ADIFAFUN IFA IKU YOYE ADIFAFUN ITA LUBA OLEFANA SOFA NIKUA MAMETA LODO SHEDE LADE SHOKA LUDO EKUN, ADIE DUN DUN, ISHERI META, EWEFA OWO LOKE OMA AYE RERE OMA AYE KERE OMA AYE IKUPA KEKE IKUPA MAKI ASHEBO PASHAN ELEBO, KAFEREFUN OZAIN, LODAFUN OBATALA.", "REZO: OYEKUN BARA LODAFUN ESHIN LO OZAIN SHANGO SHINTILU OSUSHE MUTI ESHIN NILOKO IFA SHOMI OSHUN LONSHE MAMU OLUFINA OPOLOPO OTI OGU WERE NINSHE OMO OLOFIN LODAFUN OZAIN KAFEREFUN ABOÑO OÑI SHANGO.", "SUYERE: ESHIN KOKO, ORO ASARELE ONI SHANGO WERE WERE NI TO SUN.", "REZO: OYEKUN BARA OLODABA ESU LO KIMOLU NI OKUSENI TE ESIN NI LOKO SESE NI TOASEMI LAFOSE NIBA ABAL BONSE OMO OLOFIN."]}]$q$::jsonb),
(38,'3bbeaf12457ccaf2f72db0e0747d84ce',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀kànràn habla de cómo la ofrenda protege de las malas intenciones de otros y de la pérdida del prestigio. La persona es terca y no quiere seguir un consejo sabio. Ifá promete arreglarle la vida y pide cuidar la relación con la pareja y no hacer falsas amistades."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["No quiere seguir un consejo razonable y se aleja de quien podría ayudarle.", "Quiere cuidar su prestigio y teme que una mala decisión lo dañe (relato de la estrella Irawọṣaṣa).", "Siente una amenaza en una salida o una fiesta (relato del mono Oyi).", "Una amistad o una relación de pareja necesita cuidado y límites.", "Busca descanso y estabilidad después de una etapa difícil (relato del Akápò de Ọ̀rúnmìlà).", "Si deja la terquedad, un cambio de rumbo puede traerle oportunidades."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que los enemigos no puedan vencerlo.", "Una vida reparada y tranquila.", "Conservar a la pareja a su lado."]}, {"titulo": "Ibi y advertencias", "puntos": ["Perder la fama y el honor por apartarse del camino del dueño.", "Meterse con la pareja de un amigo: puede costar la vida.", "La terquedad que rechaza el consejo.", "Ir a una fiesta donde alguien planea hacerle daño."]}, {"titulo": "Enseñanza principal", "texto": "El orgullo hace caer a la estrella. La que no siguió el camino de su señor es la estrella fugaz que vemos caer a la oscuridad. Y el que se mete con la mujer ajena, aunque esté avisado, paga con su vida."}, {"titulo": "Relatos reunidos", "puntos": ["El hijo del mono y la fiesta. Kabẹkukutekurolonà consultó para Akibola, que iba al campo a la fiesta anual con la idea de matar al hijo del mono (Oyi) y lucir su piel. Al mono le marcaron tres lanzas, tres gallos y 6,600 cauríes. Rechazó la ofrenda y lo mataron.", "La estrella orgullosa. Atorirorayo consultó para Irawọṣaṣa, la estrella, una de las sirvientas de Olódùmarè, y le dijo que si no seguía el camino de su señor, su fama se acabaría. Le marcaron una chiva y 2,000 cauríes, y se negó. Por eso, el día que Olódùmarè se refleja en el orgullo de una estrella, vemos una estrella fugaz caer del cielo a la oscuridad.", "El animal de cuernos para el Akápò. Ifá consultó para Ọ̀rúnmìlà, y Ọ̀rúnmìlà le dijo a su Akápò (su adivino ayudante) que preparara un animal del monte con buenos cuernos para que su vida mejorara. Lo prepararon y lo ofrecieron a Ifá; todo mejoró y llegaron la paz y el descanso.", "Mágbàgbéọlá y la mujer de su amigo. Ifá consultó para Mágbàgbéọlá y le advirtió que ofreciera y tuviera mucho cuidado con las mujeres de sus amigos. No hizo caso: se llevó a una mujer casada de su casa a la de sus padres. Unos asaltantes desconocidos lo golpearon hasta matarlo en su propia casa, que quedó robada y casi destruida. Ifá pide a esta persona mucho cuidado con los amoríos y el adulterio."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El mono (rechazado): tres lanzas, tres gallos y 6,600 cauríes.", "La estrella (rechazado): una chiva y 2,000 cauríes.", "El Akápò: un animal del monte con cuernos grandes para Ifá.", "Mágbàgbéọlá (rechazado): ofrenda para no morir por una mujer ajena."]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè es el señor de la estrella. Ọ̀rúnmìlà y su Akápò, su ayudante, aparecen en el relato del animal de cuernos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Lanzas, animal de cuernos, chiva."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 38.1 (yorùbá): Kabẹkukutekurolonà- / karibipade-ijàpẹkipẹki: / li o dífá f'Akibola / hlos'oko àlorò odún. / Ó nlọ pa qmọ Oyi (obọ) / O mi a so awo rẹ kọ, / wọ̀n niki Oyi wa rú: / Ako-ofà mẹta, / akuko-adiyẹ mẹta / ati egbẹ̀talelọ̀gbọ̀n owó. / Ko rúbọ. / Wọ̀n paa.", "Verso 38.2 (yorùbá): Atorirorayo-llélaba-Irókò-ngbe: / li o difá fún Irawoṣaṣa, / tiiṣe erú Olódùmare / Wọ̀n ni: / \"bikobafiti Olúwa\" rẹ ṣe / ònà l yo pa ọlá mọọ lára\" / Ewúrẹ ati egbèwá owó li ẹbọ. / Irawą ko rúbo. / Nitorinaa ni ojo ti Olódùmarè / ba ro ti igberaga irawọ kan / liaṣe nrii ti irawo naa ṣidi lojüji / a si wọ ookun.", "REZO: OYEKUN PELEKA ADIFAFUN OKANA OYEYU OBARA YIRE WA OBINI AYE OLONU OGUTIYUN LARIFUHN LODI IKU OYEKU PELEKA.", "REZO: IDI FORISHE MOLEGU BABA ILINGUO AUN MODIA NO EIFE CAPADA KORIMIO LIRE META OTAPI BABARE LO CADAMO MOCHI ILUDEDE SAGUA LEGUA COCURI RE OLEDAO OBINI LO CON LOGUN ORUBO AKORDIE ETU MELLO, EKU, EYA, EWE JARA JARA ABEFA OWO.", "REZO: OYEKUN OKANA KARA AWO WITI EFAN AWO IBANA ADIFAFUN IMPEGUO OKARAN YAKUN IMPEGUO OKARAN WAMPO OMO OWO WAMPO LODE ADIE MEYI ELEBO OWO MEDILOGUN LA MESA UOSAN.", "REZO: ADIFAFUN OKANA YEKUN AGRIA BLENIRE IFA EGGUN AGUANI LOKUN LERI FIFESHU LERI EGGUN OKUA AKUARI EGGUN FIFESHU AOBANI OLOKUN OBANIRE ALAKUARA YALE OGUANI IFA OLOKUN IFA KAFEREFUN OLOKUN Y AAYE.", "REZO: OYEKUN PELEKA ADIFAFUN OKANA YEKU OBARAYIRE YA OBINI AYE OLONU OMO TITUN LARIFUN LODIKU OYEKUN PELEKA ADIFAFUN ELEKUN OMO BARAYAN OKANA YEKU OYEKUN PELEKA EGGUN EFU OBARADARASE NI ELEKUN OBAYEKU LARA LARA LAYEBAISHE SHELERI OYEKUN PELEKA OKANA YEKU MODAWA AMOYARE MOYARE YOYOUN LEKUN ELEKUN OMO LERIFUN LEDIFUN.", "REZO: ODARA BI OSHA OYE AWO OSHAKUNODA, OMO OSHA TIRO OFIN TOKUN AGBA ENI OSHA EYE EKUN SHINAYAKUA BABA ERIN, EFUN KAFUN TOLE AYE, EKUN OBANI BOSHE OSUN KAFUN TOLE ILEKE AWO LAYE EKUN, NIYE BABA ERIN OKE ENIFA OSHA BABA OSUN ASHE ORI BEWA, BABA NILEFUN OSHA ORI AGBANI BOSHE BABANIFA OLORUN EFUN LOWA, ORUN LOWA, OSUN AYEGBE ENI OSHA BABA OLOFIN LOWA AYEGBE ENI OBOLOYO YEMAYA LANIRE SHANGO BI OSUN BABANI IRAWO OBATALA BABA IROKE BOWAO OMO ONI AYE OSHA IFA NI KAFEREFUN OBATALA, KAFEREFUN SHANGO, YEMAYA, OSUN, LODAFUN ORUNMILA.", "REZO: ADIFAFUN OKANA YEKUN AGRIA BLENIRE IFA EGGUN AGUANI LOKUN LERI FIFESHU LERI EGGUN OKUA AKUARI EGGUN FIFESHU AOBANI OLOKUN OBANIRE ALAKUARA YALE OGUANI IFA OLOKUN IFA KAFEREFUN OLOKUN Y AAYE.", "REZO: ODARA BI OSHA OYE AWO OSHAKUNODA, OMO OSHA TIRO OFIN TOKUN AGBA ENI OSHA EYE EKUN SHINAYAKUA BABA ERIN, EFUN KAFUN TOLE AYE, EKUN OBANI BOSHE OSUN KAFUN TOLE ILEKE AWO LAYE EKUN, NIYE BABA ERIN OKE ENIFA OSHA BABA OSUN ASHE ORI BEWA, BABA NILEFUN OSHA ORI AGBANIBOSHE BABANIFA OLORUN EFUN LOWA, ORUN LOWA, OSUN AYEGBE ENI OSHA BABA OLOFIN LOWA AYEGBE ENI OBOLOYO YEMAYA LANIRE SHANGO BI OSUN BABANI IRAWO OBATALA BABA IROKE BOWAO OMO ONI AYE OSHA IFA NI KAFEREFUN OBATALA, KAFEREFUN SHANGO, YEMAYA, OSUN, LODAFUN ORUNMILA."]}]$q$::jsonb),
(39,'773947c000a1fce26d7c2524b76f0285',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ògúndá protege contra una muerte cercana. Un trabajo o una relación están por terminar a causa de pleitos emocionales. Pide cuidar la manera de hablar, porque una palabra descuidada puede destruir a la familia, y comportarse bien dentro de ella."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una relación o un trabajo está en riesgo por tensión y pleitos repetidos.", "Habla sin pensar y otros toman sus palabras como ofensa (relato de Òyè).", "Un desacuerdo familiar empieza a abrir distancia y conviene atenderlo pronto.", "Teme una pérdida grave que todavía se puede prevenir (verso de Ọ̀yẹ̀kú).", "Busca una vida más tranquila después de mucha lucha.", "Debe saber cuándo y cómo decir una verdad, sin callar por miedo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Pasar el día señalado sin que ocurra lo anunciado.", "Larga vida y felicidad.", "Que la conspiración contra él no se cumpla.", "Riqueza por saber hablar con cuidado."]}, {"titulo": "Ibi y advertencias", "puntos": ["Hablar sin cuidado y ofender sin querer.", "Faltas dentro de la familia que la pueden destruir.", "Pleitos que acaban con el trabajo o con la pareja."]}, {"titulo": "Enseñanza principal", "texto": "Si la pared no se abre, el lagarto no entra. Quien se sabe callar a tiempo no le da a nadie con qué usarlo en su contra. Ningún árbol alcanza el cielo: no es todavía la hora de nadie."}, {"titulo": "Relatos reunidos", "puntos": ["La muerte anunciada para cuatro días. Los adivinos consultaron para Ọ̀yẹ̀kú, a quien le habían anunciado la muerte en cuatro días. Le marcaron un carnero; cumplió. Llegó el día señalado y no pasó nada; desde entonces no se conoce el día de la muerte de Ọ̀yẹ̀kú.", "La pared que se abre. 'Por donde la pared se abre entra el viento.' Así consultaron para Ọ̀yè, hermano de Ojóòmódá, y le advirtieron que cuidara su manera descuidada de hablar: 'Si la pared no se abre, el lagarto no entra; cuida que tus palabras no destruyan a tu familia'. Al escucharse a sí mismo, ofreció, y su vida mejoró: 'Mi manera cuidadosa de hablar me hará rico'.", "El árbol que no toca el cielo. Ọ̀yè preguntó si viviría mucho y sería feliz. Le dijeron que sí, que ofreciera un chivo viejo, y que muchos conspirarían contra él pero su plan no se cumpliría. Ofreció y dijo: 'Todavía no es la hora de mi fin; ningún árbol podrá tocar el cielo'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀yẹ̀kú: un carnero.", "Ọ̀yè (larga vida): un chivo viejo.", "Ọ̀yè (palabra): ofrenda para cuidar lo que dice."]}, {"titulo": "Relaciones espirituales", "texto": "La familia es el espacio que se cuida con la palabra. Ikú, la muerte, pasa de largo ante quien ofreció."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Carnero, chivo viejo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 39.1 (yorùbá): Eni l'qjà Ewọn, / Ờla lọjà Owe: / li o difá f'Ọ̀yẹ̀kú / tii wọn nfi qjọ ikú rẹ / da piriti (ojẹ mẹrin). / Wọ̀n niki ó rú / Agbo kan / Ó gbọ̀ ó rú. / Qjọ ti wọn nda koipe / Imọ ikú awo koijọ'ra.", "REZO: OYEKUN TEKUNDA LOBINA NASA OYO OPA OTA KUKU WORA ADIFAFUN ABEREGUE LUBA OMO ORUNMILA KOBA OGGUN TITIWO BEBERE OLOTURA AGOGO LABINIKU TENIYE EWE OGUMA IFA NI OTA OJOJO EBBO ADIE, EKU, EYA, OWO TETEBORU.", "REZO: OYEKUN OGUNDA INTORI ARAYE KAFEREFUN OSHUN OLOFIN ESHU AKATA BOMI OMI AMUOKOTE MOSU SOYO OSHE LOTI LOSE AUN OTA ORUNMILA OLOFIN DIRE LOFA ORUNMILA.", "REZO: INTORI EYELE NI LETE AWO IBASEN BONO NO LOLO ERO LOMBA TUMBA AWO RERE NI ADIFAFUN TOBO SHIWI IFA OWUNKO ODDUNDE ASHO TELEDI INTORI OKUNI ILE LONA, LODAFUN OBATALA.", "REZO: INTORI ARAYE EYELE LEBO INTORI IGUABOBO AGUTAN LEBO ORUNMILA IFAYOKO LODAFUN EGGUN AYAKA.", "REZO: ORUNMILA ADIFAYOKO OGGUN AYAKA.", "REZO: APATO MABIRAN AQUITE MABIBELLI EFIN ABILOGUE SHAUNDATI LARE ILISHU RANIPO ARDE MAMAKE BABA SHIKE IGUIORIBE OLLOKU TEGUNDA LOBINA NASA TITI GUO LELERE ELETURA AGOGO LEBO LEOBABEBINKA TENULLA OGUOAGUMA IFANI OTA OFOFO LEBO OKU EYA.", "REZO: OYEKUN OGUNDA INTORI ARAYE KAFEREFUN OSHUN OLOFIN ESHU AKATA BOMI OMI AMUOKOTE MOSU SOYO OSHE LOTI LOSE AUN OTA ORUNMILA OLOFIN DIRE LOFA ORUNMILA.", "REZO: INTORI EYELE NI LETE AWO IBASEN BONO NO LOLO ERO LOMBA TUMBA AWO RERE NI ADIFAFUN TOBO SHIWI IFA OWUNKO ODDUNDE ASHO TELEDI INTORI OKUNI ILE LONA, LODAFUN OBATALA."]}]$q$::jsonb),
(40,'9065ea5a0670c4538853a9a3b065b63e',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀sá aconseja negociar, ceder y pactar antes de perderlo todo. Señala pleitos de pareja, de familia y entre compañeros que se resuelven con diplomacia. Ifá le desea victoria: ninguna guerra lo detendrá si ofrece, y las fortunas entrarán bajo su techo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Dos personas o grupos se pelean algo que podrían repartir (relato del elefante entre Olijede y Onitiyo).", "Una relación de pareja, familiar o de trabajo se volvió conflictiva y necesita negociarse.", "Teme perderlo todo por no ceder a tiempo.", "Busca prosperidad y continuidad familiar honrando a sus ancestros.", "Siente oposición y quiere superarla (relato de Ọ̀rúnmìlà).", "Puede arrepentirse de algo que sigue posponiendo (relato de la gente de Ogere-egbe)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Victoria; ninguna guerra lo detiene.", "Acabar con los pleitos usando la palabra.", "Que las fortunas entren bajo su techo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Pelear por algo que se puede repartir, hasta que se echa a perder.", "Arrepentirse por no ofrecer a tiempo.", "Creer que lo propio no se puede perder y descuidarlo."]}, {"titulo": "Enseñanza principal", "texto": "Lo que se pelea se pudre. El elefante muerto entre dos granjas se echó a perder mientras discutían, y al final Èṣù repartió el marfil. Ọ̀rúnmìlà acabó con las guerras con su estera: con la conversación."}, {"titulo": "Relatos reunidos", "puntos": ["La gente de Ogere-egbe. Ile-ẹwu-ab'ojuṣokoto consultó para la gente de Ogere-egbe y les marcó una jícara de vino de palma, cuatro palomas y 800 cauríes para no tener que lamentarse en la vida. No quisieron ofrecer.", "El elefante entre dos granjas. Un elefante murió en la granja de Olijede, pero la cola le cayó en la granja de Onitiyo. Los de Onitiyo dijeron que era suyo y los de Olijede también. Un elefante muerto entre dos granjas anuncia guerra. Les marcaron un chivo y 12,000 cauríes para que no pelearan por algo que se podía repartir. Tres meses después hicieron la ofrenda que habían ignorado; para entonces el elefante ya se había podrido. Èṣù repartió el marfil entre los dos y les aconsejó dejar de pelear.", "Ọ̀rúnmìlà acaba las guerras con su estera. El pájaro vuela moviendo las alas arriba y abajo y toca la tierra con el ala derecha, con un sonido como el de una azada o un machete al caer. Así consultaron para Ọ̀rúnmìlà, contra quien habían levantado una guerra. Le dijeron que aplastaría todas las guerras con su estera, con la conversación. Ofreció y venció toda confrontación, y dijo que nunca dejaría que la gente del mundo fuera detenida por la guerra mientras hiciera las ofrendas de Ifá.", "Kúkúnrú, el agua de la lluvia. Ifá consultó para Kúkúnrú, cuyos hijos eran todos hermosos, y le pidió ofrecer para que tuvieran lugares dichosos donde vivir y nadie les cerrara el camino. Kúkúnrú dijo que, una vez que se tienen hijos, nadie les puede negar la entrada a la vida, y no ofreció. Kúkúnrú es el agua que escurre de la lluvia: nadie la deja entrar en su casa, y si entra la sacan. Ya tarde, lloró: 'Ifá, no permitas que se pierda la fortuna'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogere-egbe (rechazado): una jícara de vino de palma, cuatro palomas y 800 cauríes.", "Olijede y Onitiyo: un chivo y 12,000 cauríes.", "Ọ̀rúnmìlà y para la victoria: un chivo viejo.", "Kúkúnrú (rechazado): ofrenda para el camino de los hijos."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù reparte lo que se disputa y aconseja la paz. Ọ̀rúnmìlà vence con la palabra, no con las armas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Vino de palma, marfil, estera, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 40.1 (yorùbá): Ile-ẹwu-ab'ojuṣokoto / li o difá fún wọn l'Ogere-egbe. / A niki wọ̀n wa rúbọ, / kiwọn ma baa ta'hun l'ayé: / Igbá iregbe-ògurọ̀, / ẹyẹlé mẹrin ati ẹgbèrin owó. / Wọ̀n kọ wọn ko rú.", "Verso 40.2 (yorùbá): Erin kus'oko Olijede, / Of'irusoko Onitiyo. / Àwọn ara ilu Onitiyo / ni àwọn li o ni Erin. / Àwon ara Olijede / ni àwọn li o ni Erin. / Erin ti o kus'oko Ọloja Méjì, ogun ni. / A niki wọn rúbọ / nitoripe wọn maa jüjadu lori / ohun kan bayi. / Öbúkọ ati ẹgbàáfà owó ni ebọ. / Lẹhin oṣu méta, / wọn wa rúbọ ti wọn kosilẹ. / Erin ti ra. / Eṣú wa pin ehin Erin naa / fún wọn li okookan / O niki ẹ ma jà mọ o.", "REZO: OYEKUN BIKUSA KUKUTE KUKI ADIFAFUN OGGUN ATI OSHOSI. DARIKO OYEKUN SA KAFEREFUN OYA, ORUNMILA ADIFAYOKO ALADAFA AWO ALADAFA OTOKE TOYO INA MEYI INYA LOWO ODSA NITO LOSUSHU KOMANDI KOLILU EDAN ATOKE TOYO ORUGBO AIKORDIE, AKUKO PUPUA ELEBO.", "REZO: KUKUTE KUKADIFAFUN OGGUN Y OSHOSI DARICO YOKUNSA KAFEREFUN OYA ORUNMILA ADIFAYOKO ALADAFA OWO ALADAFA ATOKEOYO OÑA MEYI INYA LOGUO ASONITO LASUSHU KOMANDIO LILU EDAN OLOKU ATOQUE TELLO ORUBO AIKORDIE AKOKO PUPUA.", "REZO: AGOI OMODE AZOWANO OMOLITASA TASA NIWA GUDU UNLO AZON MALITE OBINI ODARA OBEYAWO OKUNI OPOLOPO OWO ALAGBA AGBA ODARA NANU IYA BOGBO AZOWANU, ENIMO OTERI BASHO KUKUTONI LE ZANGBETO DAJONI NILE BABA EGUNGUN ORO AWO IKOFA AGOI ARIKU LODAFUN ORUNMILA, MAFEREFUN AZOWANU IKU.", "SUYERE: AGOI WIYEBO AGOI KOIYEWO BABA EGUNGUN, ONIFA ARIKU."]}]$q$::jsonb),
(41,'d90c81ced3f997cb63652044ced237fd',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìká habla de compartir las ofrendas con Èṣù y con las demás divinidades, porque eso garantiza la seguridad. La persona necesita poner más atención a lo espiritual y menos al dinero. Debe ofrecer lo que su Orí acepte para que lo bueno llegue a sus manos, y no envidiar el éxito de otros."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está tan metido en ganar dinero que descuidó otras responsabilidades o su vida espiritual.", "Se compara con alguien y la envidia daña la relación (relato de Ọ̀yẹ̀kú y Èká).", "Siente que no alcanza lo que esperaba de su destino (relato de Sàniyàn y Orí).", "Necesita consejo de sus mayores o ancestros antes de entrar en un conflicto.", "Una lectura mal interpretada puede traer daño (relato de Owá).", "Teme pérdidas y busca firmeza sin rebajarse ni dañar a otros."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Clientes, dinero y sabiduría para quien trabaja con honestidad.", "Ser salvado de las aguas por los gemelos.", "Una vida hermosa cuando se ofrece a la propia cabeza."]}, {"titulo": "Ibi y advertencias", "puntos": ["Envidiar al que prospera y querer hacerle daño.", "Interpretar mal una consulta y pagar las consecuencias.", "Descuidar lo espiritual por el dinero.", "Cobrar de más por una ofrenda."]}, {"titulo": "Enseñanza principal", "texto": "Solo Ọ̀rúnmìlà controla el destino a través de la ofrenda. Quien escoge su destino sin incluir la ofrenda escoge mal. Y el honesto prospera mientras el tramposo se queda solo con su rencor."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀yẹ̀kú, Èká y el balsero. Gbingbin erẹkẹ consultó para Ọ̀yẹ̀kú y para Èká, una rama, y les pidió ofrecer juntos dos gallinas, maíz y 3,200 cauríes. Ọ̀yẹ̀kú no ofreció. Los dos se fueron de viaje de adivinación: a Èká le fue bien y a Ọ̀yẹ̀kú no. Al regresar llegaron al cruce del río; Ọ̀yẹ̀kú llegó primero y le pagó al balsero para que tirara a Èká al agua. El mono (Ẹdùn) fue quien rescató a Èká: el agua nunca se lleva al cangrejo.", "Cómo Èṣù recibe la primera porción. Ọ̀yẹ̀kú y Èká consultaron para Owá, que preguntaba por las mujeres estériles de su casa. Interpretaron mal la consulta, y Owá los mató a los dos en un cruce de caminos. Kokofakokoyẹrẹ, que es Èṣù Ọ̀dàrà, bajó del cielo, arrancó una hoja, se la frotó en los ojos y en la cabeza, y cantando los levantó. Los llevó con Owá, y esta vez le dijeron bien: lo que quería era que sus mujeres quedaran embarazadas, y si no ofrecía ese mismo día moriría. Owá ofreció. Repartieron los materiales y le dieron a Èṣù su parte. Èṣù dijo que no sabía cuánto sufrían los babaláwo, que seguiría ayudándolos, pero que en adelante él tomaría la primera porción de toda ofrenda. Desde ese día los babaláwo comparten con Èṣù lo que se ofrece.", "Sàniyàn y su destino. El buitre se posa en lo alto y desde ahí ve la ciudad y el bosque. Así consultaron para Sàniyàn, esclavo del destino en el cielo. Cada quien escoge lo que será al venir del cielo a la tierra, y él preguntó qué debía hacer. Le dijeron que solo Ọ̀rúnmìlà controla el destino a través de la ofrenda, y que cualquier destino escogido sin ofrenda sale mal. Le mandaron ofrecer a su cabeza. Lo hizo y su vida se volvió hermosa.", "Ìká el honesto y Ọ̀yè el tramposo. Ọ̀yè fue a ejercer la adivinación en la ciudad de Ìká, donde Ìká ya trabajaba desde hacía tiempo. Ìká era honesto: si una ofrenda costaba ocho cauríes, cobraba ocho. Ọ̀yè mentía, y todo lo que hacía le salía mal. Ìká se hizo muy rico en clientes, dinero y sabiduría, y Ọ̀yè se llenó de rencor. Un día Ọ̀yè retiró el tronco que servía de puente, esperando que la corriente arrastrara a Ìká para quedarse con su dinero. Pero Ìká, al que también llamaban Oníkàá, había ofrecido muchas mazorcas de maíz a los gemelos, que lo habían hecho rico; cuando lo vieron ahogándose, se echaron al agua y lo sacaron con vida. Canto: 'No dejes que el príncipe de los babaláwo se ahogue en el agua del odio'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀yẹ̀kú y Èká: dos gallinas, maíz y 3,200 cauríes.", "Owá: doscientos de cada cosa; la primera porción para Èṣù.", "Sàniyàn: ofrenda a su Orí.", "Ìká: muchas mazorcas de maíz a los gemelos."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù Ọ̀dàrà resucita a los adivinos y recibe desde entonces la primera porción de toda ofrenda. Orí y Ọ̀rúnmìlà deciden el destino. Ìbejì, los gemelos, salvan al honesto."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Maíz y mazorcas, hojas de Ifá, gallinas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 41.1 (yorùbá): Gbingbin ẹrẹkẹ awo eti odò / li o ṣe Ifá fQyèkú, / o bu fún Ẹ̀ká kan / A niki awọn mejeji wa rúbọ: / Agbebo-adiyẹ Méjì, igbàdo / ati ẹgbèrindilógún owó. / Ọ̀yẹ̀kú ko rúbọ.", "Verso 41.2 (yorùbá): Aderomokun awo ode ljeṣa, / Adebori awo ode Çabá, / Kokofakokgyprẹ-o-bawon-pin-eru- / l'ogboogba-ọ̀run-niith-wa, / li a pe Éṣü-Ọ̀darà.", "REZO: OYEKUN OYEWODELAKA ADIFAFUN OYEKUN ADIFAFUN IKA. OYEKUN BIKA ALAKE EDON ADIFA OYE OKA NOGBATI TIN ISOPO KUN EKU, EYA TIO LA SHAWO.", "REZO: IFA NIRE ERE AWADO OMO OLOFIN OMONI SHANGO ABURA IÑA OLOTE MEYA ADIFAFUN ORUNMILA, LODAFUN IBEYI ORU EDUN LOBAYE EGGUN ABURE ÑAÑIRE AWO ITUTO BILAYEO NI IFA KAFEREFUN OLOFIN AWO ELE TTUTU MOSHE OBANI YEKUN ELLA NIRE OLOFIN Y ORUNMILA.", "REZO: LEJE EL LERI OKURIN OROGBO IGBA DUDU ELEJE OKANA IKU BIÑI.", "REZO: OYEKUN BIKA LERI MESAN ABALODO AWO ILE GUNGUN ELEMARE EGGUN AWO KORO IWA EGO KAFEREFUN ASHEDA, KAFEREFUN OPA IGUI LERI MESAN.", "REZO: OYEWODE LAKA ADIFAFUN OYEKUN ADIFAFUN IKA OYEKU BIKA ALAKE EDON ADEFA OYE UN OKA WATI FIN WOSHOKUN TROLA SHAWO.", "REZO: OYEKU BIKA LOMI OLASHO ORUNMILA AWAKAN MADAJUN OJO ORUKO OBI ISHEYI SOROPE ORONIA JUN OLORI BURUKU OFI ORIYA IGUI ODIOLODI OFI ISHEWE LU IGUI YUBU.", "REZO: IGBA, 41 CARACOLES, ORO, PLATA, COBRE, BRONCE, ESTAÑO, PLOMO, PLATINO, HIERRO, MARFIL, ALGODON QUE SEA DE LOS SANTOS OLEOS, ERO, KOLA, OBI, OSUN, ORUGBO, IYEFA, IGUI PEREGUN, 4 KOIDE, OTI, EPO, EFUN, ASHO FUN FUN, ASHO DUN DUN, PUPUA, OÑI , OPOLOPO OWO.", "SUYERE: OLAÑO OLAÑO OUN OTA EWE BARA OLAÑO OLAÑO OUN OTA EWE BARA.", "SUYERE: IKUTOPA OJUBA ONOPOWO. SUYERE:", "OJO OWORO TIBI OLOWO NINU OLOWO GOLOTO IMOFA GELOTO OJO OJO ASHE IMEFA NONI OKO ISHERODO YON A MA NONWO YON A MA NO RA.", "REZO: IFA NIRE ERE AWADO OMO OLOFIN OMONI SHANGO ABURA IÑA OLOTE MEYA ADIFAFUN ORUNMILA, LODAFUN IBEYI ORU EDUN LOBAYE EGGUN ABURE ÑAÑIRE AWO ITUTO BILAYEO NI IFA KAFEREFUN OLOFIN AWO ELE TTUTU MOSHE OBANI YEKUN EYA NIRE OLOFIN Y ORUNMILA.", "REZO: AKIKARA IGBA IMIYA MUYA EGU AWO OYEKUN BIKA OMOLU SOYAYA ILE OKOKON BOROMU BOLELE DE MI BASHEYA KOFIBORI IÑIRI EYA KAFEREFUN BOROMU ADIFAFUN SOYAYA.", "REZO: LEJE EL LERI OKURIN OROGBO IGBA DUDU ELEJE OKANA IKU BIÑA.", "SUYERE: IKUTOPA OJUBA ONOPOWO.", "REZO: OYEKUN BIKA LERI MESAN ABALODO AWO ILE GUNGUN ELEMARE EGGUN AWO KORO IWA EGO KAFEREFUN ASHEDA, KAFEREFUN OPA IGUI LERI MESAN.", "SUYERE: “BABA LERI IKU MESAN, LERI IKU OPOLOPO LERI IKU ASHEDA LERISO LERI YEKUN BIKA OYEKUN AZONA”.", "REZO: OYEWODE LAKA ADIFAFUN OYEKUN ADIFAFUN IKA OYEKU BIKA ALAKE EDON ADEFA OYE UN OKA WATI FIN WOSHOKUN TROLA SHAWO.", "REZO: OYEKU BIKA LOMI OLASHO ORUNMILA AWAKAN MADAJUN OJO ORUKO OBI ISHEYI SOROPE ORONIA JUN OLORI BURUKU OFI ORIYA IGUI ODIOLODI OFI ISHEWE LU IGUI YUBU.", "REZO: IGBA, 41 CARACOLES, ORO, PLATA, COBRE, BRONCE, ESTAÑO, PLOMO, PLATINO, HIERRO, MARFIL, ALGODON QUE SEA DE LOS SANTOS OLEOS, ERO, KOLA, OBI, O SUN, ORIGBO, IYEFA, IGUI PEREGUN, 4 AIKORDIE, OTI, EPO, EFUN, ASHO UN FUN, ASHO DUN DUN, PUPUA, OÑI, OPOLOPO OWO."]}]$q$::jsonb),
(42,'9befb195b434f20e96c8563a527b0022',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Òtúrúpọ̀n da la posibilidad de evitar el castigo por malas acciones, pero exige buena conducta en adelante. La persona enfrenta problemas legales, muchas veces con el gobierno. Se queja de que su éxito se retrasa: si ofrece, será respetado y admirado, y vencerá a la muerte, la enfermedad y las pérdidas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un problema legal o de trámites y necesita actuar con responsabilidad y buena asesoría.", "Debe reparar una falta anterior o pedir perdón.", "Hay un acuerdo de dinero oculto o confuso que conviene aclarar (relato de Aribijo).", "Ha trabajado sin reconocimiento y se impacienta (relato del tambor Dùndún llamado al palacio).", "Se siente amenazado por pérdidas o enfermedad (canto de Ọ̀rúnmìlà ante los ajogun).", "Un pleito largo le está afectando y se puede aliviar hablando y tomando decisiones concretas."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ser perdonado en un problema legal.", "Que lo llamen de un lugar importante sin esperarlo.", "Respeto y admiración.", "Vencer a la muerte, la enfermedad, las pérdidas y los malos hechizos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Hacer acuerdos secretos de dinero.", "Problemas con la justicia o con el gobierno.", "Que los enemigos esperen verlo resbalar."]}, {"titulo": "Enseñanza principal", "texto": "Lo que se pacta de dinero se pacta a la vista de todos. Y frente a los que esperan nuestra caída, se baila: Ọ̀rúnmìlà llevó su ofrenda a Èṣù bailando y los ajogun se quedaron sin poder hacerle nada."}, {"titulo": "Relatos reunidos", "puntos": ["El rezo del perdón. Ọ̀rúnmìlà me perdonará, el que perdona me perdonará. Si el agua mata a una persona, se le perdona; si un rey mata a una persona, se le perdona. Ọ̀rúnmìlà, déjame ser perdonado en este caso, como la comunidad siempre perdona a la lluvia. Se ofrecen dos gallos y 1,200 cauríes, y se prepara un collar de protección: hojas de túdè molidas con iyẹ̀rosùn de este Odù sobre dos cauríes, envueltos con hilo de algodón.", "Aribijo y los acuerdos secretos. Los adivinos de la casa de Olúfọn consultaron para Aribijo, el hijo menor de Oke-Apa, y le aconsejaron no hacer nunca acuerdos secretos de dinero ni de nada: todo debía ser abierto y público. Le marcaron una chiva, una rata, un pescado, dos gallinas, vino, nuez de kola y 6,000 cauríes.", "El tambor Dùndún llamado al palacio. Nadie había invitado nunca al tambor Dùndún, porque no lo consideraban importante. Fue con el adivino y le marcaron una paloma vieja. Ofreció, y sin aviso lo mandaron llamar del palacio. Sorprendido dijo: '¿Yo? ¡Nadie me había llamado para oír mi música!'. Cantó: 'Hice la ofrenda de Ọ̀yẹ̀kú Òtúrúpọ̀n; todo lo bueno viene a mí y mi vida se ha vuelto fresca'.", "Ọ̀rúnmìlà baila frente a los ajogun. Ọ̀rúnmìlà estaba rodeado de enemigos y malos hechizos. Le pidieron ofrecer contra la muerte, la enfermedad, la pérdida y todos los ajogun que lo vigilaban esperando atacarlo. Ofreció un chivo, y al llevar la ofrenda a Èṣù le dijeron que fuera cantando y bailando, porque esperaban que resbalara y se matara. Cantó: 'Muerte, déjame bailar para tu asombro; enfermedad, déjame bailar; pérdida, déjame bailar'. Todos lo miraban sorprendidos. Èṣù tomó la ofrenda y la repartió entre los ajogun; ellos comieron, y desde entonces Èṣù es el jefe que reparte la comida entre los ajogun. Una vez que comen, no pueden hacer nada contra quien ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Perdón: dos gallos, 1,200 cauríes y collar de túdè con iyẹ̀rosùn sobre dos cauríes envueltos en hilo de algodón.", "Aribijo: una chiva, una rata, un pescado, dos gallinas, vino, nuez de kola y 6,000 cauríes.", "Dùndún: una paloma vieja.", "Ọ̀rúnmìlà: un chivo padre llevado a Èṣù bailando."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù es el jefe que reparte la comida a los ajogun (muerte, enfermedad, pérdida, problemas). Ọ̀rúnmìlà es el que perdona."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Túdè, iyẹ̀rosùn, hilo de algodón, nuez de kola, vino."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 42.1 (yorùbá): Ọ̀rúnmìlà fi'hun jimi, / Ojiji fi'hun jimi, / Bi Omi bapọ'ni wọn a fi jii. / Bi Ọlojà ba pọ'ni wọn a fi jii. / Bi Ọba ba pọni nse ni wọn fi jii. / Ọ̀rúnmìlà! Ki wọn fỌ̀ràn yi jimi. / Gbogbo ilú nii f'oràn ji Eeji. / Akuką Méjì ati egbèfà owó lẹbọ.", "Verso 42.2 (yorùbá): Oyin-wọnyinwonyin awo ilé Olüfon, / Ibarajuba-Ibarajuba awo ilé Olüfon, / a difá f'Aribijo / Lipe gmokunrin Oke-Apa. / A niki ó ma yan ipinhun* ikpkọ̀ / kioma yan ti ibaba laelae. / Gbamgba-gbamgba / niki o yan ipinhun owó. / Ewarg, eku, eja, / agbebo-adiyẹ Méjì, oti, obi / ati ggbẹtalélógbọ̀n owó li ebọ̀.", "REZO: OYEKUN BATRUPON IFA NI UNLOSILE ILARE LOKIN ILARE OBINI PAMI KAFEREFUN ORUNMILA OBARABANIREGUN OLOFIN.", "REZO: ADIFAFUN SHANGO OBA SALAMANO INLE OGGUN OPA ENI BELE BELE BEKE ILE IKU MAWANI AWO ASARE AWO FILANI OZAIN ODARA AWO ILEKUN, AWO FILANI OZAIN ODARA AWO ILEKUN, AWO FILANI KOKE UNSORONITITONI SORO EGGUN, LODAFUN OBATALA.", "REZO: IFANI UN LOSINE ILARE YEKUN YAREDO PAMI MEFEREFUN OLOFIN Y ORUNMILA OBARABO NIREGUN.", "REZO: IFA ILARE, OKUN UNYE KUBAONA AKASHE EKO OBI META INTOGGUN UMBAWA OTUKA OLUO AKOPOLA.", "REZO: ADIFAFUN SHANGO OBA SALAMANO INLE OGGUN OPA ENI BELEBELE BEKE ILE IKU MAWANI AWO ASARE AWO FILANI OZAIN ODARA AWO ILEKUN, AWO FILANI OZAIN ODARA AWO ILEKUN, AWO FILANI KOKE UNSORONITITONI SORO EGGUN, LODAFUN OBATALA."]}]$q$::jsonb),
(43,'c8ef83c6a8d7a83e45655573221a6c35',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Òtúrá habla de quitar la culpa de encima y recuperar la libertad. Los asuntos legales se resuelven y se vuelve a disfrutar la vida social. Pide no ser tacaño con nadie, sobre todo con la comida, y no ser violento con la pareja, porque ella le traerá una gran fortuna."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Enfrenta una acusación, una crítica o un trámite y busca que se aclare su situación (relato de Ṣoràngun).", "Un pleito le limita su vida social y sus actividades de siempre.", "Las relaciones se tensan por orgullo o egoísmo y necesitan otra forma de hablar.", "Hay un tema de matrimonio o de acuerdos de pareja (relato de Oni-alakan-esuru).", "Busca orientación espiritual para mejorar su conducta y su trato con los demás."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Salir libre de un gran problema.", "Dos esposas en un día; una pareja estable para siempre.", "No enfermarse.", "Volver a ver con vida a personas que están lejos."]}, {"titulo": "Ibi y advertencias", "puntos": ["La tacañería, sobre todo con la comida.", "La violencia con la pareja.", "Dejar que otros pasen hambre teniendo de comer."]}, {"titulo": "Enseñanza principal", "texto": "Ifá advierte con fuerza: si se tiene comida, no se deja pasar hambre a quien la necesita. Quien comparte con generosidad conserva a su pareja y su fortuna."}, {"titulo": "Relatos reunidos", "puntos": ["Ṣoràngun sale libre. Ifá consultó para Ṣoràngun y le aconsejó ofrecer para salir libre de un gran problema. Le marcaron dos gallos, una rata igbégbé, hojas de gbégbé, 2,600 cauríes y medicina de Ifá: envolver la rata con ocho hojas de gbégbé y enterrarla en el monte.", "Dos esposas en un día. Los adivinos consultaron para Ọni-alakan-esuru, que tendría la fortuna de casarse con dos esposas en un día. Le marcaron dos gallinas y 1,600 cauríes. Cumplió.", "Ọ̀yè, esposo de Òtúá. Ifá consultó para Ọ̀yè, que iba a ser esposo de Òtúá, y le pidió ofrecer y no ser tacaño con la gente, sino regalar comida. Ofreció y repartió harina de ñame en abundancia; todas las ancianas hambrientas se acercaron y él les dio hasta que se saciaron. Ọ̀yè fue esposo de Òtúá hasta el final de sus días y su vida fue placentera.", "La kola que se comparte. Pákúdidi y Pàkùdidi vivían en el mismo lugar sin haberse visto cara a cara. Así consultaron para Ọ̀yè, que iba a traer nuez de kola de Òtúá a su casa, y le pidieron ofrecer para no enfermarse, porque su fortuna estaba llegando. La gente le cantaba: 'Ayúdanos, Ọ̀yè, danos nuez de kola'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ṣoràngun: dos gallos, rata igbégbé, hojas de gbégbé, 2,600 cauríes y medicina de Ifá.", "Ọni-alakan-esuru: dos gallinas y 1,600 cauríes.", "Ọ̀yè: harina de ñame (èlùbọ́) repartida en abundancia.", "Para la salud: ofrenda por las personas que están lejos."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá es quien libra de la culpa. Las ancianas reciben la comida del generoso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Gbégbé, rata igbégbé, harina de ñame, nuez de kola (pákúdidi)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 43.1 (yorùbá): Ọropọto: / li o difá fún Ṣoràngun, / a niki ó rúbo / kioba leṣe ràn naa gun. / Ebọ: Akuko-adiyẹ Méjì, / eku igbégbé8o, / ewé gbégbé, / ẹgbẹtala owó / ati ewé Ifá. / Ọropotọ:", "Verso 43.2 (yorùbá): Iyán-bi-atungun, / Ọbẹ-bi-atunse, / Okelegbongbo-di-atunbu-baálé: / wọ̀n dífá f'Qni-alakan-esuru, / nigbati o maa rire aya Méjì loojo. / Wọ̀n niki ó rú: / Agbebo-adiyẹ Méjì / ati egbăájo owo. / Ô gbọ̀ ó rú.", "REZO: OYEKUN TESIA AKIKI OLORUN OBI LOLUN MATI BIBIKOUGUN AWO APIGUMI WATA ORUNMILA AKINE IDILA SARA AKUKO ABELO WO ELEBO.", "REZO: OYEKU TESIA AKIKI OLORUN INIBOLON MATIBIBI KONGU OWO APIGUNI GUATA ORUNILA AGUINO IDILA SARA AKUKO ABELO GUE.", "REZO: LLEBO NIBUNI ADIFAFUN ERONI MOYELE TINTIATE OMO OLOKUN NIFA EBBO ADIE RE ELEGBA AKUKO.", "REZO: EKARU EKARU OMILE LODAFUN ORUNMILA INTORI OMO ADIFAFUN OLOKUN ADIFAFUN SHANGO.", "REZO: UWOYUJO OMINO ADIFAFUN OBATALA OSHEREGBO UMBOBO UMBATI OMARE.", "REZO: OYEKUN OTURA ASIA ADIFAFUN OMOLOKUN OZAIN OLORUN YODA ORI INLE MABA DA LEYA OBANSHE LERI OMA ARONI MEYEYE OWA OLOKUN ORUNMILA NIFA OMA OBAYENI AWO AUM ORIKANI META BENI LAYE OMO OBAYANI AUM AWO AKINKUN OLO ORUN ABIBO MARAYELENI AWO OLO ABIBO GONGO ORUN ADIFAFUN ISHENI OBAYE LODAFUN ORUNMILA Y OLOFIN.", "REZO: EKARU EKARU OMILE LODAFUN ORUNMILA INTORI OMO ADIFAFUN OLOKUN ADIFAFUN SHANGO.", "REZO: UWOYUJO OMINO ADIFAFUN OBATALA OSHEREGBO UMBOBO UMBATI OMARE.", "REZO: OYEKUN OTURA ASIA ADIFAFUN OMOLOKUN OZAIN OLORUN ODA ORI INLE MABA DA LEYA OBANSHE LERI OMA ARONI MEYEYE OWA OLOKUN ORUNMILA NIFA OMA OBAYENI AWO AUM ORIKANI META BENI LAYE OMO OBAYANI AUM AWO AKINKUN OLO ORUN ABIBO MARAYELENI AWO OLO ABIBO GONGO ORUN ADIFAFUN ISHENI OBAYE LODAFUN ORUNMILA Y OLOFIN."]}]$q$::jsonb),
(44,'2325df158a3b904e7ddf6285e85b1612',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ìrẹtẹ̀ trae solución para la enfermedad: la persona o alguien de su casa está o estará enfermo. También habla de una mujer que desea hijos aunque le digan que ya es mayor, y de dos personas que planean ir a un lugar y deben ofrecer para que una no se acomode a costa de la otra."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Alguien de la casa está enfermo y la familia busca apoyo (relato de la familia de Kuṣeru).", "Una persona sigue como si nada aunque hay señales que piden atención.", "La familia necesita organizarse para cuidar sin paralizarse por la preocupación.", "Con determinación y decisiones a tiempo, el cuidado puede salir adelante."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Recuperación de un enfermo de la casa.", "Hijos para una mujer a la que creían demasiado mayor.", "Establecerse y multiplicarse en un lugar nuevo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enfermedad que hincha el cuerpo; conviene atenderse con el médico además de la ofrenda.", "Llegar primero y creerse dueño sin ofrecer.", "Que uno se acomode a costa del otro."]}, {"titulo": "Enseñanza principal", "texto": "No basta con llegar primero. La hierba Èèsún tomó el mejor terreno sin ofrecer y el hombre la cortó; la caña de azúcar ofreció su machete y la dejaron crecer."}, {"titulo": "Relatos reunidos", "puntos": ["El joven de la familia Kuṣeru. Los adivinos consultaron para la familia Kuṣeru y vieron a un joven, antes delgado, al que una enfermedad le había hinchado manos, piernas, ojos y nariz. Ifá dijo que se recuperaría si ofrecían cuatro palomas, 44,000 cauríes y medicina de Ifá: corteza del árbol ayẹ, hojas de asunrun, mucha sal y chiles rojos pequeños, hervidos en una olla, para bañarse y beber.", "Ìyálóde Òpò, la que creían vieja. Ìyálóde Òpò lloraba porque no tenía hijos y la gente decía que ya era muy mayor. Le marcaron una gallina que ya hubiera sido madre, una rata y un pescado ahumado. Ofreció, y al poco tiempo quedó embarazada y después tuvo muchos hijos. La gente cantaba: '¿Quién tiene tantos hijos? La que llamaban anciana'.", "La hierba Èèsún y la caña de azúcar. Èèsún y la caña buscaban tierra pantanosa donde vivir, y a las dos les pidieron ofrecer. Èèsún llegó primero, escogió una gran porción sin ofrecer y dijo: '¿Quién me va a sacar de aquí?'. La caña ofreció un machete y se estableció en la misma tierra. Con el tiempo las dos se multiplicaron. Cuando el hombre llegó, tomó el machete de la ofrenda, cortó toda la hierba por dañina y de la caña solo tomó unos trozos para calmar su sed, dejándola crecer porque vio su beneficio."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Kuṣeru: cuatro palomas, 44,000 cauríes y medicina de corteza de ayẹ, hojas de asunrun, sal y chiles, para baño y bebida.", "Ìyálóde Òpò: una gallina que ya haya sido madre, una rata y un pescado ahumado.", "La caña de azúcar y las dos personas que viajan: un machete cada una."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá cura a través de la medicina de hojas. La Ìyálóde es la jefa de las mujeres de la ciudad."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ayẹ (corteza), asunrun, sal, chiles rojos, caña de azúcar, hierba èèsún."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 44.1 (yorùbá): Afinjuyẹle, / Okùnrùn-kojẹkẹwàfuyi, / Awowonsàn awo wọn ni'le Kuṣeru: / li o difá fún Kuṣeru. / Wọ̀n ni: / \"omokunrin kan wa ni ilé rè. / O ti tẹẹrẹ ri, àrùn kan kọluu. / O kun lọwọ̀, o kun lẹsẹ, ojú ati imu\". / A niki ó wa rúbo. / Ifá a woosan. / Ẹbọ: Ẹyẹlé mẹrin, ẹgbàá méjilélógún owó ati ewé Ifá", "REZO: OYEKUN BIRETE MOLALA AWO MOLALA INTORI IFA ARUN MOLALA ABE OYU LAYE TINSHORE IFA OLOWO-POPO MOLALA AWO TINSHORE IFA OSHE OSHANLA IFA MOLALA NI YABE OTARENI IFA MOYARE NI LAYE MOLALA.", "REZO: OWO ADA ADIFAFUN IBINO NIRUBO ADIFAFUN ERU NILLO IBEYO OBUOMELLO MAFEREFUN BABALU AYE.", "REZO: OPO CURETA ADIFAFUN ESHU BATILOMBIBE ACOSHE EYELE EMENI OWO KAFEREFUN AGRINIKA ENI BABALAWO KIROSHILE NIKA.", "REZO: OYEKUN IRETE ADIFAFUN BABALU AYE KONIBO ESHI TETAN OBATALA, EPO AKUKO, KOLONI, EIYOKO, OWO LA MERIN ADIFAFUN ADA ADANIBI AYALUBERI ETUFO EYELE MEYI, ORI, OWO LA EPO KARETE ADIFAFUN ESHU UMBALE VIE.", "REZO: OYEKUN IRETE MOLOLA AWO MOLOLA INERI ARUN MOLOLA ABE EYULELE EYU LERUN TINSHORE IFA MOYARE BE IFA ORANLA MELALA NI YABE OTORONI IFA MOYARE NILAYE MOLOLA NI SHANGO YOROBO FUN BORI BEKUN INTOBI AWO MOLOLA.", "REZO: OYEKUN BIRETE YANA YANA IFA ABELEYERE IFA OBO ODEDI ESHUN Y AYOBI ETA AGUA YEBA ARA EYEKU LOKUN ABONISE SHANGO AWO OBAYOBI AWO OYEKU BIRETE BAYA BAGUARA BABARA ABAYEKU OLUO POPO OYEKUN IRETE OMO EWE YEKUN NI SHANGO A IÑA.", "REZO: OYEKUN IRETE MOLOLA AWO MOLOLA INERI ARUN MOLOLA ABE EYULELE EYU LERUN TINSHORE IFA MOYARE BE IFA ORANLA MELALA NI YABE OTORONI IFA MOYARE NILAYE MOLOLA NI SHANGO YOROBO FUN BORI BEKUN INTOBI AWO MOLOLA. INTORI ARUN GIN GUN:"]}]$q$::jsonb),
(45,'48e004e4269655ba2983ceaad1762c1d',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ọ̀ṣẹ́ explica que la muerte es parte del ciclo que renueva el orden natural. La persona se resiste a aceptar el final de una relación, de una etapa familiar o de un negocio. Ifá le desea lo mejor: se volverá alguien importante en el lugar al que viaja con frecuencia, y tendrá un nombre grande."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le cuesta aceptar el fin de una relación, un negocio o una etapa familiar.", "Vive un duelo o se pregunta por el sentido de la muerte (relato de los sabios y el agua que fluye).", "Desea hijos o continuidad familiar (relato del sapo Òpòló).", "Quiere establecerse y dejar un nombre respetado (relato del árbol Àràbà).", "El deseo de tener algo no le deja ver un cambio necesario.", "Llegar a un lugar nuevo puede abrirle una posición importante."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos robustos y numerosos.", "Un nombre grande y respetado que se perpetúa en la familia.", "Volverse importante en el lugar al que viaja.", "Sobresalir por encima de los demás."]}, {"titulo": "Ibi y advertencias", "puntos": ["Aferrarse a lo que ya terminó.", "Vivir con miedo a la muerte."]}, {"titulo": "Enseñanza principal", "texto": "El agua estancada se pudre y enferma; el agua que corre limpia y renueva. Así es la muerte en el orden del mundo: lo que no se va no deja lugar a lo nuevo."}, {"titulo": "Relatos reunidos", "puntos": ["Los sabios preguntan por la muerte. Varios adivinos consultaron para los sabios, que querían saber por qué la muerte mata a la gente y nadie se salva. Los babaláwo respondieron que Amuniwayé, que es Òrìṣà-ńlá, creó la muerte como algo bueno para la humanidad: el agua que no corre se estanca, se pudre y trae enfermedad; el agua que se deja correr se lleva la enfermedad de la casa y renueva el cuerpo y el carácter. Los sabios gritaron a Ifá: 'Ọ̀rúnmìlà, que la ofrenda sea aceptada'. Se dispersaron y nunca volvieron a ver a la muerte como un problema.", "El sapo y sus hijos. Ifá consultó para el sapo cuando lloraba porque no tenía descendencia, y le dijo que si ofrecía tendría hijos robustos y gordos. Ofreció, y empezó a tener crías que saltaban por todas partes. '¿Quién tiene tantos hijos? Solo el sapo'.", "El baobab en el bosque. Ifá consultó para el baobab (Àràbà) cuando iba a escoger tierra en el bosque y preguntaba cómo podría ser más grande que los demás árboles. Ofreció rápido; al establecerse creció por encima de todos, y los otros árboles preguntaban qué árbol era ese. Ifá dice que esta persona tendrá un nombre grande y honorable y que su linaje será respetado."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Los sabios: la ofrenda pedida por Ifá, aceptada (Iború, Iboyè, Ibọṣẹ).", "El sapo y el baobab: ofrenda para descendencia y grandeza."]}, {"titulo": "Relaciones espirituales", "texto": "Òrìṣà-ńlá, llamado Amuniwayé, creó la muerte como parte del orden. Ọ̀rúnmìlà recibe el grito de los sabios."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Baobab (Àràbà), agua que corre."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 45.1 (yorùbá): K'amatètèkú awo ilé Alayo, / Aitètèkú-iṣé awo wọn nile Ibànújé, / Bi-ikú-ba-de-ka-yin-Olúwa-logo / awo Igboya ewà / Alogbón-on-makú-ninú, / Maṣimale ninmẹyẹniyi / awo Afinju-makú-maṣe'bajẹ, / Öyẹkẹṣeniyi: / a difá f'àwọn Èniyàn ṣaṣa / ti wọn gbara jọ npe Babaláwo / wa difá ikú wope: / Eetiri ti ikú fi npo'ni ti kos'ẹnitikiikú? / Àwọn Babaláwo ni Ifá wipe: / Ire li Amuniwayé nfi Ikú ṣe. / Omi ti ko ṣan siwájú / ti ko pada s'ẹhin a d'ogodo, / Ọgodo omi ibajẹ. / Ọgọdo omi àrùn. / Omi ngbe wọn lo rerẹ, / Ọmọ nko wọn bọ rẹrẹ, / Olokunrun kare'le lọ gba Awotitun, / Aṣebajẹ kare'lé lọ gbiwa-titun bowa'yé. / Alasínwin ni nwo asíinwin san. / Àwọn Babaláwo ni: / Ewo ni ko dùn? / Awọn èniyàn foribalẹ fún Ifá-nwipe: / Ọ̀rúnmìlà! Iború, Iboyè, Iboṣẹ. / Wọn tuka lọ, / wọn ko tun gba ikú si ràn edun mo. / Oriṣà-ńlá liape ni Amuniwayé.", "REZO: OYEKUN PAKIOSHE OBI OSHEMA EYELEO KAMA SHERUWO ILE KENDE OMA FIRO OSHUN OBINI MEYI TANILO.", "REZO: NI MORE OYE PAKIOSHE EFU AGUATUN MELLA AFITORI MABO OSHE ASHUN KAODERU UMBA OKULA ABANI OMO LLOMO ARUN IKU LAMODI LOMBOLO LLUMU.", "REZO: OYEKUN PAKIOSHE NI MARI ALLO PAKIOSHER APAGUO OTRUN MELLO APOTARI MOBO OSHE OSHUPA ONDENI UMBAICA ABAN AMALLA MU ERU IKU LONDI TOUMBA IKU BOOMO LLUMU.", "REZO: ONI BIBE KORO GUAGUO ELA LAKAN AYAFO AKUKO LEBO OYEKUN PAONE NIMORE SIYO PAKIOSHE OJO OWO LA MELLO OFOSI MABO OSHUKA ODARU OMBAIKU LA ABAN OMO YOMILI ERU IGULANDI TOMBLE YOMU.", "REZO: ADIFAFUN BABARE ADAFUN ORUNMILA ESHU OSHUN Y EGGUN.", "REZO: ADIFAFUN BABARE ODO FUN ORUNMILA ESHU, OSUN Y EGGUN."]}]$q$::jsonb),
(46,'2c775124f819c2489e4d1d1fba7799de',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Òfún advierte de una enfermedad repentina y da protección contra ella. La persona enfrenta un obstáculo inesperado en su vida diaria o en el negocio. Pide ofrecer ñames, cuidarse de las burlas de la gente y que los hijos no sean soberbios con sus padres."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Surgió un obstáculo inesperado en el día a día o en el negocio.", "Tiene síntomas repentinos o teme enfermar (relato de Abaralile-oṣiṣẹ-oṣabą).", "Se siente a merced de cosas que no controla y busca tranquilidad.", "Hay tensiones en la familia por burlas, presunción o falta de respeto de los hijos a los padres (relato de Baálé y sus hijos).", "Quiere saber si su esfuerzo de hoy le traerá bienestar, recursos o hijos (relato de Èèyàn e Ìpín)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Recuperarse de una enfermedad repentina tomando la medicina.", "Fuerza, resistencia y paz mental.", "Larga vida para el padre y para los hijos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Una enfermedad repentina que puede dejar lisiado; conviene atenderse con el médico.", "Hijos soberbios con sus padres.", "Burlas de la gente."]}, {"titulo": "Enseñanza principal", "texto": "El destino tiene riquezas, pareja, hijos y todo lo bueno, pero se trabaja con la ofrenda. Y quien se niega a caminar junto al mal, el mal se le mete encima."}, {"titulo": "Relatos reunidos", "puntos": ["Abaralile, el que nunca se había enfermado. Los adivinos del bastón y de lo alto del estante consultaron para Abaralile, que nunca había estado enfermo, y le advirtieron que venía una enfermedad repentina que lo podía dejar lisiado. Le marcaron una babosa, un bagre, aceite de palma, 20,000 cauríes y medicina de Ifá. Ofreció. La enfermedad llegó de todos modos, pero tomó el remedio y se recuperó.", "El ser humano y los ñames. Pékótókótó, el adivino del vendedor de manteca de òrí, consultó para el ser humano, esclavo del destino en el cielo, y le pidió ofrecer ñames. Ofreció, y cada persona empezó a desarrollar músculos fuertes y una vida con más fuerza. Canto: 'Ven a ver el trabajo del destino: el destino tiene riqueza, tiene pareja, tiene hijos, tiene todo lo bueno'.", "El jefe de la casa y sus hijos. 'Ọ̀yẹ̀kú camina al lado de la muerte, Ọ̀yẹ̀kú camina al lado de la maldad; quien no le hace lugar al mal, el mal se le trepa encima.' Así consultaron para el jefe de la casa y para sus hijos, y les pidieron ofrecer para vivir mucho. Mientras el padre se traslada, los hijos pasean en sus caballos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Abaralile: una babosa, un bagre, aceite de palma, 20,000 cauríes y medicina de Ifá.", "El ser humano: dieciséis ñames; el babaláwo raspa la cáscara durante la ofrenda.", "El jefe de la casa y sus hijos: ofrenda por larga vida."]}, {"titulo": "Relaciones espirituales", "texto": "El destino (Ìpín) se trabaja desde el cielo con la ofrenda. Ifá da la medicina contra la enfermedad repentina."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame, babosa, bagre (ẹja aro), aceite de palma, manteca de òrí."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 46.1 (yorùbá): Adurogangan awo Ọpa, / Ayẹgiridanu awo orí pẹpẹ: / wọ̀n difá f'Abaralile-oṣiṣẹ-oṣabą, / eni àrùn kan koṣe ri, / Wọ̀n nì: / Àrùn kan nbọwa, àrùn öjiji, / àrùn naa yoo yeẹ ni'kun / Ó ni: kini ebọ? / A ni: igbin, eja-aro, epo, / ẹgbàáwa owó pelu ewé Ifá. / Ó gbọ̀ ó rú. / Àrùn naa de dandan, / ó mu qwó-ẹrọ, ó si sàn.", "REZO: OYEKUN BERDURA MAFUN ABA BARABA MAFUN ABA OFUN MAYEKUN FUN YANZAN LELE BERELE FOGUEREMALELE OYEKUN FUN MAFUN YEKU BERERE ORI OSHUN MERIYEYE MOLALA LALA YERI YALORDE MORIYEYEE LELE OSHUN BEBERE OKANA YELEGUE YELELE OYEKUN FUN YEYEBI OYA OMA YIRE AWO BADAWA. AWO OBA ERI IFA KAFEREFUN LERI IFA KAFEREFUN ELEGBARA.", "REZO: OYEKUN FUN IGUI AWO ILE ADO IRO AWO IKAURO AKOSHAMABA A OFE IBUNI ILE OYO SHANGO IBAURO ADIFAFUN OLOFIN UMBINA UNLO ARA OMODE LOMBO ADA ADIE IBUN EFUN EBEYI ORO AWO LOMBO EKU, EYA, EPO, EKO, OWO LAMEFA, OTUN, OSI.", "REZO: OYEKUN FUN OYEKUN BODURA IFA KUERIANO ODAFUN ORUNLA OLOKUN.", "REZO: BEBE AWO AFIBOYA LOGUE NITOSHE TOSHISHE BALERI YAGUN YAGUNANDIFAYESE KANFUN SHISHI LORAN OMO TINTUN MAFEREFUN OGGUN MAFEREFUN ARRIKUE OWA SHURIKUI UN SHOLA KOKO ARAYO ALA KAAKOLA AGUERE ALARA UNFUN BEROYANO ANDIFA FOYO LABEBE AFUN MUAA OLADE YOMOFUN MENI EYELE ADIFAFUN OSUN RONLORO INTORI OFO.", "REZO: KUKU ADIFAFUN AYO OKU TINSHOMA OLORDUMARE AKUKO LEBO IFA DE AROGIO.", "REZO: MAFUN AWO BABAGUA MAFUN AWO OFUN YANZA LELE BERELE FAGUERE MALELE OYEKUN FUN MAFUN YEKU BERERE ERI OSHUN MORI YEYEO MALEBE LALAYENI YALODE MORI YEYEO ABEJENA LELE OSHUN BIBERE OKANA YELEGUE YELELE OYEKUN FUN ESHU LARUFA OBA YEBE IKU, IKU OLORIN, AWO DAGUA NI OSHUN YEYEBI OYA OMAYIRE AWO MALAGUA AWO OBA ERI IFA KAFEREFUN LERI IFA KAFEREFUN ELEGBA.", "REZO: ESHU OWEREWI UNSHOLE KOKAROYO ALAGA OROKONLA AWERE ALOUN OFUN RERE YARU ADIFAYOKO OYETOURERE OFIN.", "SUYERE: OFUN MINI ALDEYANO (2 VECES)", "ADIFAFUN OSUN OLORUN (2 VECES)", "REZO: OYEKUN FUN IGUI AWO ILE ADO IRO AWO IKAURO AKOSHA MABA A OFE IBUNI ILE OYO SHANGO IBAURO ADIFAFUN OLOFIN UMBINA UNLO ARA OMODE LOMBO ADA ADIE IBUN EFUN EBEYI ORO AWO LOMBO EKU, EYA, EPO, EKO, OWO LAMEFA, OTUN, OSI.", "REZO: MAFUN AWO BABAGUA MAFUN AWO OFUN YANZA LELE BERELE FAGUERE MALELE OYEKUN FUN MAFUN YEKU BERERE ERI OSHUN MORI YEYEO MALEBE LALAYENI YALODE MORI YEYEO ABEJENA LELE OSHUN BIBERE OKANA YELEGUE YELELE OYEKUN FUN ESHU LARUFA OBA YEBE IKU, IKU OLORIN, AWO DAGUA NI OSHUN YEYEBI OYA OMAYIRE AWO MALAGUA AWO OBA ERI IFA KAFERE FUN LERI IFA KAFEREFUN ELEGBA.", "+++"]}]$q$::jsonb),
(47,'20a002e89b6d50fadaeb8848f6816170',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ogbè habla sobre todo de los hijos: hay que ofrecer para tenerlos y para mantenerlos sanos. Pide crear en la casa un ambiente alegre y de juego, porque la persona es demasiado seria y necesita divertirse para recuperar el equilibrio. También anuncia dinero, pareja, hijos y larga vida, y un amigo cuyo consejo hay que conservar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa la salud o el bienestar de un hijo y necesita apoyo de la familia (relato del niño enfermo).", "El ambiente en casa está muy serio o tenso y hace falta juego y convivencia.", "Hay una disputa que se arregla hablando con honestidad y escuchando a un amigo.", "Dos personas piensan hacer negocio juntas (relato de Ìwòrì y Ogbè en la casa de la riqueza).", "Busca dónde establecer a su familia o teme quedarse sin refugio (relato de las dos palomas y la tormenta).", "Una deuda ligada a una relación o a un proyecto le está presionando."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos y que sanen los niños enfermos.", "Dinero, pareja, hijos y larga vida.", "Riqueza que llega gota a gota hasta volverse abundante.", "Un buen negocio hecho en sociedad.", "Un amigo cuyo consejo lleva a buen destino."]}, {"titulo": "Ibi y advertencias", "puntos": ["Demasiada seriedad en la casa.", "Creerse a salvo sin ofrecer y perder a los hijos en la tormenta.", "Perder al amigo que aconseja bien."]}, {"titulo": "Enseñanza principal", "texto": "Los niños sanan comiendo y jugando con sus compañeros. Y quien ofrece se cubre en la tormenta: la paloma de la casa se tapó con la olla y salvó a sus hijos; la del monte, que no ofreció, los perdió."}, {"titulo": "Relatos reunidos", "puntos": ["La fiesta del niño enfermo. Ifá dijo que el hijo debía ofrecer para no morir: ñame machacado, una gallina y 3,200 cauríes. Mandó cocinar el ñame y la gallina, reunir a los compañeros de juego del niño enfermo y dejar que todos comieran. Si se le hace una fiesta con sus amigos, el niño sana.", "La paloma de la casa y la paloma del monte. Ọ̀ràn-bo'nilojúmabo'nininú consultó para la paloma de la casa y para la paloma del monte, que sufrían porque no tenían hijos. A las dos les marcó semillas de quimbombó, una carga de ñames, un bulto de ramas, una olla (ìkòkò) y 3,200 cauríes. La paloma de la casa cumplió y la del monte no. Las dos tuvieron dos crías, y la del monte presumía que sin ofrecer tenía hijos. Hizo su nido en un árbol; vino una tormenta, el árbol se arrancó de raíz y sus crías murieron. Desde entonces grita: 'Al primero y al segundo no los volví a ver'. La paloma de la casa dice: 'Nos cubrimos la espalda con la olla y no morimos'.", "Ọ̀rúnmìlà y los granos de sorgo. Ìwòrìgbogbè, el pájaro del campo, consultó para Ọ̀rúnmìlà, que se levantaba cada día quejándose de no tener dinero ni para lo poco. Le dijeron que la fortuna ya estaba con él, que ofreciera, y que lo bueno le llegaría gota a gota. Ofreció mucho sorgo y dinero, todo esparcido sobre el tablero de Ifá, y su vida se volvió placentera. Cantó: 'Riqueza, ven en abundancia; palomas de colores, vengan a comer sorgo'.", "Ìwòrì y Ogbè en la casa de la riqueza. 'Este camino incierto, revisémoslo juntos.' Así consultaron para Ìwòrì, que iba a encontrarse con Ogbè en la casa de la riqueza. Ogbè le aseguró que tendría riqueza si ofrecían juntos, y le propuso un negocio en sociedad. Lo hicieron y se toparon de frente con una riqueza inmensa, y luego con pareja e hijos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El niño enfermo: ñame machacado, una gallina y 3,200 cauríes, cocinados y comidos con sus compañeros de juego.", "Las palomas: semillas de quimbombó, una carga de ñames, un bulto de ramas, una olla y 3,200 cauríes.", "Ọ̀rúnmìlà: mucho sorgo y dinero esparcidos sobre el tablero de Ifá.", "Ìwòrì y Ogbè: ofrenda hecha en común."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá protege a los niños. Èṣù hace llegar la riqueza a quien ofrece."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame machacado, semillas de quimbombó, sorgo, ramas, olla de barro (ìkòkò)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 47.1 (yorùbá): Iworibogbè l jije. / İwòribogbè I mimu. / Ô niki wọ̀n mu oun ko omo, / ki ọmọ ma ba kú: / Iyán, agbebo-adiyẹ / ati ẹgberindilógún owó. / Ifá niki a se ohun jüjẹ ti òun wi yi, / ki a gba àwọn omodé wẹwẹ jo, / egbẹ omọ naa ti o nṣaisan yi / ki wọ̀n jẹẹ. / Iwòribogbè I jije.", "Verso 47.2 (yorùbá): Ọràn-bo'nilojúmabo'nininú: / li o difá fẸrukuku iléa / a bu fún t'oko. / Ìṣẹ́-ọmọ[87] li nṣe àwọn mejeji. / A niki wọ̀n rú: / Ilá, ẹru-iṣu, ẹru-igi, ikoko ati ẹgbẹrindilogún owó. / Ti ilé li o rúbọ ti oko kó rù. / Ti oko bi Méjì ti ilé bi Méjì. / T'oko I: oun kò sẹbọ bẹ òun bi / Ó lọ kọle sori igi egungun, / lji de, egungun wuṣi. / Gbogbo omo Frukuku-oko (adaba) kú, / Ó nke: \"T'okan-t'eji oun kò rii\" / Erukuku-ilé (eiyẹlé) nke: / \"Oun f'ẹhin kan koko oun kò kú\"", "REZO: IWORY BOGBE IFA MAYEWE IFA AFELE ITI IKI ITI EWE ANANAKUN ORUN BEBANI IFA ADIYOKO ONIBARABANIRE GUN ARA BUSHE AWOMAYAWE AWO ADIYEKE ORI IFA OÑI SHANGO ONIWE OLOKUN ONINI IFA.", "REZO: IWORY BOGBE IFA MAYEWE IFA AFELE ITI IKI ITI EWE ANANAKUN ORUN BEBANI IFA ADIYOKO ONIBARABANIRE GUN ARA BUSHE AWOMAYAWE AWO ADIYEKE ORI IFA OÑI SHANGO ONIWE OLOKUN ONINI IFA.", "REZO: ALLA KONI ESEN AYA IWO KANKATE Y LLABE. MAFEREFUN OLOKUN YALORDE OBINI SHESHE OLOGO ADIFAFUN AYE EYELE LEBO EKU EYA LEBO.", "REZO: IWORY BOGBE ORO BOENI LOJU INADEMI LETI ADAFUN ELEMALE ILE ALU IKUN UN ELENMALE OKO NI OJO TI NEON IFI OMO SHA ASIKU.", "SUYERE: KUORON LEYUN BARA KUELE KUALAYA. KUORON LEYUN BARA KUELE.", "REZO: IWORY BOGBE IFAYE OMO LORIFA BEYAMO AFEFE ARON IRE ABEYABI AWO LORIFA IWORY BOGBE ASHEBI ASHE IWORY BOGBE ALEYO ASHE IWORY BOGBE LORIFA ABEYARI LADE IFA OMA MAYARIN IFA KAFEREFUN OBINI MAYORA IFA ASHE KEIBE ASHE IFA LORIFA IFA ASHEGUN OTA MALALA ABERIN LORUN IWORY BOGBE ORUN MI LA ASHEBO ASHETO IFA LORIFA.", "REZO: IWORY BOGBE IFA AWO TOSHE MONI IKA KAFEREFUN OSHUN MONI BOSHE LODE NI IFA OMO IFA LOCOYEO IWORY BOGBE MONI BOSHE LALO NIFA YAKUN BABA IWORY BOGBE IFA TOSHE MONI OBOSHE KALE NI IFA MOWAYE NI IFA AFEFE LORUN BAWA OLOFIN.", "REZO: IFA ALEYO UMBO. IWORY BOGBE EFA ASHE BELLERE EFA AWO ABELLO NI AGBA NI BOSHE BODARANI TEMBOBOLE IFA A FE FE OLORU. AGOFORE KA AGBANI OLORUN. OBONI OBA NI BOSHE OLORUN. ONIBAYE BAYE OBONI. IBORI BOGBE ASHE IGUA LODE AGUIE TOLE IFA TOLO."]}]$q$::jsonb),
(48,'7e5aaf7ae3f3020d95eb57f4d6ce57e2',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀yẹ̀kú habla de un peligro cercano y de cómo evitarlo o reducir sus consecuencias. El bloqueo emocional se quita adorando y ofreciendo a los ancestros. Hay una fuerte disputa de pareja que amenaza con separarlos, y riesgo de pasar una experiencia amarga en el trabajo. Está prohibido llegar a los golpes con nadie, se tenga o no la razón."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente bloqueado emocionalmente y busca apoyo en sus ancestros.", "Hay una pelea fuerte en la pareja o miedo a una separación.", "En el trabajo puede pasar una vergüenza, un malentendido o perder la confianza de otros (relato del pato y la ropa de Eégún).", "Preocupa la salud de un recién nacido o de un familiar (relato de Ọlọ́fin).", "Hay tensión entre grupos y hace falta un acuerdo para evitar violencia (relato de Alágbàáà).", "Dice una cosa y hace otra, y eso le resta (relato del azadón)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Apartar la muerte que se acercaba.", "Un niño enfermo que, aunque quede con alguna secuela, prosperará.", "Una vida plena para el sacerdote que respeta los límites.", "Paz entre grupos que podían enfrentarse."]}, {"titulo": "Ibi y advertencias", "puntos": ["Pleitos de pareja que llevan a la separación.", "Que un secreto quede al descubierto en público.", "Pelear a golpes.", "Malentendidos o malicia contra otros."]}, {"titulo": "Enseñanza principal", "texto": "El que se cree protegido por lo que lo tapa termina expuesto. El pato confió en la ropa de Eégún y la ropa se le cayó en plena ceremonia. Y el sacerdote de Eégún y el babaláwo no deben pelearse nunca."}, {"titulo": "Relatos reunidos", "puntos": ["Ìwòrì frente a la muerte. Ògún agbotẹlẹ consultó para Ìwòrì y le dijo: 'Prepárate con valor, la muerte viene; pero si ofreces, se apartará'. Le marcaron ñame cocinado y machacado mezclado con aceite de palma en una jícara (que es tabú para la muerte), mucha nuez de kola para repartir a la gente, un pollito, una carnera y 240,000 cauríes. Cumplió.", "El recién nacido de Ọlọ́fin. Los adivinos le dijeron a Ọlọ́fin que su hijo recién nacido se enfermaría y que, tras un largo tratamiento, mejoraría pero podría quedar cojo. Le pidieron que no se enojara: si ofrecía, el niño todavía podía prosperar. Le marcaron una carnera, 440,000 cauríes y medicina de Ifá: hojas de iroyin (ifọn) y de ewúro machacadas en agua, para bañarse con jabón.", "El pato y la ropa de Eégún. El pato comerciaba con ropa para las ceremonias de Eégún, y decía que con ella hacía maravillas. Los babaláwo le advirtieron que ofreciera para que su secreto no se perdiera y nadie lo hiciera pasar una vergüenza. Respondió: '¿Quién va a poder algo conmigo cuando me tapo con esta ropa?', y no ofreció. Un día, en plena ceremonia, la ropa se le resbaló del cuerpo y la gente gritó '¡cuá, cuá!'. Eso es lo que el pato dice hasta hoy cuando habla.", "El sacerdote de Eégún y los babaláwo. Un enmascarado no debe pegarle nunca a un babaláwo, ni un babaláwo al enmascarado. Así consultaron para Alágbàáà, el jefe del culto de Eégún, que preguntaba si tendría una vida plena. Le marcaron vino de òpì y cumplió. Les avisaron a los babaláwo y a los enmascarados que no debían pelear entre ellos, y desde entonces no se ha oído que se peleen."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ìwòrì: jícara de ñame machacado con aceite de palma, mucha nuez de kola para repartir, un pollito, una carnera y 240,000 cauríes.", "Ọlọ́fin: una carnera, 440,000 cauríes y baño de iroyin (ifọn) y ewúro con jabón.", "El pato (rechazado): ofrenda para que no se descubra su secreto.", "Alágbàáà: vino de òpì."]}, {"titulo": "Relaciones espirituales", "texto": "Los ancestros y Eégún piden adoración. El culto de Eégún y el de Ifá deben respetarse mutuamente. Ikú, la muerte, se aparta con la ofrenda."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame machacado con aceite de palma, nuez de kola, iroyin (ifọn), ewúro, vino de òpì."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 48.1 (yorùbá): Ogun agbotẹlẹ kiip'aro: / li o difá fún Ìwòrì. / Wọ̀n ni: / \"ki o mura giri, Ikú mbọ\". / \"Sugbọ̀n bioba rúbọ / Ayẹ a yẹe\" / Ẹbọ: Igbá-ewo / opplopọ obi fun tüitorẹ / fún gbogbo èniyàn, / oromodiyẹ, àgutàn / ati egbàá méjilá owó. / Ó gbọ̀ ó rú", "Verso 48.2 (yorùbá): Ohun-tiyooṣenikiigbaiṣe'ni, / Eniyàn-kan-dandan- / lio-maabi-Ayèkun-omq: / a dífá fQlófin. / Wọ̀n ni: / Ọmptitun tiobi yi, / biobapẹ a ṣaisan kan. / Wọ̀n a woo titi a san ṣùgbón a yễ'kun. / Wọ̀n niki Ọlófin ma binu biobarubọ / omo naa a rire dandan. / Ẹbọ: Àgùtàn kan, / egbàá méjilélógún owó / ati ewé Ifá.", "REZO: IWORY YEKU INKAN OMBELARE OUN YELENI INTORI INKAN TOWALORE ALA TOKUMA ALA BURURU OUN BATONSHE GUE INKAN TO GIRELORI KOMAWA YOTE LOWO LOMA NI MI OBORI.", "REZO: IWORY YEKU INKAN OMBELARE OUN YELENI INTORI INKAN TOWALORE ALA TOKUMA ALA BURURU OUN BATONSHE GUE INKAN TO GIRELORI KOMAWA YOTE LOWO LOMA NI MI OBORI.", "REZO: IKAN OKU OMBELARE UN YELDEÑI INTORI IKAN TO GUALORE ALA TOGUEMA ALA BURURU UN BATONSHE GUE INKAN GUA TO GIRALORI COMOGUA LLOTE LOGUO YOMONI NI OBORI.", "REZO: DAKE ENU IBUYU BORI MU ADAGUEDE ADIFAFUN IWORY UN BATILOFE OKU GUO ETU LEBO ADIE.", "REZO: DAKEE ONCE BULUBARI ENUNDAQUE ADIFAFUN IWORY TINLO LEKOKUEKU GUETUETU LEBO ADIE MELLI EKU EYA.", "REZO: YEKAWO MOMENO KAMOROLO AWO KUKU AWO KOMAYA ADIFAFUN ENIMELE AFORUN YELOPE AGUE ABO AGUE KOKO EKU EYA EPO REZO: DAKENSE IBO YUBARI ENU ADAKE ADIFAFUN IWORY UN BATISHE AGUGUO ETU LEBO ADIE.", "REZO: IJATIJATI AWO ORUN ODE ADAFUN OLUKOUN IJIWO TI A NI KI ORUGBO NITORI OKO IDI RE SHOKOTO IDI RE OBUKO KAN ATI EGBETA LELOGBON.", "REZO: IWORY YEKU ADIFAFUN AKADO OKUNI MOTUMBA AWIGBO LODAFUN ELEGBA IFA NI KAFEREFUN ORUNLA. REZO: IJATIJATI AWO ORUN ODE ADAFUN OLUKOUN IJIWO TI A NI KI ORUGBO NITORI OKO IDI RE SHOKOTO IDI RE OBUKO KAN ATI EGBETA LELOGBON."]}]$q$::jsonb),
(49,'49d03628cefc114efb25ef70c0e48095',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ìdí establece la enseñanza de Ifá sobre la reencarnación: alguien puede dar vida a quienes fueron sus ancestros. La persona necesita hijos para equilibrar su vida espiritual. Ifá habla bien en este Odù: buena vida, una pareja que no lo dejará pasar hambre e hijos. Pide regalar ropa vistosa a los pobres para conservar la vista en la vejez."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Desea hijos o piensa en la continuidad de su familia (verso de Ọ̀rúnmìlà sobre padres e hijos).", "La casa necesita comida y estabilidad antes de asumir nuevos compromisos (relato de Ìwòrì e Ìdí).", "El miedo a perder sus bienes lo está llevando a decisiones que los gastan.", "Tiene algo valioso que podría compartir con quien lo necesita (relato del búho Òwiwí)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos y una tierra fértil que se multiplica.", "Una pareja que lo cuida y no deja que le falte comida.", "Buena vida, sin perder lo que tiene."]}, {"titulo": "Ibi y advertencias", "puntos": ["Perder la vista en la vejez por no desprenderse de lo que se pidió.", "Querer intimidad con el estómago vacío: el hambre debilita la fuerza del hombre.", "Ignorar el aviso de la propia pareja."]}, {"titulo": "Enseñanza principal", "texto": "Todo lo que se multiplica se ofrece en pareja: macho y hembra. Y quien no escucha el consejo de su pareja termina gritando 'te lo dije' en la oscuridad, como el búho."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà y las ofrendas en pareja. Ifá consultó para Ọ̀rúnmìlà cuando dijo que bajaría del cielo a la tierra y llevaría de nuevo la tierra al cielo. Para cumplir su misión le pidieron ofrecerlo todo en pareja, macho y hembra: un carnero y una carnera, un chivo y una chiva, un gallo y una gallina, y así con todo. Cumplió, y por eso la tierra es fértil y se multiplica sin fin.", "Ìwòrì y el hambre. 'Ìwòrì mírame, Ìdí mírame: es nuestro interior el que ve nuestra desnudez.' Así consultaron para Ìwòrì cuando iba a buscar la intimidad con su pareja. Le pidieron ofrecer y le dijeron que siempre que la buscara debía tener el estómago lleno. Canto: '¿Cómo va a poder el que tiene hambre?'.", "El búho que no quiso dar su ropa. 'El camino del problema no está lejos.' Así consultaron para el búho (Òwiwí), esposo de Òhúù, y le pidieron ofrecer su ropa de colores brillantes para conservar la vista hasta la vejez. Òhúù le insistía que escuchara el aviso, pero el búho se negó a dar su ropa. Por eso hasta hoy grita en el bosque: 'Òhúúú, ¡te lo avisé!'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: animales en parejas, macho y hembra (carnero y carnera, chivo y chiva, gallo y gallina).", "Ìwòrì: ofrenda y comer antes de la intimidad.", "El búho (rechazado): su ropa de colores; regalar ropa grande y vistosa a los pobres para conservar la vista."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà baja a la tierra y la devuelve al cielo: es el ciclo de la reencarnación. Los ancestros renacen en los hijos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Animales en pareja, ropa de colores."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 49.1 (yorùbá): Kosi abiyamo ti ko le bi awo lọmọ / Kosi abiyamo ti ko le bi Ọ̀rúnmìlà / Baba-ẹni biobabini nipipe, / bopẹtiti a tun nbi Baba-ẹni lomo, / Yeye-ẹni biobabini nipipe, / bobapẹtiti a tun nbi yeye-ẹni l'ọmo: / a dífá f'Ọ̀rúnmìlà ti o wipe òun maa / m'ọ̀run bọsayé òun maa mu / ayé l'osğrun. / Kiobaa leṣe bẹẹ dandan, / Wọ̀n niki ó rú / Ohun gbogbo ni méjiméji, / ako ati abo kan bayi: / Agbo kan, àgutăn kan, / òbúkọ kan, ewúrẹ kan, / akuko-adiyẹ kan / ati agbebo-adiyẹ kan / ati bẹẹbẹẹ. / Ó gbó ó rúbọ. / Bẹẹ ni ayé nbisii ti wọ̀n si nrẹ sii. / \"No hay madre con hijos que no pueda haber parido / a un sacerdote de Ifá\" / \"No hay madre con hijos, que no pueda haber parido a Ọ̀rúnmìlà\", / \"Nuestro padre, si nos ha dado plena existencia, / inevitablemente le daremos a él vida a cambio también\" / \"Nuestra madre, si nos da plena existencia, / inevitablemente le daremos a ella vida a cambio también.", "REZO: IWORY BODE IWERI IFA IWERI OSO YENE GONGOLE YEBE OSHANLA ABERE NI IFA OLOKUN OBORE GBORE OMO INA BORE IFA WOLODE FI ALAQUEMA SOVERE IFA OSHANLA LORUBO."]}]$q$::jsonb),
(50,'98f9d211a5a1185e4c3a5e478857b016',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ìrosùn habla de paciencia y de avanzar paso a paso hacia una solución. La persona es indecisa y duda, y eso no la deja avanzar. Anuncia hijos para la pareja y pruebas duras —tres tribulaciones— que, si se soportan sin rencor, terminan en riqueza."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene una decisión pendiente, le da vueltas a lo que pasó y sigue sin saber qué hacer (relato de Kòmò).", "Pasa de un plan a otro sin llevar ninguno a la práctica.", "Una pareja desea hijos y necesita apoyarse ante la incertidumbre (relatos de Ọ̀rúnmìlà y de Onígòósùn).", "Una etapa difícil le está dejando enojo, pesimismo o vergüenza.", "Se pregunta si podrá sostener una meta larga a pesar de los altibajos (relato de Òòsàálá y sus tres pruebas)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Las ideas y los planes llegan solos a la cabeza.", "Embarazo y un hijo para la esposa.", "Riqueza inmensa después de tres pruebas.", "Una casa en lo alto construida por la gente."]}, {"titulo": "Ibi y advertencias", "puntos": ["La indecisión que paraliza.", "Desesperarse en medio de la prueba.", "Guardar rencor."]}, {"titulo": "Enseñanza principal", "texto": "Un problema se resuelve calculando día por día y mes por mes. Òòṣà sufrió tres grandes aflicciones bajo el sol y la lluvia sin guardarle rencor a nadie, y la gente terminó construyéndole su casa en la cima de la colina."}, {"titulo": "Relatos reunidos", "puntos": ["Kòmọ̀, el que no sabía qué hacer. Ifá consultó para Kòmọ̀, que pensaba cómo hacer algo desde ayer; meditó, se durmió y al día siguiente seguía sin saber. Le dijeron que para resolver un problema hay que calcular día por día y, si se puede, mes por mes, hasta saber qué hacer. Le marcaron cuatro gallos, 8,000 cauríes y medicina de Ifá: cuatro garras en agua fresca para beber. El adivino le aseguró que las ideas le llegarían solas a la cabeza.", "El palo de osun para el hijo. Ifá consultó para Ọ̀rúnmìlà, que dijo que su esposa quedaría embarazada y daría a luz. Le marcaron dos gallinas, un palo de madera roja de osun y 4,400 cauríes. El palo de osun se le da a la mujer para que mantenga la esperanza de usarlo para untar el cuerpo de su hijo.", "Onígòósùn y el pecho que rehusaba. Ifá consultó para Onígòósùn, hija de Àpọ́n, que lloraba porque no tenía hijos. Le marcaron dieciséis bolas de osun (madera roja) y bastante dinero, y le dijeron que al llevar la ofrenda al lugar de Èṣù no se tocara la cabeza sino el pecho: su cabeza ya había aceptado la ofrenda, pero su pecho la rechazaba. Lo hizo así y tuvo muchísimos hijos.", "Las tres aflicciones de Òòṣà. Òòṣà llegó a la ciudad de Ifọ̀n y se quedó a las afueras, en un terreno abierto. Sufrió mucho: el sol lo quemaba y la lluvia lo empapaba, pero perseveró porque sabía que debía pasar tres grandes infortunios antes de llegar a ser rico. Cuando pasaron las tres pruebas, se llenó de todo lo bueno y su riqueza no se podía contar. La gente dijo: 'Nadie aguantó como él; no le guardó rencor a nadie; él es la deidad que vamos a adorar'. Lo llevaron a la cima de una colina y ahí le construyeron su casa."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Kòmọ̀: cuatro gallos, 8,000 cauríes y cuatro garras en agua fresca para beber.", "Ọ̀rúnmìlà: dos gallinas, un palo de osun y 4,400 cauríes.", "Onígòósùn: dieciséis bolas de osun y bastante dinero, tocándose el pecho al llevar la ofrenda a Èṣù.", "Devoción a Òòṣà-ńlá para que termine la etapa de prueba."]}, {"titulo": "Relaciones espirituales", "texto": "Òòṣà-ńlá (Ọbàtálá) es el modelo de paciencia en la prueba. Èṣù recibe la ofrenda. Orí acepta, pero el pecho también debe aceptar."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Osun (madera roja), garras en agua."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 50.1 (yorùbá): Bi ojumó ba nmọ̀ a / konly ògbẹ̀ri bi qjo-anọ: / li o difá fún Kòmò, / ti o nronú bi oun / ti maaṣe kini yi si lana. / Ó ronú titi ó sùn. / Nigbi Ojump mọ̀ ti yẹ̀ la, / Kòi mọ̀ eyiti oun maaṣe dandan. / Njẹ ki a jẹki qjẹ bori ojẹ, / bi ko ba to ki oṣu bori osu, / bopẹtiti aó mọ̀ eyiti a maa ṣe. / Ẹbọ: Akuko-adiyẹ mẹrin, ẹgbàárin owó ati ewé Ifá / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Ero rè a ma ṣe orí\".", "Verso 50.2 (yorùbá): Ifá I yoo ṣe abiyamo: / \"Ngo ra osù ki'miri / ohun mu fi pa omọ lara\". / \"Abiyamo kole ṣair'osù / ki o ler'ohun mupa omọ lara\": / a difá f'Ọ̀rúnmìlà, / wọ̀n ni aya rè maa loyun o maa bimọ. / Ebọ: Agbebo-adiyẹ Méjì, / osù ati egbejie-lógún owó. / Kiamu osù / igi-osù fún un / Ki o tọju rẹ ni ireti la ti fi pa omo l'ara. / Ifá predijo que ella sería madre: / \"Yo deseo comprar osù (polvo de madera roja) / para frotar sobre mi hijo\" / \"Una madre no puede ayudar a comprar osù / para poder cuidar el cuerpo de su hijo\":", "/ IWORI IROSO", "REZO:IWORY KOSO EÑI EWA OBINI EGUN IKU EVEQUE IWONEKE ARUN OFUN EFUN LELE YEKU IYA ARUN OBONU, OLUWO ABO MEN IFA EMO AWO OYEKUN LEYE LENGUA YENQUE ORUN AGBANI FAINLO EBBO LOKUN OMO NIKA.", "REZO: IWORY KOSO EÑI EWA OBINI EGUN IKU EVEQUE IWONEKE ARUN OFUN EFUN LELE YEKU IYA ARUN OBONU, OLUWO ABO MEN IFA EMO AWO OYEKUN LEYE LENGUA YENQUE ORUN AGBANI FAINLO EBBO LOKUN OMO NIKA.", "REZO: IWORY OKOSI LESE OYUPO EYE LOKO ADIFAFUN LO DURO TIMOSHONA EYE LOKO ETU MEYI ASHO PUPUA EBEFA OWO LEBO AKUKO EYELE LEBO. IFA ORUNLA GUONIN GUOMA GUEN ENFO ADIFAFUN EYELE BATONTO KITI EFAN EYELE OSU LEBO.", "REZO: IWORY KOSU LERE AYUPO EYILOKO ADIFAFUN ALODURO TINSHOBA EYE LOKO ETU MEYI ASHO PUPUA EBEFA OWO.", "REZO: IWORY KOSO ENI EYA EWA ABONI EGUN IFUN AYEWE WOKEYI ARUN IFUN LELE YEKUN IYA ORUN LEYE LEYE NEORI ARUN ABOYUN OLUO ABONI ENI IFA OMO ARUN O LELEKUN LEYE YENYE ORUN ABONIFA INLE EBBO LOGUN OMO INFA.", "REZO: IWORY KOSO IFA MAMU ELENU AFEFE IFA LERI BA OBA LERI AWO EGUN ASIERE ILE YIRE ABONO SHANGO MO PUE ILE AMONI NI SHANGO OMO YIRE AWO BAYEBI OMO SHANGO OLONIRE AWO.", "REZO: IWORY KOSO IFA LENU ELENU AFEFE LERI MORATERI AWO EGUN ASIERE MOBIRE ABONI SHANGO MOPEO LELE OBORI OMA YINI AWO.", "REZO: OLU SUAYA AYE ORI OLOGU MAYA PASA AFORA LOFUON ADIFAFUN ORUNLA EYELE LEBO AIKORDIE ETU OMO FINA EKU ELEGBA IFA.", "REZO: IWORY KOSO IFA MAMU ELENU AFEFE IFA LERI BA OBA LERI AWO EGUN ASIERE ILE YIRE ABONO SHANGO MO PUE ILE AMONI NI SHANGO OMO YIRE AWO BAYEBI OMO SHANGO OLONIRE AWO.", "REZO: IWORY KOSO IFA LENU ELENU AFEFE LERI MORATERI AWO EGUN ASIERE MOBIRE ABONI SHANGO MOPEO LELE OBORI OMA YINI AWO.", "REZO: OLU SUAYA AYE ORI OLOGU MAYA PASA AFORA LOFUON ADIFAFUN ORUNLA EYELE LEBO AIKORDIE ETU OMO FINA EKU ELEGBA IFA."]}]$q$::jsonb),
(51,'ddb2b61bcbcf346404e9363edbfa2df7',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀wọ́nrín habla de protegerse de pérdidas por desastres naturales y de recuperar lo perdido. Es un Odù de reencuentros: una vieja relación de pareja, de familia o de amistad puede volver. Anuncia la bendición de pareja, y pide no abandonar a las viudas ni a quienes se quedaron sin padres."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Va a viajar o a trabajar cerca del agua y necesita prepararse y tomar precauciones (relato de Joworo).", "Busca a alguien o algo que se perdió (relato de la comunidad de Otú-Ifẹ̀).", "Puede reencontrarse con una expareja, un familiar o un amigo.", "Perdió a sus padres o tíos y necesita una red de apoyo.", "Una persona viuda o mayor se está quedando sin compañía ni sustento (relato de la viuda de Ẹlérín).", "Se están tomando decisiones de herencia o de mando sin pensar en quienes dependían del anterior."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["No morir en el agua; mantenerse a flote.", "Encontrar a las personas que se buscan.", "Reencuentro con una relación antigua.", "Pareja; muchas esposas para quien ofrece.", "Ser elegido rey por escuchar el mensaje."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desastres naturales y pérdidas.", "Dejar abandonada a una viuda o a una persona mayor.", "Muertes seguidas en una familia por una causa que no se conoce."]}, {"titulo": "Enseñanza principal", "texto": "No se deja sola a la viuda. Los hijos de Ẹlérín no la cuidaron y la cobra que ella escondió los fue mordiendo; solo el que escuchó a Ifá y ofreció quedó vivo y fue rey."}, {"titulo": "Relatos reunidos", "puntos": ["Joworo y el agua. Olúgbemiro, adivino de la casa de la montaña, y Emibajo, adivino del ojo de agua, consultaron para Joworo cuando iba al ojo de agua. Le marcaron camarones, una carnera y 4,000 cauríes. Cumplió, y le dijeron que nunca moriría en el agua: siempre nadaría y se mantendría a flote.", "La gente de Otú-Ifẹ̀ busca a los suyos. Ìwòrì Ọ̀wọ́nrín se consultó para la gente de Otú-Ifẹ̀ cuando buscaban a unas personas. Les aseguraron que al final sonreirían porque las encontrarían. Les marcaron cuatro palomas y 8,000 cauríes. Cumplieron.", "Ìwòrìòdérín, el de las muchas esposas. 'Se parece a la rafia y es muy largo.' Así consultaron para Ìwòrìòdérín, y le pidieron ofrecer. Lo hizo y empezó a tener muchas esposas, tantas que se extendían más allá de lo que la vista alcanza, como la rafia.", "La viuda de Ẹlérín y la cobra. Los hijos de Ẹlérín se morían uno tras otro, como mordidos por veneno, y nadie sabía por qué. Cuando murió el rey Ẹlérín, quisieron poner otro, pero no quisieron mantener ni cuidar a su viuda. Ella, triste y abandonada, puso una cobra viva en la olla que se usaba en la ceremonia de elección. El primero que metió la mano fue mordido, y el segundo también. El tercero juntó sus cauríes y corrió con el adivino; le dijeron que ofreciera y cuidara de la tierra. Escuchó, ofreció, y fue elegido rey."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Joworo: camarones, una carnera y 4,000 cauríes.", "Otú-Ifẹ̀: cuatro palomas y 8,000 cauríes.", "Ìwòrìòdérín: ofrenda para tener pareja.", "El elegido de Ẹlérín: ofrenda general para detener las muertes y cuidar de la viuda.", "Devoción a los dobles celestiales (ẹnikeji)."]}, {"titulo": "Relaciones espirituales", "texto": "Los dobles celestiales (ẹnikeji) protegen a quien los atiende. La viuda del rey representa a los que quedan sin amparo y deben ser cuidados."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Camarones, rafia, cobra (en el relato)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 51.1 (yorùbá): Olúgbemiro awo Okẹ-ilé, / Emibajo awo ojú-omí, / a difá fún Joworo, / nlọ ojú-omi. / Wọ̀n niki ó rúbọ: / ẹdẹ, àgután / ati egbàá méjilelógún owó. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Joworo kii maa kú ikú omí, / a maa wẹ a maa le teje\"", "Verso 51.2 (yorùbá): Ìwòrì Wọ́nrín / a daa fún wọ̀n ni Otú-Ifẹ̀, / wọ̀n ni e nwa àwọn èniyàn kan bayi. / Ẹo fi òrán naa ṣe erin rín ni-ikẹhin / nitoripe é ori wọ̀n. / Wọ̀n niki ó rúbọ: / ẹiyẹlé mẹrin ati ẹgbàárin owó. / Wọ̀n gbọ̀ wón rú.", "REZO: IFA IWORY JUANI IFA WARA WARA NI MORO KASHEITA KASHEMINE WARA WARA BABASONA ELAROYE LAROYE KASHEITA KASHEMINI WARA WARA MORO ORUNLA O LORUGBO.", "REZO: ABARA MONO ABARA MONO OLODAFUN NIFE MERO ASHE ITA ISHE MINI. IWORY LEMI LESE PAPA CATABO GUNI GUN IWORY KUKUA CELABAMI GUERI KILINEBO. IWORY GUANI ELESE PARA KATOPO GUIRI GUIRI. IWORY DERIN POPA KALABABO MU KIRI KIRI.", "REZO: BALE ARIKU ARUKU LAYE KOYIWO ILU BALENDI IFA KOYIWO ILU BALEMBERE ABO MEYI OZAIN EGUNGUN DEÑIGU AYA INA OKAKA FIWO TIKU EGGUN TOTO BITAN LAWAYI ODO FUN KAWA GERI ODO ADUSHU ISHU WAYUWO KODIDE KAWOKO TOKESO JORO JORO OYUTO IWORY JUANI LODAFUN ORUNLA KAFEREFUN ESHU.", "SUYERE: ATIPONLA AIFAGURURU ATIPONLA IFA OMA IFA OMA ATIPONLA IFAGURU.", "SUYERE: IWORY JUANI OLE BAWASHE ODUN OLE BAWASHE.", "SUYERE: AWARA WARA NIMORO. AWARA WARA NIMORO KASHE ITA KASHE MINI AWARA.", "REZO: BALE ARIKU ARUKU LAYE KOYIWO ILU BALENDI IFA KOYIWO ILU BALEMBERE ABO MEYI OZAIN EGUNGUN DEÑIGU AYA INA OKAKA FIWO TIKU EGGUN TOTO BITAN LAWAYI ODO FUN KAWA GERI ODO ADUSHU ISHU WAYUWO KODIDE KAWOKO TOKESO JORO JORO OYUTO IWORY JUANI LODAFUN ORUNLA KAFEREFUN ESHU.", "SUYERE: IWORY JUANI OLE BAWASHE ODUN OLE BAWASHE."]}]$q$::jsonb),
(52,'f8728733a9c318bd6b4f206882e10782',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀bàrà insiste en la buena conducta y da soluciones para criar y educar a los hijos con responsabilidad. La atención debe estar en lo práctico. La persona dice que sufre y debe saber exactamente qué quiere; las cicatrices de lo malo que ha vivido se borrarán con el tiempo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita dejar las preocupaciones generales y tomar decisiones concretas.", "Hubo engaños o robos que pueden traer consecuencias para otros (relato de Òlé y Òpùrọ̀).", "Quiere criar hijos responsables y cuidar la memoria familiar (relato de Abowaba).", "Siente que el bienestar nunca llega y está perdiendo la esperanza; necesita apoyo de otros a tiempo (relato de Ìwòrì ò bèrè).", "Una comunidad o familia desea hijos y sufre por no tenerlos (relato de Dásà a ò kú mó)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Larga vida y poder contar la historia de su familia.", "Hijos responsables que lo sobrevivan.", "Un cambio total de suerte cuando ya no se esperaba, incluso llegar a ser rey.", "Niños donde antes no había."]}, {"titulo": "Ibi y advertencias", "puntos": ["Robar o mentir y caer en un juicio grande.", "Perder la paciencia y querer acabar con todo.", "Cargar penas como si fueran hijos."]}, {"titulo": "Enseñanza principal", "texto": "Hay que tener paciencia con Ifá aun cuando parece que lo bueno no llega. Ìwòrì ò bèrè estaba por rendirse cuando llegaron a buscarlo para hacerlo rey: lo que esperaba estaba en camino."}, {"titulo": "Relatos reunidos", "puntos": ["Los ladrones y los mentirosos. Ìwòrìbàràbàrà consultó para los ladrones y para los mentirosos y les pidió ofrecer y dejar su mala conducta para librarse de un gran juicio. Les marcaron mucha nuez de kola, aceite de palma, 44,000 cauríes, palomas y otras cosas; el dinero y la kola debían regalarse. Se negaron.", "Abowaba contará la historia de su familia. Iná kúf'eerub'ojú consultó para Abowaba, hijo de Afẹsoṣayé, y le dijo que viviría mucho y podría contar la historia de su familia; pero para tener hijos responsables que lo sobrevivieran debía ofrecer seis palomas, 12,000 cauríes y medicina de Ifá. Cumplió.", "Ìwòrì ò bèrè, el que se cansó de esperar. Ìwòrì ò bèrè decía que ya estaba cansado de esperar a Ifá: todo lo bueno que debía llegarle se le escapaba, y había decidido irse al monte a quitarse la vida. Le pidieron ofrecer; ofreció, pero no tuvo paciencia. Mientras tanto, en la ciudad vecina había muerto el rey, e Ifá les había dicho que escogieran como nuevo rey a un hombre que encontrarían en el monte a punto de quitarse la vida. Cuando Ìwòrì ò bèrè ya se ponía la soga, la gente de esa ciudad lo vio, lo detuvo y lo proclamó rey. Cantaron: 'Ìwòrì ò bèrè, no te ahorques; no te desesperes, que la corona viene en camino'.", "La ciudad que cargaba jorobas. Un siervo no compite por el asiento del rey. Así consultaron para la gente de Dásà a ò kú mọ́, que cargaba jorobas como si fueran niños porque no nacían hijos en la ciudad. Les pidieron ofrecer en grande; ofrecieron muchas chivas y mucho dinero, y cuando la ofrenda llegó al cielo la vida cambió: tiraron las jorobas y en su lugar cargaron a sus hijos a la espalda."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ladrones y mentirosos (rechazado): mucha nuez de kola, aceite de palma, 44,000 cauríes y palomas; regalar el dinero y la kola.", "Abowaba: seis palomas, 12,000 cauríes y medicina de Ifá.", "Ìwòrì ò bèrè: ofrenda y paciencia.", "Dásà a ò kú mọ́: muchas chivas y mucho dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá elige al rey y premia la paciencia. Los hijos responsables continúan la memoria familiar."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Nuez de kola, aceite de palma, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 52.1 (yorùbá): Iworibàràbàrà, / İworibàràbàrà: / a difá f'Ole, / a bu f'Opuro. / A niki wọ̀n wa rúbọ. / Ki wọ̀n ṣiwọ ninu iwà tiko sunwọ̀n. / Ki òràn bàràbàrà ma bàwọn. / Ẹbọ: Ọpolopo obi, epo, / egbàá méjilelógún owó, / ẹyẹlé ati bẹẹbẹẹ. / Kia maa fi owó torẹ. / Kia maa fi obi torẹ. / Wọ̀n kọ, wọ̀n ko rú.", "Verso 52.2 (yorùbá): Iná kúf'eerub'ojú, / Ọ̀gbẹdẹ̀kúfomọrẹrợ'po: / a dífá f'Abowaba / ọmọ Afẹsoṣaye / Wọ̀n ni: \"a pẹ laye, / a di onitan ninu ẹbi\" / Sùgbọ̀n ki àwọn ọmọ rè / baa lẹ gbẹhin rẹ̀ / ki o rúbọ kiobaa leri ẹnirere / ṣ'ẹhin de òun: / eyẹlé mẹfà, egàáfa owó / ati ewé Ifá li ebo. / Ó gbọ̀ ó rú.", "REZO:IWORY JOBERE OUN BEREYO OUN TIROLA OUN TIROLO IYE TIMODE AYE OUN BERE LEKE UJU ADIFAFUN YALORDE EYEBEMEKUN YEWA YOKO YEWA EURE ELEBO. KAFEREFUN ORUNLA, YALORDE ATI SHANGO. MAREREFUN ELEGBARA.", "REZO: IWORY BARA AUN BERERA AUN BEREYO AUN TIROLA AUN TIROLO IYO TIMOLE AYE AUN BERE LOKO UJU ADIFAFUN YALORDE EYEBO MEKUN YEWA YOKO YEWA EURE LEBO.", "REZO: OYOAYA KOMABE IKOKO KOMA LORI ARUN LONINA KOKOMATO AYUMA KOBOMATO AKUA.", "REZO: ADIFAFUN YEMAYA ATARAMAGUA ADIFAFUN AWO SEIKO ASEKAN KORRE EGUA ORI EYA TUTO OLONTOAYE GUAYR AYAKA ATAFUN IYA OLO OYO ORUBASHIRU AGBE ACHICUIABIOEO FUNI ORUN BI OGBE ISHU FERE OBINI ONI TAN AOBA OYO OMI NILEKEY NIKORO ORUNLA OLORUN ASHE ABAIMA MIGUALOREYU KAFE REFUN OLOFIN.", "REZO: IWORY OBERE UN BARERA BOROLLO UN TIRO LATIROLU TIOMODE AYA OBORE LOKO ORI ADIFAFUN YALORDE EYA BOMOKU OGUA YOKO OGUA. ADIFAYOKO KANFUN O BAGUYA LORUBO FUNSHESHE FUNAGUA AYO OPOLOPO EYELE ABO MEGUA NIAMO KIYA.", "REZO: OYUMANA KAMABE IKOKO KAMA LORI ARO LOUINA KOKOMATE IYUIMA KOBO MATO LEBO.", "REZO: UMBEREYA UMBEREYA ADOKO ADIE ADIFAFUN TOMODE.", "REZO: IWORY BARA AUN BERERA AUN BEREYO AUN TIROLA AUN TIROLO IYO TIMOLE AYE AUN BERE LOKO UJU ADIFAFUN YALORDE EYEBO MEKUN YEWA YOKO YEWA EURE LEBO.", "REZO: OYOAYA KOMABE IKOKO KOMA LORI ARUN LONINA KOKOMATO AYUMA KOBOMATO AKUA.", "REZO: ADIFAFUN YEMAYA ATARAMAGUA ADIFAFUN AWO SEIKO ASEKAN KORRE EGUA ORI EYA TUTO OLONTOAYE GUAYR AYAKA ATAFUN IYA OLO OYO ORUBASHIRU AGBE ACHICUIABIOEO FUNI ORUN BI OGBE ISHU FERE OBINI ONI TAN AOBA OYO OMI NILEKEY NIKORO ORUNLA OLORUN ASHE ABAIMA MIGUALOREYU KAFEREFUN OLOFIN."]}]$q$::jsonb),
(53,'e007fc59646857c06e52e87e52ec131b',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀kànràn establece la privacidad entre el babaláwo y quien consulta, y la importancia de planear el futuro. A veces la persona no es sincera con el babaláwo. Ifá le pide no vivir aislada: su fortuna está en estar entre la gente. Si tiene hijos, deben ofrecer junto con el padre."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["No le cuenta todo al babaláwo o no se siente en confianza para hablar.", "Quien aconseja puede estar contando cosas privadas o hablando de más (verso de Ọ̀rúnmìlà).", "Tiene un proyecto nuevo que debe evaluar antes de arrancar (relato de Makanju-huwa y la cabra).", "Busca oportunidades, pero se aísla y no acepta consejo (relato de Olórèé Agbọ̀n).", "La familia pregunta por los hijos y cómo acompañarlos juntos (relato de la Mosca del Sol)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Buenos pensamientos que llegan siempre a la cabeza.", "Fortuna al estar rodeado de gente y ser conocido.", "Muchos hijos.", "Escapar de un problema en lo que se planea emprender."]}, {"titulo": "Ibi y advertencias", "puntos": ["Hablar de más sobre lo que otros consultan.", "Aislarse de la gente.", "Emprender algo sin revisar antes el terreno."]}, {"titulo": "Enseñanza principal", "texto": "El adivino lo ve todo, lo sabe todo y no anda contando nada. Y la chiva, antes de echarse a dormir, revisa el suelo: lo mismo hay que hacer antes de aventurarse."}, {"titulo": "Relatos reunidos", "puntos": ["El adivino no es chismoso. Arimaṣaroka-Iwogbe, adivino de Ọ̀rúnmìlà, le advirtió que ofreciera para no meterse en grandes problemas por lo que les decía a quienes venían a consultarlo. 'Hablar sin cuidado mata al ignorante; no hay nada que el ojo del adivino no vea ni nada que no sepa, pero el adivino no es chismoso.' Le marcaron cuatro babosas, una chiva y 32,000 cauríes. Cumplió.", "La chiva revisa antes de echarse. 'Cuando la chiva va a dormir, primero inspecciona el suelo.' Así consultaron para Makanju-huwa, y le dijeron que algo en lo que pensaba aventurarse podía traerle un gran problema, pero que si ofrecía escaparía. Le marcaron una chiva, una gallina, 8,000 cauríes y medicina de Ifá: cuatro garras en agua fresca para beber, diciéndole: 'Buenos pensamientos vendrán siempre a tu cabeza'.", "Olórèé Agbọ̀n deja de ser ermitaño. El sacerdote de Olórèé Agbọ̀n consultó para él, que vivía debajo del mercado, apartado de todos, y preguntaba si le llegaría algo bueno. Le dijeron que ofreciera y que no viviera solo, porque su fortuna estaba en encontrarse con la gente. Por eso, hasta hoy, cuando algo bueno le llega a alguien, es para que se vea en otros.", "La mosca del sol. El mismo adivino consultó para la mosca del sol, que lloraba porque no tenía descendencia. Ofreció y tuvo hijos sin número; pero nadie conoce a sus padres: solo se conoce a la mosca."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: cuatro babosas, una chiva y 32,000 cauríes.", "Makanju-huwa: una chiva, una gallina, 8,000 cauríes y cuatro garras en agua para beber.", "Padre e hijos: ofrecer juntos."]}, {"titulo": "Relaciones espirituales", "texto": "El babaláwo y quien consulta guardan un pacto de discreción. Ọ̀rúnmìlà es el adivino que ve todo."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Babosas, garras en agua."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 53.1 (yorùbá): MAFII / Arimaṣaroka-lwogbe awo Ọ̀rúnmìlà: / li o difá fún Ọ̀rúnmìlà. / A niki o rúbo, / kioma baa ri òràn-ẹjó / lati odọ gbogbo àwọn / ti nwa pee kioyẹ wọn wo yi o. / \"Ẹnu-aim'ẹnu\" / \"ete-aim'ete niiṣe ikú p'ọ̀gbẹri\". / \"Kosi ohun ojú Awo kiiri\" / \"Kosi ohun Awo kiimg\", / \"Awo kiiṣ'aroka\" / Ẹbọ: İgbin mẹrin, ewúrẹ / ati egberindilógún owó. / Ó gbọ̀ ó rú", "Verso 53.2 (yorùbá): Ṣbelẹwobẹlẹwo, / \"bi ewúrẹ ba maa dubulẹ / a bẹ ilẹ ibẹ wò\": / li o difá fún Makanju-huwa / Irin-gbẹrẹ-ọla. / Wọ̀n ni: / \"ohun ti o ma ṣe yi, / ko niile d'òràn s'ọrùn fún un / biobatirúbo ṣa\" / Ebọ: Ewúré, adiyé, / egbàárin owó / ati ewé Ifá / Ó gbọ̀ ó rú. / Ewé Ifá: Ko iṣo mẹrin sinu omi tiomọ kiomuu nigbati o ba muu / tan kiaso fün un pe: / \"Ero rẹ a maa ṣ'ori\"", "REZO: IWORY KANA ADIFAFUN EYA OKUNRIA ASHIRI OKUN OLOKUN OBA OKUN AGANA LOPA LERI, KAFEREFUN ORUNLA.LODAFUN OLOKUN.", "REZO: OWO OBOKA LENISURE OBEYOGUO. AWO OLORE AKOBA OMA AKOTIGUA BATAN EURE LEBO EL BEYO OWO ADAFUN OBATALA. ALADAFUN OLOKUN.", "REZO: IWORY KANA ADIFAFUN EYA OKUNRIA ASHIRI OKUN OLOKUN OBA OKUN AGANA LOPA LERI, KAFEREFUN ORUNLA. LODAFUN OLOKUN."]}]$q$::jsonb),
(54,'6f5e74d5ef36c570298ab201abcd6f64',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ògúndá habla de actuar a tiempo frente a una situación crítica para que la suerte cambie. La persona no está sabiendo manejar ciertas cosas y está perdiendo el rumbo. La cabeza está llamada a una corona: hay que ofrecer para subir y tener paz. Si piensa unirse a alguien que está saliendo de un matrimonio, debe pensarlo bien."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Evita decidir en un momento clave y siente que pierde el rumbo.", "Un enojo viejo vuelve y provoca pleitos en lugar de cerrarlos.", "Busca un cargo o reconocimiento (relato de Orí Olóyè).", "Se interesa por alguien que no ha cerrado su relación anterior y no debe guiarse por rumores (relato de Àṣá y Kútelú).", "Tomó una decisión apresurada antes de una reunión o celebración familiar (relato de Ọloba en el bosque).", "Su suerte puede cambiar (relato de Olúlatẹjà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["El desafortunado se vuelve afortunado.", "Subir al trono o a un cargo importante.", "Encontrar la salida cuando se estaba perdido.", "Paz en una relación nueva."]}, {"titulo": "Ibi y advertencias", "puntos": ["No ofrecer a tiempo y quedarse perdido.", "Unirse a alguien que no ha cerrado su matrimonio anterior.", "Hacerle caso a las habladurías."]}, {"titulo": "Enseñanza principal", "texto": "Lo que no se hace a tiempo lo tienen que hacer otros por uno. El Ọloba no quiso ofrecer y se perdió en el bosque; sus hijos ofrecieron por él y lo sacaron con su canto."}, {"titulo": "Relatos reunidos", "puntos": ["Olúlatẹjà cambia su suerte. Los adivinos consultaron para Olúlatẹjà y le dijeron que el desafortunado se convertiría en afortunado. Le marcaron una paloma, tela blanca y 16,000 cauríes. Cumplió.", "El Ọloba perdido en el bosque. Iwowotiriwo consultó para el Ọloba, que en cinco días celebraría el centenario de su cargo. Le marcaron diez ratas, diez pescados y 2,000 cauríes para que tuviera tiempo de celebrar su fiesta. No quiso; decidió entrar rápido al bosque a cazar las ratas que necesitaba. Èṣù le nubló la vista y no encontró el camino de regreso. La víspera de la fiesta, sus hijos hicieron la ofrenda. Al amanecer se reunieron y fueron hacia el bosque cantando: 'Iwowotiriwo, hoy es la fiesta del Ọloba'. Todo el barrio los siguió en procesión, y Èṣù le quitó la oscuridad de los ojos. El Ọloba siguió el hilo de la canción y salió del bosque.", "Orí Olóyè, la cabeza que será coronada. 'Ìwòrì, mira algo bueno que crear.' Así consultaron para Orí Olóyè, que venía del cielo a la tierra y preguntaba si su vida sería buena. Le pidieron ofrecer para subir al trono, ser alguien importante y tener paz. Ofreció. 'Vengan a ver qué impresionante es tenerla.'", "Àṣá y la esposa de Àwòdì. Ifá consultó para Àṣá, el halcón, que iba a tomar a Kútelú, la esposa de Àwòdì. Pero Kútelú no se podía divorciar de Àwòdì: lo que se decía eran mentiras y murmuraciones."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Olúlatẹjà: una paloma, tela blanca y 16,000 cauríes.", "El Ọloba (hecho por sus hijos): diez ratas, diez pescados y 2,000 cauríes.", "Orí Olóyè: ofrenda a la cabeza para subir al trono."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù ciega al que no ofrece y le devuelve la vista cuando se cumple. Orí es la cabeza que lleva la corona."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ratas, pescados, tela blanca."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 54.1 (yorùbá): Ogun tán, qtẹ̀ tán, / Eni-nbamiijà-o-ṣiwo-ijà: / a difá f'Olúlatẹjà / Abataṣekẹrẹkẹrẹgb'ọkọ. / Wọ̀n ni: / \"Orí buruku maa di oriire\" / Ebọ: eyẹlé, aṣo-funfun ati ẹgbàásan owó / Ó gbọ̀ ó rú.", "Verso 54.2 (yorùbá): Iwowotiriwo: / li o dífá fQloba, / a nfi qjọ odún rè da orunni. / Wọ̀n niki ó rú: / Eku méwà, eja mẹwà / ati ẹgbèwá owó / kio baale ri aye ṣe odún rẹ̀. / Ọloba kọ ko rú. / Ó ni òun nyara lọ sinu igbó lọ / pa eku wa. / Ọloba de inu igbó tan, / Èṣú diil'ojú kom'ọna bowa'le mọ. / Odún di ola tan awọn pmọ rẹ̀ / pada lọ rúbo. / O di ojumo odun, / wọ̀n gbarajo nkorin / lọsi'gbo'Malè Ọloba bayi pe: / Iwowotiriowo o, / Oni ma l'odún Oloba o. / Gbogbo ilú gbọ̀ wọ̀n si wọjowa bawọn / korin yi ninu igbo'Malẹ naa. / Nigbanaa ni Eṣú wa ka òkùnkùn / kuro loju Ọloba. / O si nto'pa orin bọ titi o fi wa / yọsi wọ̀n ninu igbó Imalẹ naa.", "REZO:IWORY OGUNDA, IWORY OWA LELE IFA OGUNDA AWABO BORUN AWANIRI LORIN OÑI IFA AWO BEHENI IFA AWAKENI IFA ORIBAYE AWO ABIWA ABANI AWO.", "REZO: IWORY OGUNDA, IWORY OWA LELE IFA OGUNDA AWABO BORUN AWANIRI LORIN OÑI IFA AWO BEHENI IFA AWAKENI IFA ORIBAYE AWO ABIWA ABANI AWO.", "REZO: IWORY AWA LELE IFA OGUNDA AWABO BORUN AWANIRI LORIN ONI IFA AWO KANIBI IFA AWAKENI IFA ORIBAYE AWO ABIWA ABANI AWO; OSHANLA KEKEREYE YENI ONI BABALAWAO OBANI ALAKENTA ELEGBA ASHE LEBI LEGUN OBAYE NI AWO ELEGBA ONI EGGUN TENI IKI OGUE SHANGO INA BI IFA KAFEREFUN OGUN, YEMAYA, SHANGO ATI ELEGBA.", "REZO: LAMI LAMI OGGUN ALAN TAKUA UMBO ILE IBU OMODE KERE LAMI LAMI UNSODE ORUNLA LODAFUN ORUNLA.", "REZO: IWORY AWA LELE IFA OGUNDA AWABO BORUN AWANIRI LORIN ONI IFA AWO KANIBI IFA AWAKENI IFA ORIBAYE AWO ABIWA ABANI AWO; OSHANLA KEKEREYE YENI ONI BABALAWAO OBANI ALAKENTA ELEGBA ASHE LEBI LEGUN OBAYE NI AWO ELEGBA ONI EGGUN TENI IKI OGUE SHANGO INA BI IFA KAFEREFUN OGUN, YEMAYA, SHANGO ATI ELEGBA.", "REZO: LAMI LAMI OGGUN ALAN TAKUA UMBO ILE IBU OMODE KERE LAMI LAMI UNSODE ORUNLA LODAFUN ORUNLA."]}]$q$::jsonb),
(55,'ee91a5f42dc8d6961a37b03aed4336bb',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀sá pide hacerse responsable de los propios actos. La persona tiene el conocimiento y la capacidad para resolver sus problemas, pero no quiere reconocerlo ni usarlos. Hay riqueza que llega por medio de un amigo; para que entre a la casa hay que ser tolerante, no pelear y no ser malicioso."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Sabe cómo resolver un problema, pero lo pospone o cree que no puede.", "Huyó de una responsabilidad o de las consecuencias de lo que hizo (relato de la tortuga).", "Sigue pidiendo ayuda para algo que podría empezar a resolver por su cuenta (relato de Olódùmarè).", "Espera mejorar la economía de la casa, quizá con un amigo, pero un pleito amenaza ese apoyo (relato de Ìwòrì en casa de Òsá).", "Se siente atacado por detractores y debe distinguir un conflicto real de una reacción impulsiva (relato de Àwón)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza que llega a través de un amigo y se lleva a casa.", "Protección contra las guerras y las malas influencias.", "Sosiego y paz mental."]}, {"titulo": "Ibi y advertencias", "puntos": ["Huir de las consecuencias de lo que se hizo.", "No usar la fuerza y la sabiduría que se tienen.", "Pelear o provocar enojos en momentos delicados."]}, {"titulo": "Enseñanza principal", "texto": "Olódùmarè ya repartió poder y sabiduría; quien no usa lo que recibió no tiene a quién culpar. El hijo que no ve a su padre debe valerse de su fuerza interior."}, {"titulo": "Relatos reunidos", "puntos": ["La tortuga que huyó al monte. Ifá consultó para la tortuga (Ìjàpá), que huyó al bosque por su mala conducta. El adivino le dijo que el día que la atraparan la traerían de regreso amarrada, y que ofreciera para evitarlo: una paloma, 3,200 cauríes y medicina de Ifá. Se negó.", "Olódùmarè cubre la tierra con un velo. Atikareṣetẹ, el adivino del cielo, consultó para Olódùmarè y para el mundo, cuando toda la gente corría a Olódùmarè por cualquier cosa, llorando: 'Padre, sálvame'. Él decía: 'A quienes les di poder no lo usaron; a quienes les di sabiduría no usaron la que llevan dentro'. Le aconsejaron ofrecer para poner un velo oscuro sobre la tierra: una tela negra, una carnera negra, 20,000 cauríes y medicina de Ifá. Cumplió, y el adivino dijo: 'El hijo que no vea a su padre debe defenderse con su inteligencia y su fuerza interior'.", "Ìwòrì trae la riqueza de la casa de Ọ̀sá. Ifá consultó para Ìwòrì, que iba a la casa de Ọ̀sá a recibir riqueza para llevarla a la suya. Le pidieron ofrecer y no pelear con nadie, no ser malicioso ni provocar enojos. Cuando la riqueza apareció en casa de Ọ̀sá, Ìwòrì tomó una buena parte y se la llevó. 'Gbàbilà, el hijo que está lleno de cauríes.'", "Ọláawin salva a Àwọ́n. 'No es bonita la oveja, pero tiene la cabeza redonda.' Así consultaron para Ọláawin, que salvaba a Àwọ́n de sus enemigos. A Àwọ́n le pidieron ofrecer contra sus detractores y lo hizo; Ọláawin y Òòṣà se pusieron de su lado. '¿Qué nos salva de las guerras y de las malas influencias? Ọláawin'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La tortuga (rechazado): una paloma, 3,200 cauríes y medicina de Ifá.", "Olódùmarè: una tela negra, una carnera negra, 20,000 cauríes y medicina de Ifá.", "Ìwòrì: muchas palomas y bastante dinero para que la riqueza entre a la casa.", "Àwọ́n: ofrenda contra los detractores."]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè dio a cada uno poder y sabiduría. Òòṣà y Ọláawin protegen a quien ofrece contra sus enemigos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tela negra, carnera negra, palomas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 55.1 (yorùbá): Eni a Sa, Ọla a Sa, / a dífá fObahun İjapá / sọ̀ràn ti ko sunwọ̀n o / nsalo sinu igbó. / Wọ̀n nì: / Qjọ ti owó ba tẹ ijapa, / dide ni wọn maa dee l'okun bowale. / Ki o wa ṣebo / kiwọn ma le dee l'okun / lati oko bowale. / Ẹbọ: eyẹlé, egberindilógún owó / atí ewé Ifá / Ó gbọ̀ ko rú.", "Verso 55.2 (yorùbá): Atikareṣetẹ awo ğrun: / a difa fOlódùmarè ati Ayè, / nigbi àwọn omo-aráyé / nsare to Olódùmarè / nitori ohun gbogbo, / nke Baba: / \"Baba mo de gba mi jowẹ gba mi\". / Ó ni: \"Eetiri?\" / \"eniti mo fún l'agbára ko lo agbára, / eni ti mo fún lọgbón ko lo ọgbọ̀n / inu wọn ti mo fun wọn?\" / A niki Olódumarè rúbọ / kiofi ṣe asa-ökünkùn s'ojú ayé. / Ẹbọ: Aṣo-dúdú, àgùtàn dúdú, / ẹgbàá méwà owó ati ewé Ifá. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Ọmọ ti ko ri Baba rẹ̀ a sa ipa inu\".", "REZO:IWORY ROSA ADIFAFUN BABA AYALGUNA ELESE OLOFIN AMEGO OGBO NI OLOGUN OGBO, AIYE OLOFIN ALAMORERE, KAFEREFUN OBATALA, LODAFUN ODUDUWA.", "REZO: IWORY ROSA ADIFAFUN BABA AYALGUNA ELESE OLOFIN AMEGO OGBO NI OLOGUN OGBO, AIYE OLOFIN ALAMORERE, KAFEREFUN OBATALA, LODAFUN ODUDUWA.", "REZO: IWORY BOSA ADIFAFUN OYIGBONA WOSA BERENI AWO, ELEGBARA ORI IKU MAWA EYONI WOWONI EWE, OWUNKO WEWENI ELEGBA OBI AÑAÑAJUN OWUNKO TIBONI BOKUN AKOBA.", "REZO: ADIFAFUN BABA AYAGUNA ELESE OLOFIN AMEGO OGBONI OLOGUN GBOGBO AIYE OLOFIN ALA MORERE KAFEREFUN OBATALA LODAFUN OSHUN.", "REZO: ILELE IWORY BOSASO MI ATI FUN AIGBORAN GBOGBO PAWATI ENLA ABAPERUDE DEKUN ELEGBA OGA DE KUNI NITORI OLUGARA NI OLOFIN ELEGBA YIOKUTE.", "REZO: IWORY BOSA ADIFAFUN OYIGBONA WOSA BERENI AWO, ELEGBARA ORI IKU MAWA EYONI WOWONI EWE, OWUNKO WEWENI ELEGBA OBI AÑAÑAJUN OWUNKO TIBONI BOKUN AKOBA.", "REZO: ADIFAFUN BABA AYAGUNA ELESE OLOFIN AMEGO OGBONI OLOGUN GBOGBO AIYE OLOFIN ALA MORERE KAFEREFUN OBATALA LODAFUN OSHUN."]}]$q$::jsonb),
(56,'d3be59bda66c062854393c94727a53fa',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ìká advierte contra robar y actuar con violencia. Cuando aparecen relaciones nuevas o las de siempre ofrecen grandes oportunidades, la persona se fija solo en el dinero. Pide que en la casa nunca falte nuez de kola y que se vigile a un enemigo que quiere atraparlo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay una relación nueva o actual con futuro, pero solo se está mirando lo material.", "La casa busca negocio, comida y paz (relato de Ajitobi y las nueces de kola).", "Hubo un robo o lo están presionando para entrar en algo ilegal (relato de Kuṣika y su banda).", "Alguien joven o de menor rango se siente amenazado por compañeros con más poder (relato de Àmùrè ò dàgbà).", "Se está poniendo a prueba la lealtad en la pareja, la familia o el grupo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza en pareja vendiendo algo que la gente siempre busca.", "Salvarse de una trampa de compañeros envidiosos.", "Pareja, paz mental y riqueza mientras haya kola en casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Robar: el que roba es atrapado.", "Compañeros con más poder que planean deshacerse de uno.", "Fijarse solo en lo material en las relaciones."]}, {"titulo": "Enseñanza principal", "texto": "Lo robado se devuelve al cruce de caminos y se deja de hacer el mal. Y el que tiene el conocimiento de Ifá se salva aunque sea el más joven: el halcón se llevó la ropa del lagarto, no al lagarto."}, {"titulo": "Relatos reunidos", "puntos": ["Kuṣika y su banda. Los adivinos consultaron para Kuṣika y su banda, que robaban de noche tapados por la oscuridad, y les advirtieron que pronto serían arrestados. Si no querían ser atrapados, debían ofrecer toda la mercancía robada que tenían en sus casas, una chiva grande y 8,000 cauríes; llevar todo lo robado a un cruce de caminos a medianoche y dejar de hacer el mal.", "Ajitobi, la vendedora de kola. Ifá consultó para Ajitobi, esposa de Ìwòrì Àyòká, y le pidió ofrecer. Lo hizo, y al poco tiempo, cuando la gente buscaba nuez de kola, decía: 'Vamos a casa de Ajitobi, que ahí siempre hay'. Ella y su esposo se hicieron ricos con ese negocio. En la casa del babaláwo, joven o mayor, siempre debe haber nuez de kola.", "El lagarto y la ropa del sacrificio. Cuatro aprendices de la casa de Àgbọnnìrègún fueron instalados en cargos: la cobra como jefe (olúwo), la pitón como segundo, el caracol como heraldo, y el lagarto Àmùrè ò dàgbà, el más joven, solo cargaba los bultos. Los tres mayores contrataron al halcón para matar al lagarto y lo citaron a una reunión. El halcón se escondió en un árbol alto. Esa noche el lagarto tuvo pesadillas, y le pidieron que ofreciera muy temprano la ropa agbádá de su cuello: 'nadie que ofrece teme ser destruido'. Cuando el halcón se lanzó sobre él, Èṣù le echó la ropa de la ofrenda a las garras; el halcón la enredó, creyó que tenía al lagarto y subió gritando '¡Lo atrapé!'. Los otros tres celebraron, pero el lagarto, que sabía Ifá, cantó: 'Lo que atrapó el halcón fue la ropa; mi vida no la perderé'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Kuṣika: lo robado, una chiva grande y 8,000 cauríes; dejar todo en el cruce de caminos a medianoche.", "Ajitobi: ofrenda; siempre tener nuez de kola en casa.", "El lagarto: su ropa agbádá ofrecida temprano en la mañana."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù desvía el ataque hacia la ropa ofrecida. Àgbọnnìrègún (Ọ̀rúnmìlà) es el maestro de los aprendices."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Nuez de kola, ropa agbádá."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 56.1 (yorùbá): Anikanja-ole-ẹjó, / Ajumoja-ole-ejo, / Ijotiabam'ole / Ole-a-ka'rawọn: / liadá fún Kuṣika / ati àwọn ẹgbẹ rè / tinṣe awo-oru. / Wọ̀n ni: / Qwọ̀ a tẹ Kuṣika ati àwọn ẹgbẹ rẹ̀, / bi a pe ki owó ma tẹ won, / ki wọ̀n wa rúbọ: / Ohun-olohun gbogbo tiowa ni ilé, / ake-ewúrẹ ati ẹgbàárin owó. / Bi wọ̀n ba rúbọ, / kiako ohun-olohun tiowa ni ilé / dasi ikorita li oganjo oru. / Ki wọ̀n gba ikilo yi pe: / kiwọn ye'ka-iṣe.", "/ IWORI IKA", "REZO:IWORY BIKA ADIFAFUN ORUNLA IWORY BOKA BOKO ADIFAFUN ORUNLA ADIE ELEBO. BABA BOKA GUNUGUN ASHABA GODA GUNUGUN AKA ASHABA GUOKO ADIFAFUN ALEYO IBABA GUEKO BABA BUEKO OMI ELE DOMIYE ASHABA LEDE APATA PINA EWE, EPO ELEBO.", "REZO: BABAKOKA BUKO GUNUGUN ASHABA BOKO BOKO ADIFAFUN ENI LAYO EBA BABA BAKO BABA GUSHINI AFEDU MUYE ASHANI BABA YEDELE APATA PITI AMANSI ODABATANI AFEDU MUYE ASHANI BABA YEDELE PATA PITI.", "REZO: IWORY KA ADIFAFUN ORUNLA IWORY GUOKA BOKO ADIFAFUN ORUNLA ADIE LEBO BOBA GUOKA GUMIGU ASHABA GAGA GUGIN AKA ASHABAGUOKO ADIFAFUN ALEYO IBABA GUOKO BABA EMIELE DOMIYE DOMIYA ASHABALADE PINA EWE EPO.", "REZO: BABA GUOKA BABA GUOKA GUNUGUN OSHALA GAGAGUGU OKO OSHABA GUOKA GUOKO OBINI OLOFIN IRU LAKADO OBINI OLOFIN AMUNI ODABA ODABA TAÑI AFEDUMUYE ASHAMBALA YEDE DEAPATA PITI OWO EPO ADIE FUN FUN.", "REZO: SHEGUE SHEGUE SHEGUERE GUIRI GUIRI KAN GUILONO UMBATI UMPON."]}]$q$::jsonb),
(57,'5b6678f7550db61fda7520934c44e9f3',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Òtúrúpọ̀n habla de éxito en el embarazo y el nacimiento de los hijos, y de convertir las malas situaciones en triunfo por medio de la ofrenda. Un renacer espiritual o emocional pone fin a los temores. Lo bueno llega en bultos; pide continuar la buena obra de los padres y que los hijos aprendan Ifá."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una familia que perdió un hijo teme pasar otra vez por eso.", "Una mujer embarazada o que desea hijos busca apoyo y cuidado.", "La familia quiere continuar un oficio o una enseñanza de sus mayores (relato de Atinúlahùn).", "Teme que un error de dinero convierta una oportunidad en pérdida (relato de la compra de Ọ̀rúnmìlà).", "Una etapa de dolor no le deja ver lo bueno que ya está llegando (relato del baobab)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un nuevo embarazo y un hijo cargado a la espalda.", "Que los hijos no mueran antes de tiempo.", "Lo bueno llega en bultos y a montones.", "Que lo que parecía perdido se convierta en ganancia, como Ajé convertida en servidora de Ọ̀rúnmìlà."]}, {"titulo": "Ibi y advertencias", "puntos": ["Comprar o emprender sin hacer primero la ofrenda.", "Perder hijos por no ofrecer.", "Apartarse del buen camino de los padres."]}, {"titulo": "Enseñanza principal", "texto": "Primero la ofrenda, después la compra. Ọ̀rúnmìlà compró sin ofrecer y perdió; cuando cumplió, Èṣù convirtió la pérdida en la mayor ganancia."}, {"titulo": "Relatos reunidos", "puntos": ["La planta de ẹ̀là no pierde sus hojas. Ìwòrì era esposo de Òtúrúpọ̀n, que había perdido un hijo. Ifá dijo que ella volvería a embarazarse y cargaría a su hijo a la espalda, y que si Ìwòrì ofrecía, sus hijos no morirían antes de tiempo. Le marcaron una gallina, una chiva, pescado ahumado, 18,000 cauríes y medicina de Ifá: diez hojas de ẹ̀là molidas con semillas de iyèré, cocinadas en sopa con pescado, para tomarla muy temprano a los cinco meses de embarazo. Cumplió, y el adivino dijo: 'La ẹ̀là nunca pierde sus hojas cuando las demás las tiran'.", "Ọ̀rúnmìlà, la esclava y Ajé. Ekitibababa le marcó a Ọ̀rúnmìlà una chiva y 3,200 cauríes cuando ahorraba para comprar una esclava. No ofreció; compró a una mujer, que murió a los tres días. En la casa todos lloraban. Èṣù entró y preguntó si había consultado antes de comprar; Ọ̀rúnmìlà dijo que sí, pero que no había ofrecido. Èṣù le dijo que fuera a ofrecer si no quería perder su dinero, y Ọ̀rúnmìlà lo hizo. Entonces Èṣù bañó el cuerpo, lo vistió con lujo, lo sentó en un cruce del mercado con un palito de mascar en la boca y una bandeja de mercancías, y se escondió. Era día de mercado: todos la saludaban y, como no respondía, se alejaban. Al final llegó Ajé, la riqueza, con sus doscientos esclavos; quiso comprarle, se enojó porque no respondía, tomó un garrote y la golpeó, y el cuerpo cayó. Èṣù salió gritando: '¡Ajé, mataste a la esclava de Ọ̀rúnmìlà!'. Ajé suplicó y fue ofreciendo esclavas en reemplazo, hasta prometer las doscientas, pero Èṣù exigió que ella misma fuera también. Así Ajé se convirtió en servidora de Ọ̀rúnmìlà.", "El baobab lleno hasta el borde. Ifá consultó para Ọlọ́mọ ní ràdiràdi, que lloraba por hijos y por lo bueno de la vida. Ofreció, y lo bueno le llegó en bultos y a montones. Ọlọ́mọ ní ràdiràdi es el sobrenombre del baobab: cuando se abre su fruto, sus semillas se ven como hilos de algodón entrelazados, llenos hasta el borde.", "Atinúlahùn, el hijo de las entrañas. Ifá consultó para Atinúlahùn. Después de nacer actuó según las enseñanzas de Ifá, y su vida fue tranquila y famosa. Le dijeron: 'Ọ̀rúnmìlà te hará regalos espléndidos'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ìwòrì: una gallina, una chiva, pescado ahumado, 18,000 cauríes y sopa de ẹ̀là con iyèré y pescado a los cinco meses de embarazo.", "Ọ̀rúnmìlà: una chiva y 3,200 cauríes antes de comprar.", "Para que lo bueno llegue en bultos: un pedazo de paño y algodón entrelazado."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù hace cumplir lo prometido a quien ofrece. Ajé, la riqueza, termina al servicio de Ọ̀rúnmìlà. Ọ̀rúnmìlà, llamado Àbikújigbo, es el que combate a la muerte."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹ̀là (orquídea), pimienta iyèré, pescado ahumado, algodón, fruto del baobab."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 57.1 (yorùbá): Ìwòrì okọ Òtúrúpọ̀n bimo ó kú. / Ifá ni: \"Obirin yi a tún fi inú ṣe oyun / a tún fi ẹhin gbe ọ̀mọ pòn\" / \"Ki Ìwòrì wa rúbọ ki ọmọ rẹ̀ ma baa kú mọ\". / Ẹbọ: Agbebo-adiyẹ, ewúrẹ, eja-aro, / egàásan owó ati ewé Ifá. / Ó gbọ̀ ó rú. / Wọ̀n ni: \"Èla kiiba igi oko wọ'we\"", "Verso 57.2 (yorùbá): Ekitibababa: / a dífá f'Ọ̀rúnmìlà / ntu owó-ẹrú jọ. / A niki ó rú: / Ewúrẹ ati egberindilógún owó. / Ó gbọ̀ ko rú. / Ọ̀rúnmìlà ra erú naa / liarúbo tiogbo pe o tọ / ki oun rú kiotoo raa. / Erú naa jẹ Obirin. / Qjokẹta ti o raa li o kú. / Àwọn ara-ilé Ọ̀rúnmìlà bẹrẹsii kigbe / wọ̀n si nsokun nitori rẹ̀. / Eṣú gbọ. / O wole wa ba wọn. / O bere lowo won pe: / Kini nṣe yin ti ẹ nsokun to bayi? / Ọ̀rúnmìlà ni: Erú ti oun ra nijẹta liokú nisisiyi. / Èṣú ni: Olúwa mi, iwọ ko ha difá kiotoo raa? / Ọ̀rúnmìlà ni: mo difá nitori rẹ. / Èṣú ni: Olúwa mi, Abikújigbo?! / O ha rúbọ naa bi? / Ọ̀rúnmìlà ni: oun kiotii rúbọ naa. / Eṣú ni: Iwọ ni koṣe bi o ba ti ṣe nigbanaa. / Njẹ lọ rú ebọ naa bioko bafẹ / ki owó rè ti o fi ra erú na ṣegbe o. / Ọ̀rúnmìlà lọ rúbọ.", "REZO:IWORY TRUPON EYELE, EKO, OÑI KERE YELE ADAKOY EYELE LEBO OWUNKO LEBO. MAFEREFUN OLOKUN, ALA ATI ALEYO.", "REZO: EYELE EKO OÑI GUEREYELE ADAKOY EYELE ELEBO OWUNKO MAFEREFUN OLOKUN MAFEREFUN ALA MAFEREFUN ORUNLA MAFEREFUN ALIYO.", "REZO: IWORY TRUPON EYELE, EKO, OÑI KERE YELE ADAKOY EYELE LEBO OWUNKO LENO. MAFEREFUN OLOKUN, ALA ATI ALEYO."]}]$q$::jsonb),
(58,'ccd965c681d6afd11706043d98eeed28',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Òtúrá habla de falta de armonía en la familia: hay problemas con los hijos, se note o no. Se refiere a tres personas que deben ofrecer para progresar y obtener buenos puestos, y a no menospreciar a quien parece menos capaz, porque puede llevarse la ganancia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Un padre o una madre quiere que sus hijos se pongan de acuerdo (relato de la serpiente padre).", "En la familia o el grupo compiten por cargos, reconocimiento o ganancias.", "Desprecia una ayuda porque viene de alguien que considera poco capaz.", "El hijo menor no es valorado igual que los demás (relato de Kèké, Òkótó y Àré).", "Cree que ya sabe resolverlo todo y dejó de escuchar (relato del Sabio y el Necio)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["El último de los hijos puede quedarse con el lugar del padre.", "El humilde que ofrece se lleva la ganancia.", "Buenas posiciones para quien se prepara."]}, {"titulo": "Ibi y advertencias", "puntos": ["Hijos que no se unen ni para defenderse.", "Creerse demasiado hábil para ofrecer.", "Despreciar a alguien por parecer torpe."]}, {"titulo": "Enseñanza principal", "texto": "El que se siente seguro de su talento y no ofrece pierde frente al que reconoce su debilidad y se prepara. Así ganó la rueca el baile, y así el necio se llevó a casa la ganancia del sabio."}, {"titulo": "Relatos reunidos", "puntos": ["La serpiente padre y sus hijos. Ifá consultó para la serpiente padre y sus hijos, y dijo que los descendientes de la serpiente nunca se pondrían de acuerdo para unirse frente a un ataque. Si el padre quería unirlos, debía ofrecer dieciséis babosas, una paloma, veneno de serpiente y 16,000 cauríes. Se negaron. Por eso las serpientes andan siempre solas.", "El rodillo, el cono y la rueca. Olómijó, ya viejo, era jefe del pueblo. Para heredar su lugar había que bailar sobre la piel de un animal grande sin salirse de ella. El rodillo de hilo dijo que no ofrecería porque sabía bailar muy bien; el cono presumió lo mismo por todo el pueblo. La rueca (Àré), la más pequeña, dijo que era mala bailarina y ofreció la piel de un animal grande y el látigo de la fiesta de la riqueza. El día del baile, el cono giró como torbellino y no pudo quedarse sobre la piel; el rodillo tampoco. La rueca empezó y se detenía, y Èṣù dijo: 'Péguenle con el látigo de la ofrenda'. Tres veces la azotaron, y a la tercera tomó velocidad y bailó perfecto. Se quedó con el lugar del padre.", "El sabio y el necio. Ifá consultó para el sabio y para el necio, y les dijo que ofrecieran para resolver cualquier problema. El sabio presumió que dentro de él estaba la solución a todo; el necio ofreció. Fueron juntos al mercado: el sabio caminaba con desprecio y el necio con torpeza y humildad. Al final, el necio se llevó a casa las ganancias del sabio."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["La serpiente padre (rechazado): dieciséis babosas, una paloma, veneno de serpiente y 16,000 cauríes.", "La rueca: la piel de un animal grande y el látigo de la fiesta de la riqueza.", "El necio: ofrenda para resolver cualquier problema.", "Para que no escape la fortuna: ofrecer por alguien que se menosprecia."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù ayuda a la rueca con el látigo de la ofrenda. El padre es la autoridad que se hereda en la familia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Piel de animal, látigo, babosas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 58.1 (yorùbá): Igi-woroką niitú iná ka, / Èniyàn iwèrè niitú ilé ara rẹ̀ ka: / a difá fún Baba-Ejò ati àwọn qmọ rè / Wọ̀n ni: / \"Àwọn ọmọ ejò koniile ni ajohun / kiwọn ko ara wọn jọ / kiwọn wa kọ'ya l'ọjọ ijà. / Bi Baba-Ejò ba pe kiwọn ni ajohun / kiwọn wa rúbo\": / İgbin mẹrindilógún, ẹyẹlé, / oògùn burúkú / ati ẹgbàájo owó. / Wọ̀n gbọ̀ wọn ko rú. / \"La madera hueca dispersa al fuego\". / \"Un loco (quien pierde el juicio) / separa su propio hogar\":", "REZO: KUKUTE KUKU ADIFAFUN AUN TOMA OWUNKO EKU LEBO ONERU AKUKO LEBO.", "REZO: ELEGBA LOMIRIN ORUNLA KE OTIBEYAWO AYE OMA OLORUN OBINI INSHE APETEVI AYAWO ORUNLA INTORI OWO PIPO LORUBO IWORY OTURA TUTU TUTU ODIFAYOKO KANFUN ORUN MILA AYE OMO OLOKUN OMA LOBORUN INTORI OWO PIPO LODAFUN OLOKUN IKU GUNLE OFO LERI LAITOSHU.", "REZO: KUKUTE KUKU ADIFAFUN AUN TOMA OWUNKO EKU LEBO ONERU AKUKO LEBO REZO: IWORY TUNILARA EYENI AYE EYE BEWA ESHU ELEGBA ESHU GOGORO AYO MAFUN WANILODE ERITA MENI EYIWA OMO IWORY TUNILARA EYENI GUELERI OYA IRE ASHEGUN OTA ELEGBA EYI MAFUN OBENIWA AYE OMA BERENI AYE ELEGBA ORIBODE OBATALA OBANI AYE AYEGUNA OSHANI LAYE OYA BEBENIWA ORUNLA ORIBOSHE ELEGBA.", "REZO: IWORY OTURA MOSAWERE AWO INLE ÑAÑA OLOWUO OZAIN ADIMOWO KOBELE FO BASUN KOBELEFO IMOLE INLE ÑAÑA TORI TI OZAIN TI ELESE NILE OBATALA SHONSHON LONA OYU NI WORI OTURA MOSAWERE AWO UNSORO ISI LE TE ARUN ARA AILOKUN ATIRE OTORIRE SHONSHON LONA ILE OZAIN MAFEREFUN OZAIN, OYA, ATI OBATALA.", "REZO: OLUMENE TU NENE, OLUMENE TUNENE DINAN KUKO YOKA WAWA EWINA KIKU ANSHI TUTO DUDU TUTO NENE INANKIYO NIPAPONI KUKADE ODUMI OMO IRIKU LAISO ORISHA.", "REZO: ELEGBA LOMIRIN ORUNLA KE OTIBEYAWO AYE OMA OLORUN OBINI INSHE APETEVI AYAWO ORUNLA INTORI OWO PIPO LORUBO IWORY OTURA TUTU TUTU ODIFAYOKO KANFUN ORUNLA AYE OMO OLOKUN OMA LOBORUN INTORI OWO PIPO LODAFUN OLOKUN IKU GUNLE OFO LERI LAITOSHU.", "REZO: IWORY TUNILARA EYENI AYE EYE BEWA ESHU ELEGBA ESHU GOGORO AYO MAFUN WANILODE ERITA MENI EYIWA OMO IWORY TUNILARA EYENI GUELERI OYA IRE ASHEGUN OTA ELEGBA EYI MAFUN OBENIWA AYE OMA BERENI AYE ELEGBA ORIBODE OBATALA OBANI AYE AYEGUNA OSHANI LAYE OYA BEBENIWA ORUNLA ORIBOSHE", "REZO: IWORY OTURA MOSAWERE AWO INLE ÑAÑA OLOWUO OZAIN ADIMOWO KOBELE FO BASUN KOBELEFO IMOLE INLE ÑAÑA TORI TI", "OZAIN TI ELESE NILE OBATALA SHONSHON LONA OYU NI IWORY OTURA MOSAWERE AWO UNSORO ISI LE TE ARUN ARA AILOKUN ATIRE OTORIRE SHONSHON LONA ILE OZAIN MAFEREFUN OZAIN, OYA, OBATALA."]}]$q$::jsonb),
(59,'2284a7035c45917ce722a29e40424457',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ìrẹtẹ̀ habla de la iniciación en Ifá como camino para mejorar la vida: la persona debe considerarla en serio. El que hace el bien lo hace para sí mismo y el que hace el mal también. Pide ofrecer a Orí para llegar a una posición importante y no perderla, ser agradecido con su babaláwo y, si es babaláwo, tratar bien a sus aprendices."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa iniciarse en Ifá o renovar su compromiso con lo que ya aprendió.", "Un babaláwo, aprendiz o consultante debe revisar cómo trata a quienes le ayudan.", "Repite una conducta dañina aunque sabe lo que provoca (verso de los actos que regresan).", "Aspira a un cargo importante y teme perderlo por ingratitud o imprudencia.", "Está enfermo o cuida a alguien enfermo (relato de Ẹ̀rẹ̀).", "Un golpe del destino puede terminar en un cambio de posición (relato de Ṣàṣóré)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una posición importante en la vida, incluso un trono.", "Curar a un enfermo que le traen.", "Recoger el doble del bien que se hace.", "Que el destino cambie para bien."]}, {"titulo": "Ibi y advertencias", "puntos": ["Robar: el que roba mil pierde dos mil.", "Envidiar o castigar al que pide bien para sí.", "Hacer las cosas de Ifá sin cuidado."]}, {"titulo": "Enseñanza principal", "texto": "El que inicia debe hacerlo con cuidado, y el iniciado debe reiniciarse en su propia mente. Awo, no subas a la palma con una soga podrida, no entres al agua si no sabes nadar, no saques el cuchillo con enojo. Orí sabe a dónde lleva a cada quien."}, {"titulo": "Relatos reunidos", "puntos": ["El que hace el bien lo hace para sí. Ifá habló para todo el mundo: 'Ladrones, dejen de robar'. Respondieron que no podían. Ifá dijo: 'El que robe será avergonzado; el que robe mil perderá dos mil. El que encuentre a un mendigo, que le dé caridad; el que haga mil cosas buenas cosechará dos mil. Odùduà recompensará los buenos actos'. Les marcaron babosas, pescado y 3,200 cauríes.", "Los consejos al awo. 'Si estás iniciado en Ifá, debes reiniciarte en tu propia mente. Awo, no subas a la palma con una soga podrida; no entres al agua si no sabes nadar; no saques el cuchillo con enojo; no rompas el delantal de otro awo.' Le marcaron pescado, 3,200 cauríes y medicina de Ifá: sopa de pescado con hojas de ẹ̀sọ̀ para tomar.", "Ìwòrì cura a Ẹ̀rẹ̀. 'Primero piso el agua antes que la arena.' Así consultaron para Ìwòrì, que iba a curar a Ẹ̀rẹ̀ de una enfermedad. Le dijeron que todo lo que hiciera terminaría bien. Ofreció, curó a Ẹ̀rẹ̀ y su cuerpo quedó sano por completo.", "Ṣàṣóré y el ataúd en el río. Cada año, en su fiesta, el rey Ẹléwìí llamaba a Ṣàṣóré para ofrecer a su cabeza. Ṣàṣóré rezaba por el rey —larga vida, caminos abiertos, hijos, bienestar— pero también pedía: 'Que la vida me sonría a mí; llévenme a un lugar bueno'. Un año el rey se enojó: '¿A dónde quieres que te lleve tu cabeza?'. Mandó hacer un ataúd, lo metió dentro y lo echó a un río caudaloso: 'Veremos a dónde te lleva tu Orí'. En Benin acababa de morir el rey, y la costumbre era coronar a un extranjero. Ifá les dijo que sacaran del río cualquier cosa rara que vieran, porque tendría que ver con el nuevo rey. Al séptimo día vieron flotar el ataúd, lo abrieron y encontraron a Ṣàṣóré. Lo llevaron por todo el pueblo cantando 'hoy tenemos un superior' y lo sentaron en el trono. El rey de Benin está por encima del Ẹléwìí, y todos los reyes de la región debían ir a rendirle homenaje. Cuando llegó el Ẹléwìí, reconoció temblando al hombre que había echado al río. Ṣàṣóré le dijo: 'Si no hubieras hecho lo que hiciste, yo no estaría en este trono', y lo despidió con buen dinero."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para todos: babosas, pescado y 3,200 cauríes.", "El awo: pescado, 3,200 cauríes y sopa de pescado con hojas de ẹ̀sọ̀.", "Ìwòrì: ofrenda antes de curar a Ẹ̀rẹ̀.", "Ṣàṣóré: ofrenda a su propio Orí."]}, {"titulo": "Relaciones espirituales", "texto": "Orí es quien guía a cada persona a su destino. Odùduà (Ọ̀ọ̀duà Atẹ̀rígbẹ̀jì) recompensa los buenos actos. Ifá elige al rey."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹ̀sọ̀ (tilo), pescado, babosas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 59.1 (yorùbá): \"Aroratẹwọ̀n-roratẹwón, / ki àwọn omo aráyé ma ṣiwàfü\", / \"Eni ṣe rere o ṣee fún'ra rè\" / \"Ẹni ṣe Ìká o ṣee fún'ra rè\": / ni Ifá tadá f'Ayé. / I: eyin ole ki ẹ ma dẹ jale mo o. / Wọn ni: àwọn kòlè ṣe aláijalè. / I: ẹni jalè a ṣ'èsín, / I: ẹni jiwọn l'ẹgbèrún a ṣ'ofo ẹgbàwá l'ayé. / Ẹni r'akẹbojẹ kiofi oore ṣee. / Eni ṣoore ẹgbèrún a fi gb'ẹgbèwá. / Oòduà Olúwa mi Atẹrigbeji lo maa san an. / A niki wọ̀n rú: / Igbin, eja-aro ati ẹgbèrindilógún owó.", "Verso 59.2 (yorùbá): Ìwòrì-tẹjúmọ̀'hun-tiiṣẹ'ni / Bi o ba tẹ' Fá tan, kiotun iye rẹ tẹ̀ / Ìwòrì-tẹjúmo'hun-tiiṣẹ'ni / Awo! mamafi èjá-igbà gun opè. / Ìwòrì-tẹjúmó'hun-tiiṣẹ'ni / Awo! mamafi àimowe wọ omi. / Ìwòrì-tẹjúmọ̀' hun-tiiṣẹ'ni / Awo! mamafi ibinú yo obẹ / Ìwòrì-tẹjúmp'hun-tiiṣẹ'ni / Awo! mamasan bantẹ Awo. / Ìwòrì-tẹjúmo'hun-tiiṣẹ'ni / A niki wọ̀n rú: / Eja-arẹ, ẹgbẹrindilógún owó / ati ewé Ifá.", "/ IWORI IRETE", "REZO:IWORY ROTE ADAE OBI OSU DUDU AKUN FIBI YURUMA TELO IJOSHEKE IRI SHAKE ADIFAFUN AKUKO MOKOKOJE ABO TOLOFE ANAKE OMO OLOKUN BOGBO AWO ARANKO AIYE AGBO SHAGOBO ALUKU INIKA NI EYA OKO ABELE OYI ADIFAFUN ELEGBARA.", "REZO: KUKUTE KUKU ADIFAFUN AUN ARIMATUYO ADIE CARE ILEKE INU AKUKO EYELE LEBO.", "REZO: IWORY ROTE INSO BELEFUN ODARA ARA ERAN ERI BABANI INLE OFO BAGUALO DETIYA INLE INSO BOBO ENI FUN FUN INA YAFRA TUTO NI ERAN ENI ARA ODARA AWO BABINU INSO TOWA INE OZAIN MOYENI OSHALEKE OLAYE ODARA BI IFA LODAFUN ORUNLA.", "REZO: IWORY ROTE ADAE OBI OSU DUDU AKUN FIBI YURUMA TELO IJOSHEKE IRI SHAKE ADIFAFUN AKUKO MOKOKOJE ABO TOLOFE ANAKE OMO OLOKUN BOGBO AWO ARANKO AIYE AGBO SHAGOBO ALUKU INIKA NI EYA OKO ABELE OYI ADIFAFUN ELEGBARA.", "REZO: AIDEJU AWO ADIFAFUN ORUNLA UMBO WASIYE EURE MEYI ELEBO EYELE MEYI ELEBO OWO MEDILOGUN ELEBO AWO JEREKUN OLE ODUDUWA AKALA ITANA. IGBODUN IFA AKALA AWO NIFA AKALA OMO ORISHA UMBELORO YEYE MANIBU ORUNLA LODAFUN ORUNLA. MAFERFUN ORISHA.", "REZO: OKITI BABA OPEKU ADIFAFUN OLOFIN APARI ADIFAFUN PALAKORE.", "SUYERE: AKALA AWO ONIFA AKALA OMO ORUNLA MANIBU.", "REZO: IWORY ROTE INSO BELEFUN ODARA ARA ERAN ERI BABANI INLE OFO BAGUALO DETIYA INLE INSO BOBO ENI FUN FUN INA YAFRA TUTO NI ERAN ENI ARA ODARA AWO BABINU INSO TOWA INE OZAIN MOYENI OSHALEKE OLAYE ODARA BI IFA LODAFUN ORUNLA.", "REZO: AIDEJU AWO ADIFAFUN ORUNLA UMBO WASIYE EURE MEYI ELEBO EYELE MEYI ELEBO OWO MEDILOGUN ELEBO AWO JERE KUN OLE ODUDUWA AKALA ITANA. IGBODUN IFA AKALA AWO NIFA AKALA OMO ORISHA UMBELORO YEYE MANIBU ORUNLA LODAFUN ORUNLA. MAFERFUN ORISHA.", "SUYERE: AKALA AWO ONIFA AKALA OMO ORUNLA MANIBU.", "REZO: OKITI BABA OPEKU ADIFAFUN OLOFIN APARI ADIFAFUN PALAKORE."]}]$q$::jsonb),
(60,'cc5fe0395619145ea6e1de80034990fc',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Ọ̀ṣẹ́ habla de convertir la adversidad en éxito: lo dulce viene después del sabor amargo de la hoja de ewúro. Una mujer madura puede quedar embarazada. La persona debe controlarse con las mujeres para no perder lo que gana y regresar a casa con sus beneficios."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pasa por problemas de dinero y teme perder el ánimo o la reputación (relato de Owókosi).", "Su negocio pierde ventas porque se distrae o trata mal a una clienta (relato del granjero y la comerciante).", "La familia desea hijos o una mujer madura pregunta si puede embarazarse (relatos de Ojú-oje y Osúnláyà).", "Tiene recursos, pero la avaricia o la mala administración no le deja usarlos bien.", "Quiere proteger a sus hijos y el bienestar de la casa."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["La pobreza se convierte en prosperidad.", "Una mujer madura puede ser madre.", "Hijos para quien los pide.", "Mantener el buen nombre en tiempos difíciles."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desanimarse ante la pobreza.", "Distraerse con una mujer y descuidar el negocio.", "Que algo malo le pase a él o a sus hijos si no ofrece."]}, {"titulo": "Enseñanza principal", "texto": "Lo dulce viene después de lo amargo. El que en la pobreza conserva su buen nombre ve llegar la prosperidad; el que en el mercado mira lo que no debe, pierde la venta."}, {"titulo": "Relatos reunidos", "puntos": ["Owókosi y la hoja amarga. Ifá consultó para Owókosi, y le aconsejó no desanimarse por el ataque de la pobreza y mantener su buen nombre: 'La dulzura suele venir detrás del sabor de la hoja amarga'. Le marcaron palomas, 3,200 cauríes y medicina de Ifá: hojas de ewúro y de ojúùsájú machacadas con jabón para bañarse.", "Ojú-oje, la diosa de la belleza. Ifá consultó para Ojú-oje y le aconsejó ofrecer para llegar a ser madre: una gallina, una chiva, 24,000 cauríes y medicina de Ifá.", "El granjero y la comerciante. Ifá consultó para la comerciante y para el granjero, que le vendía sus productos del campo. A los dos les pidió ofrecer. Mientras vendía, el granjero se quedó mirando a la mujer y dejó de atender sus mercancías. Al final solo ganó pérdidas, y la gente se burlaba: 'Por mirar a la mujer perdiste en lugar de ganar con tu cosecha'.", "Osúnláyà, la que ya no menstruaba. Ifá consultó para Osúnláyà, esposa de Àgbọnnìrègún, que se lamentaba porque no tenía a quién arrullar en sus brazos. La gente decía: '¿Cómo va a tener hijos si ya no menstrúa?'. Ofreció, empezó a tener hijos, y alabó a sus babaláwo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Owókosi: palomas, 3,200 cauríes y baño de ewúro y ojúùsájú con jabón.", "Ojú-oje: una gallina, una chiva, 24,000 cauríes y medicina de Ifá.", "Para no perder lo ganado: un plato de barro lleno de nueces de kola.", "Osúnláyà: ofrenda para tener hijos."]}, {"titulo": "Relaciones espirituales", "texto": "Ojú-oje es la diosa de la belleza. Àgbọnnìrègún (Ọ̀rúnmìlà) es esposo de Osúnláyà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ewúro (hoja amarga), ojúùsájú, nuez de kola."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 60.1 (yorùbá): İṣẹ kiide kiomamu ire rẹ bọ̀'ni, / Tibitire-Ejiwapo: / a dífá f'Owókosi-èniyàn-kosunwọ̀n / Wọ̀n ni: / Ojú tiori iṣé kioma barajẹ. / Kiotoju oruko rere. / Adùn niigbẹhin ewúro. / Wọ̀n niki ó wa rúbą / ki Isé di Ọrọ̀ fún un. / Ẹbọ: Ẹyẹlè, ẹgbèrindilógún owó ati ewé Ifá. / \"La tribulación (pena, aflicción, adversidad) / no llega sin estar rodeada de cosas buenas\" / \"El bien y el mal siempre están juntos\":", "Verso 60.2 (yorùbá): Obirin dára e w'àṣé, / Qná-ngbaṣe-abiyamo da?: / a daa f'Ojú-oje, Ọlorun-ẹwà. / Wọ̀n ni ẹbọ niki o wa ṣe / kiobaa le ṣe abiyamo. / Ebọ: Agbebo-adiyẹ, ewúrẹ, / ẹgbàá méjila owó ati ewé Ifá. / Una mujer hermosa que no está menstruando, / ¿cómo puede ser posible que dé a luz hijos?:", "REZO:IWORY BOSHE OBA LERI, OBA LERI INLE BOLEDI WANWAN LODO NIGFA ABEYERE AWO LERI BALERI INLE IWORY OBA NI. WORI BABA LONI OSHE IWORY NOSHENSHE ABI OSHE OKOLOWO BORI BOSHE EBENI INSHE INLE NAYERI LAYE AWO OBARA NI BOSHANSHE IFA.", "REZO: OMO SHUDE MODA SHE BI ORUNLA UMBATI OLORUN OMITI BIGUENI AGUOMI ADAFUN ORUNLA UMBATI EU LEBO EWEFA AKUKO EYELE LEBO.", "REZO: IWORY BOSHE BOSHIBO FUN KELIBA NA ENA KUATI KIKE SHOBI NI KIKE OBA MALE ODUSHE.", "REZO: IWORY BOSHENSHENO ABA LERI ABALERI INLE MAYERI WANWA LODE IFA ABEYERE AWO LERI ABEYEBI INLE IWORY OBA NI IWORY BABA MONI OSHE IWORY BOSHENSHENOABI OSHE OKI LOWO BORI BOSHE EBENI ISHE INLE MAYERI LAYE AWO OBA KAFEREFUN IYALODE.", "REZO: IWORY BOSHE BOSHIBO FUN KELIBA NA ENA KUATI KIKE SHOBI NI KIKE OBA MALE ODUSHE.", "REZO: IWORY BOSHENSHENO ABA LERI ABALERI INLE MAYERI WANWA LODE IFA ABEYERE AWO LERI ABEYEBI INLE IWORY OBA NI IWORY BABA MONI OSHE IWORY BOSHENSHENOABI OSHE OKI LOWO BORI BOSHE EBENI ISHE INLE MAYERI LAYE AWO OBA KAFEREFUN IYALODE."]}]$q$::jsonb),
(61,'f7033880e409f29bc2c9d161e605d411',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Òfún anuncia mejoras en los negocios y éxito financiero: las preocupaciones de dinero se disiparán pronto. El creador y el ángel de la guarda de la persona la protegen. Hay que lavar la cabeza para atraer fortuna, pareja e hijos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme que su negocio o sus ingresos no crezcan, pero puede venir una mejora rápida.", "Va a viajar para trabajar y puede volver con prestigio y recursos (relato de Ọ̀rúnmìlà en la laguna y el mar).", "Busca protección para su cabeza (Orí), prosperidad, pareja e hijos (relato de Ìwòrì lavando la cabeza de Òfún).", "Pregunta si tendrá una vida agradable (relato de la gente de Isàọ̀wóngá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Prestigio y honor; volver a casa con buena fortuna.", "Riqueza, pareja e hijos por medio del lavado de cabeza.", "Una vida feliz en el lugar donde se vive."]}, {"titulo": "Ibi y advertencias", "puntos": ["Seguir comiendo sopa de quimbombó (okra), que estorba las bendiciones de este Odù.", "Dejar de atender la cabeza."]}, {"titulo": "Enseñanza principal", "texto": "La cabeza limpia atrae lo bueno. Òfún se dejó lavar la cabeza por Ìwòrì y empezaron a llegarle riqueza, esposas e hijos."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà va a la laguna y al mar. El adivino de la honestidad consultó para Ọ̀rúnmìlà cuando iba de viaje de adivinación a la laguna y al mar, y le dijo que seguiría ganando prestigio y honor y que regresaría con buena fortuna. Le marcaron un carnero blanco, una paloma blanca y 8,000 cauríes. Cumplió.", "Ìwòrì lava la cabeza de Òfún. 'El pasto húmedo lava la cabeza de la rata; las gotas de las hojas lavan al murciélago.' Así consultaron para Ìwòrì, que iba a lavar la cabeza de Òfún. Òfún preguntó si su cabeza estaría bien, y le dijeron que fuera con Ìwòrì. Ìwòrì le lavó la cabeza y Òfún empezó a tener riqueza, esposas, hijos y todo lo bueno. Canto: 'Ìwòrì Òfún es quien lava mi cabeza; lávamela para tener riqueza, pareja e hijos'.", "La gente de Isàọ̀wóngá. 'Benin es la casa de la riqueza.' Así consultaron para la gente de Isàọ̀wóngá, hija de Oníbú Ẹja, que preguntaban si la vida les sería feliz. Ofrecieron y la vida les sonrió. Canto: 'Ìwòrì Òfún no come sopa de òrúnlá; encuéntranos con mucha carne de pescado'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: un carnero blanco, una paloma blanca y 8,000 cauríes.", "Lavado de cabeza: muchas ratas y muchos murciélagos.", "Langostinos a Ifá para fortuna, pareja e hijos.", "Prohibido: sopa de quimbombó (okra, òrúnlá)."]}, {"titulo": "Relaciones espirituales", "texto": "El creador (Ẹlẹ́dá) y el ángel de la guarda protegen a la persona. Orí se lava para atraer bendiciones."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Carnero y paloma blancos, langostinos, pescado; prohibido el quimbombó."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 61.1 (yorùbá): Awo rere: / li o difá fOrúnmilà, / Ifá nṣawor'Ọ̀sá, / Ifá nṣawor'òkun. / Wọ̀n ni: / \"Ifá yoo maa gba iyi\", / \"I yoo maagba ẹyẹ̀ ati olá\" / \"A o riire Ajé t'ohun bowale\". / Ki ó rú: Àgùntàn funfun, / ẹyẹlé funfun ati egbàárin owó. / Ó gbọ̀ ó rú.", "REZO:IWORY BOFUN, IWORY TOWOFUN, IWORY TOSEFU OBA IWORY FARA INLE RERE BOBOFUN SHORU SHORU ADIFAFUN OBINI OLONU TIRIKO ADENIPETE OMO OLOKUN LODAFUN OÑI OBINI SOKUN INLE ONIKA OLOKUN WAGBO NI OMOBINI OMOTITUN EKEKA OBA IYA OMOLOGU ABERE SOPUTO IKOLO OLOKUN LODAFUN OLOKUN.", "REZO: IWORY BOFUN, IWORY TOWOFUN, IWORY TOSEFU OBA IWORY FARA INLE RERE BOBOFUN SHORU SHORU ADIFAFUN OBINI OLONU TIRIKO ADENIPETE OMO OLOKUN LODAFUN OÑI OBINI SOKUN INLE ONIKA OLOKUN WAGBO NI OMOBINI OMOTITUN EKEKA OBA IYA OMOLOGU ABERE SOPUTO IKOLO OLOKUN LODAFUN OLOKUN.", "REZO: IWORY GUOFUN ABANGUIÑA ABANGUIÑA ARANYE SHUDULOWO IYA UNDASHE BALLE ILE ABIDI KULUKUTU LODAFUN IRE LUTINSHE YEYEO OGUNATUFEIYA OWO ORUGBO.", "REZO: IWORY BOFUN ABAKUIÑA OMA ALASOBERIRE ADAGA YOKO OMO TONDOKO BERI AUNGUIBE SOKO ORI BIBE EGUN GUABIDI KURUBURU LODA YEYE ONGURA NIFE AYA OLOFIN.", "REZO: OMO BAQUIÑA AUNSOMO BIRIDE OMO TOSOKOBIRE ADIFAFUN TAPARIKUN BARIGUA LORUBO AURE ASHO FUN FUN ADIFAFUN ORUNLA ABATINLE OKO ASHO EURE TIBO OÑI IRE MEDILOGUN OWO.", "REZO: OMO BAGUIÑA UN SOBIRISE LODAFUN TAMURAKUA TINLOSOKO OBERI OLOMA KUEKUSHITI IBERI GUISI OFI SINA ABADEUN OLOFIN AKUE TOMURAGUA ODEBOSHUSHU GUERE SHUKA OLOFIN PEONINSHA PIPAYOBA TO FE COCNA ODEBO AKIFUN OLOFIN APEÑILUKUMBE AWO NINDA DE FIFAGOYA ILEKU APASHEFUN OLOFIN APOLULUKUNBE IBODE QUE BOFIN QUE REKUADA.", "REZO: IWORY AGBA MOFUN OMO ARAGUIÑA AGBA ORI IFA SHANGO LAMPE ORURU BAWA OMO TOKOBI WAWE OBI OMO MOBILAYE INLE OTUMBI IFA TEYU MOMI ENIFA ABAWADE ALABA IRE INLE ENI AYA ABAWALA IYA BALOSHE OMO OLOFIN IFA ADE EJIOGBE OSHE LOWO OTOBAYENI IGUI OLOFIN AGBA ENI AGBORAN EBONI OSHE OMO ESHILEKUN EBONI OSHE OLORUN SHANGO ORUGBO AIKU OMO EWA OLOFIN ENI ABEYE IYA OMOFUN OSHUN AKO ORUN OMO AGBA ORI IKAKARA EBO FUN ONILE OSHUN IYA AGBAYE OKANA OLOKIN ARUFIN KURU KURU OTA IKU AFOREGUEGUE IKU ARUDA IGBA ONISHEBO EDE LONIDE OYEKUN OSHANLA WARENI EBO OTOKI IFA BEWE OMO IYA BI OMO OLOFIN MOTUN BIMO LONIO OSHANLA FIWA OLO RIN OLOFIN BABA OLUO MEYO ORINI MERIDILOGUN KOSHEBO EJIOGBE ORIWA OLOFIN LODAFUN OLOFIN KAFEREFUN SHANGO OSHANLA OSHUN I ORUNLA, ADAFUN OLOKUN. REZO: ORUNLA ADIFAFUN ODUDUWA OSHAOGO UMBOAYE ASHABA ORUN GAGA IMULE LODAFUN ORUNMALE KEFEREFUN ORUNLA.", "REZO: ABAYENI OTONI BORUN ORUNLA AYE IFA NI AYE NI IFA IWORY BOFUN OMO ENI IFA ONI BABALAWO AWABO AWAN NILE AWO ORI EBENIFA EWE ATEBO LOYE OLOFIN AYE YENIKUN BAGUA ONI BABALAWO LABIYE AWO LAWOWE AWO EYENI IFA ASEGUE NI AWO.", "REZO: EBO AYEKUN ENI ORI NIFA ABAYENIFA NI AYE OSHA MAWA NIFAWA NIFA ORUNLA ENI IFA BAYEKUN BAJARI EYENI NI IFA.", "SUYERE: EWENI ATENO ONI WAENI AYE NI SHANGO ORI NIFA EWENI ATEBO ONIWA AYE.", "SUYERE: ORIBAWA ATEBO ORI NIFA LAWEWE, ORUNLA LAYE ORUN.", "SUYERE: ELESE SHANGUESI NIWEYE NI IFA OTUN NILAYEO AWETO ORI BAWANIFA.", "SUYERE: SHANGUESI MAYERI AWO.", "SUYERE: MAFORA EWOMI SHEWEWE AWADO ONA TIMOSHE AGSHEBUE.", "REZO: IWORY AGBA MOFUN OMO ARAGUIÑA AGBA ORI IFA SHANGO LAMPE ORURU BAWA OMO TOKOBI WAWE OBI OMO MOBILAYE INLE OTUMBI IFA TEYU MOMI ENIFA ABAWADE ALABA IRE INLE ENI AYA ABAWALA IYA BALOSHE OMO OLOFIN IFA ADE EJIOGBE OSHE LOWO OTOBAYENI IGUI OLOFIN AGBA ENI AGBORAN EBONI OSHE OMO ESHILEKUN EBONI OSHE OLORUN SHANGO ORUGBO AIKU OMO EWA OLOFIN ENI ABEYE IYA OMOFUN OSHUN AKO ORUN OMO AGBA ORI IKAKARA EBO FUN ONILE OSHUN IYA AGBAYE OKANA OLOKIN ARUFIN KURU KURU OTA IKU AFOREGUEGUE IKU ARUDA IGBA ONISHEBO EDE LONIDE OYEKUN OSHANLA WARENI EBO OTOKI IFA BEWE OMO IYA BI OMO OLOFIN MOTUN BIMO LONIO OSHANLA FIWA OLO RIN OLOFIN BABA OLUO MEYO ORINI MERIDILOGUN KOSHEBO EJIOGBE ORIWA OLOFIN LODAFUN OLOFIN KAFEREFUN SHANGO OSHANLA OSHUN I ORUNLA, ADAFUN OLOKUN.", "REZO: ORUNLA ADIFAFUN ODUDUWA OSHAOGO UMBOAYE ASHABA ORUN GAGA IMULE LODAFUN ORUNMALE KEFEREFUN ORUNLA.", "REZO: ABAYENI OTONI BORUN ORUNLA AYE IFA NI AYE NI IFA IWORY BOFUN OMO ENI IFA ONI BABALAWO AWABO AWAN NILE AWO ORI EBENIFA EWE ATEBO LOYE OLOFIN AYE YENIKUN BAGUA ONI BABALAWO LABIYE AWO LAWOWE AWO EYENI IFA ASEGUE NI AWO.", "REZO: “EBO AYEKUN ENI ORI NIFA ABAYENIFA NI AYE OSHA MAWA NIFAWA", "NIFA ORUNLA ENI IFA BAYEKUN BAJARI EYENI NI IFA”.", "+++"]}]$q$::jsonb),
(62,'a9eaaac94618dd4d9fbc2e8da37f159e',$q$[{"titulo": "Idea central", "texto": "Ìdí Ogbè habla de un problema presente o cercano y de la ofrenda para vencerlo. La persona siente miedo, casi siempre por dinero o trabajo, y los pleitos de pareja la cansan. Ifá le desea muchas bendiciones, pero advierte que sus enemigos pueden mandarle a alguien para ponerla a prueba: debe cuidar mucho lo que dice."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme por su empleo, su dinero o una relación que lo desgasta.", "Siente que la muerte o la enfermedad rondan la casa (relato de Ọ̀rúnmìlà frente a Ikú y Àrùn).", "Está rodeado de enemigos y puede salir victorioso (relato de Ṣàngó).", "Alguien puede meterlo en un pleito público; debe cuidar lo que dice."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que la muerte y la enfermedad no entren a la casa.", "Victoria sobre los enemigos.", "Que los enemigos no lo superen y él llegue a ser como hijo del Òrìṣà.", "Bendición de pareja."]}, {"titulo": "Ibi y advertencias", "puntos": ["Meterse en discursos o pleitos que lo enreden.", "Llevarse a la pareja de otro.", "Pleitos con la familia."]}, {"titulo": "Enseñanza principal", "texto": "Quien ofende y pide perdón de corazón es escuchado. Ìgbín se llevó a la esposa del Òrìṣà y lo apaciguó con su ofrenda y su arrepentimiento. Con las personas así se usan maneras suaves."}, {"titulo": "Relatos reunidos", "puntos": ["Los ṣigidi en las puertas. Baba Akikibiti consultó para Ọ̀rúnmìlà cuando la muerte y la enfermedad anunciaron que irían a visitar su casa. Le mandaron preparar dos figuras de ṣigidi, una forma de Èṣù, con doscientas hierbas pegadas, una espada de madera en las manos y un pedazo de kola en la boca, bañarlas con la sangre de un chivo y poner una en la puerta del frente y otra en la de atrás. Ọ̀rúnmìlà lo hizo. Llegó Ikú por el frente y le dijo al ṣigidi: 'Hazte a un lado, déjame pasar'; el ṣigidi no respondió. Fue por atrás e hizo lo mismo, sin respuesta. Llegó Àrùn y le pasó igual. Así ninguno de los dos pudo entrar.", "Ṣàngó rodeado de enemigos. Ìdígba Ìdígbe consultó para Ṣàngó cuando estaba rodeado de enemigos, y le aseguró la victoria si ofrecía un carnero y 6,600 cauríes. Cumplió y venció.", "Ìgbín y la esposa del Òrìṣà. Ìgbín, el caracol, se llevó a Ogele, la esposa del Òrìṣà. Sus seguidores cantaban: 'Ya tenemos a Ogele; a ver qué hace el Òrìṣà'. Ìgbín les dijo que eso era un insulto, y que buscaría la forma de apaciguar al Òrìṣà para que nadie dijera que le robó a su mujer. Hizo su ofrenda, y su tambor madre empezó a sonar: 'Déjala, perdóname, cédemela'. El Òrìṣà caminaba marcando el ritmo y dijo: 'El que se llevó a mi esposa es el mismo que me ha apaciguado con su ofrenda; quien pide perdón está arrepentido'.", "Adédoyin, hijo del Òrìṣà. Ifá consultó para Adédoyin, hijo del Òrìṣà Òwújin, y le marcó una gallina de plumas paradas para que sus enemigos no lo superaran, sacrificada en el suelo a los pies del Òrìṣà. Ofreció y venció a sus enemigos. 'La muerte que deseaban para Adédoyin no pudo con él; ni la enfermedad, ni la pérdida.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: dos ṣigidi con doscientas hierbas, espada de madera y kola en la boca, bañados con la sangre de un chivo, en la puerta del frente y en la de atrás.", "Ṣàngó: un carnero y 6,600 cauríes.", "Ìgbín: ofrenda al Òrìṣà para pedir perdón.", "Adédoyin: una gallina de plumas paradas a los pies del Òrìṣà."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù, en forma de ṣigidi, cuida las puertas de la casa. Ṣàngó vence con la ofrenda. El Òrìṣà perdona al que se arrepiente."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hierbas pegadas al ṣigidi, nuez de kola, espada de madera, gallina de plumas paradas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 62.1 (yorùbá): Baba-akikibiti, / Baba-akikibiti: / li o difá fOrúnmilà / nigbi ikú nwipe oun nbọ ni ilè rẹ̀, / ti àrùn nwipe oun nbọ ni ilé rè / Wọ̀n niki ó lọ gun ṣigidi amonu Méjì. / Kiofi igba ẹeru gun wọn lara. / Kiofi agada igi le wọn lowọ ni ökankan. / Kiopa òbúko kan / kioda ejẹ rẹ si wọn l'ara. / Kiogbe okan si ẹnú-ọ̀nà iwájú-ilé, / Kiogbe ekeji si ẹnú-ònà ehinkulé. / Ọ̀rúnmìlà gbọ̀ ó rú. / O si ṣe gẹgẹbi Ifá ti sọ fún un. / Ikú de enú-ọ̀nà iwájú-ilé, / o ki Ṣigidi yi bayi. / Baba-akikibiti, / Baba-akikibiti. / Ojobi ọ̀nà kuro f'Awo lọna k'Awo ribi lọ, / kò dahun, Ikú pada, / O lọsi enú-ònà Keji o nwi bakanna. / Àrùn de o wi bakanna, kò dahun / Bayi ni Ọ̀rúnmìlà ṣe ti Ikú / ati Àrùn kò le wole tọọ.", "Verso 62.2 (yorùbá): İdigba Idigbe: / li o difá fún Sàngó / nbẹ laarin ptá. / Ifá la ṣẹ wọ̀n: / Agbo kan ati egbẹ̀talélọ̀gbọ̀n owó li ebọ. / Ṣàngó rúbọ / O ṣégun wọn.", "REZO: ERDIBRE ORONA OGU ERDIBRE ORONA ORISHA EKUTE LELE CUA OKU IYA ADIFAFUN OKA BABA, EYELE MARUN ELEBO. ERDIBRE ORONA OGU ERDIBRE ORONA ORISHA LO OMO OGUN IYA ADIFAFUN ORUNMILA LORUGBO.", "REZO: DIBUE DIGUE ARANILA OGUN DIBUE ARANILA OLLA EKUTELE QUIMO OGUN OMO LLATA DARIENLLE.", "REZO: DIGUE DIGUE AURA AGUN DIGUE AURA LA OYA EKUTELE MIMO OGUN.", "REZO: EDIBE IDE NIFA QUI NERE CHENOTA KAFEREFUN OBANLA SHANGO Y OGUN.", "REZO: DIGUE DIGUE AURA LA OLGUE DIGUE AURA EKUTELE QUIMI ALGUNO.", "REZO: EDIBE LARA ORISHA ADIFAFUN ORUNLA MACHICHE ACHEMU OUNKO LEBO.", "REZO: ERDIBRE ORANA OGUN ERDIBRE ORANA ORISHA LE OMO OGUN IYA ADIFAFUN ORUNMILA.", "SUYERE ARARA: DIBE MASUDO AJE. DIBE MABUDO AJA.", "REZO: EDIGBERE LLAGUN EDIGBERE SALU IGRIN ADIFAFUN ILO OLUO POPO OKUTE LOWE ODE KEWE OFUN OMO OYA ARA ABIKU AYE ELU ORUNMILA FILU KALIUMI ESOSI KISHE ORA ARITI IGUI EGGUN KUELEMI OSA KULEYA EDIGBERE LOWA ADIFAFUN LOMA NUELI OMO SHAKUANA OMO ADELE.", "REZO: ERDIBRE LALAWA LAU IGBUN ODO OKUTE LOMO TIVITIWI KAGUE NI SESI IYA SENA ADIFAFUN KUNKU EGGUN INA YOGUN SHOYI TIMROYO YEMAYA LOYA NINUSHO IBU MARATRA ABITI KUEKEN ISHE ADIFAFUN.", "REZO: ADIFAFUN ERDIBRE OLOFIN FIYESI MOWAWE MOGRO KUBI OSOKAPRA SHANGO, OLOFIN SIMALE ALAFIA OBARA OLOTO LORDAFUN", "ELEGUA KAFEREFUN OLOFIN ADIFAFUN OLOGUA AWO KIRA WO IBAWOYE IBO IRIKI INLE.", "REZO: ADIFAFUN ONIBETE EWE ADETE ARUN MOWA OFOLEITOSHU MOWALE INAGUI OBO ARIKU LODAFUN OBATALA KAFEREFUN SHANGO ADIFAFUN IGUI."]}]$q$::jsonb),
(63,'c143aa42912ba153d33f9e6e66d07cd5',$q$[{"titulo": "Idea central", "texto": "Ìdí Ọ̀yẹ̀kú, en buena fortuna, anuncia éxito con el dinero por medio de la rogación de la cabeza (Orí). En mala fortuna pide ofrendas concretas para apartar la muerte. Hace falta comunicarse con los antepasados para aliviar los problemas del negocio. Tendrá muchos hijos, pero debe cuidarse de sus enemigos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca alivio de las presiones diarias y de problemas en el negocio, apoyándose en sus antepasados.", "Desea hijos y protección frente a adversarios (relato de Òyà).", "Se prepara para salir a otra ciudad y pregunta cómo le irá (relato de Okunkunṣù en Ifẹ̀).", "No quiere soltar un bien material y por eso ignora una advertencia (relato de Olorí-Oga y la tela blanca)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Éxito y dinero en un lugar nuevo, aunque uno no sea grande.", "Muchos hijos.", "Hijos fuertes y parecidos entre sí, que dan beneficio a los demás."]}, {"titulo": "Ibi y advertencias", "puntos": ["Aferrarse a algo de la casa que Ifá pidió ofrecer.", "Ofrecer por los hijos y olvidar ofrecer contra los enemigos.", "Problemas de negocio por no atender a los ancestros."]}, {"titulo": "Enseñanza principal", "texto": "Hay que ofrecer completo: por lo que se desea y contra lo que amenaza. El cortador de césped tuvo a sus hijos pero no ofreció contra sus enemigos, y el hombre los cortó y los quemó."}, {"titulo": "Relatos reunidos", "puntos": ["Olorí-oga y su tela blanca. Idiyẹkuyẹkẹtẹ consultó para Olorí-oga y le marcó una pieza de tela blanca que tenía en su casa y una carnera con 32,000 cauríes, para que ese año su cadáver no fuera envuelto en esa tela. Escuchó, pero no quiso ofrecerla. El canto dice: 'Olorí-oga se cubrió a sí mismo con su tela'.", "Okunkunṣu llega de noche a Ifẹ̀. Ifá consultó para Okunkunṣu, que iba a la ciudad de Ifẹ̀, y le dijo que llegara de noche después de ofrecer una rata, un pescado y una gallina para apaciguar su cabeza; ahí tendría mucho éxito. Cuando llegó, Èṣù fue casa por casa anunciando que había llegado un babaláwo que no iba a la casa de nadie, que la gente debía ir a verlo, porque todo lo que hiciera saldría bien aunque él no fuera grande. Así se juntó la gente, y Okunkunṣu regresó con mucho dinero y bienes.", "El cortador de césped y sus hijos. Ifá consultó para el cortador de césped, que fue a ver a Òṣun porque no tenía hijos. Le pidieron ofrecer para tener hijos y también contra sus enemigos de la tierra. Ofreció por los hijos, pero no dio los machetes, ramas y garrotes que lo protegían de sus enemigos. Tuvo hijos, y cuando los hombres llegaron a cortar y quemar el monte, quiso huir con ellos, pero le lanzaron garrotes y ramas y lo cercaron. Imploró a Ifá, pero ya era tarde.", "El coco y sus hijos duros. El adivino del coco consultó para el coco, que lloraba porque no tenía hijos. Le dijeron que ofreciera y que todos sus hijos se parecerían. Ofreció una canasta llena de pollos, la misma que hoy se le cuelga en el tronco para que sus frutos no caigan y se rompan. El coco creció más alto que una persona y los hombres buscaron sus frutos para sentirse bien. '¿Quién tiene hijos tan duros? El coco.'"]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Olorí-oga (rechazado): una tela blanca de su casa, una carnera y 32,000 cauríes.", "Okunkunṣu: una rata, un pescado y una gallina para su cabeza.", "Por los hijos: una canasta llena de pollos y gallinas en igual número.", "Contra los enemigos: machetes, ramas y garrotes."]}, {"titulo": "Relaciones espirituales", "texto": "Orí, la cabeza, se ruega para el éxito. Èṣù reúne a la gente alrededor de quien ofreció. Òṣun recibe la petición de hijos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tela blanca, coco, canasta de pollos, machetes, ramas y garrotes."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 63.1 (yorùbá): Idiyẹkuyẹkẹtẹ: / li o dífá f'Olorí-oga / Wọ̀n niki ó fi aṣo funfun kan / bayi tiowa ni ilé rẹ rúbọ / ati àgùtàn pẹlu ẹgbàá mọ̀kànlá owó, / kiwọn ma baa fi aṣo naa / di okú rẹ l'odúnni / Ó gbó kò rú. / Orin Ifá: / Edi-oyẹyẹ, Edi-pyẹyẹ / Olorí-Ọga f'aṣo rẹ bo'ri o, / Edi-oyẹyẹ, Edi-oyẹyẹ.", "Verso 63.2 (yorùbá): Awo-ire-ire-niifi-ehin-tan'na / li o difá f'Okunkunṣu / nlọ si Otù-Ifè. / Wọ̀n ni oru niki o ba wọ ilu / naa lẹhin ti o ba ti rú: / eku kan, ẹja kan, abo-adiyẹ kan, / kiotibo orí (Oluṣupẹn) rẹ. / Ifá ni a rire lohun papoju.", "REZO: ODI YEKU DIYEKU OLORDAFUN BARABANIREGUN AUN RUKU OLOYA UMBO UNPOLOSE AYARELO.", "REZO: ODI YEKUN DILLECU OLORDAFUN BARABA MIREGUN AUN RUCU OLALLA UMBO UMPELESE ALLARELO. IDICULU OLLECULU ADUFAFUN OLLA ABAGUGU CAÑA DE CASTILLA MELOBILLO OUNKO LEBO.", "SUYERE: ODI SHUKU SHUKU IDI YEKU IDI YEKU YEKU WOLU AFAFA.", "SUYERE: TELEMISHE TELEMISHE ODI YEKU AÑA AMOJO OGUARA."]}]$q$::jsonb),
(64,'b55009a5658f0285708188d5021f96db',$q$[{"titulo": "Idea central", "texto": "Ìdí Ìwòrì pide usar bien la inteligencia, trabajar y juntarse con gente de bien, de buen carácter y sabia. Advierte no unirse a estafadores, ladrones ni gente fraudulenta, porque solo traen pérdidas. La persona está ignorando a un rival que puede desplazarla. Debe obedecer a sus mayores y comportarse como su padre para ser rico."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme que lo desplacen en un negocio, una sociedad o una relación, y no sabe bien quién compite con él.", "Tiene una capacidad que no está usando: saber sin aplicar es como no saber.", "Puede estar rodeado de gente con malas mañas que terminen perjudicándolo.", "Teme quedar en un puesto de menor importancia."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["No ser relegado a un puesto menor.", "Riqueza por obedecer a los padres y a los mayores.", "Un benefactor que llega de lejos y lo hace rico."]}, {"titulo": "Ibi y advertencias", "puntos": ["Juntarse con malas compañías.", "Tener sabiduría y no aplicarla; tener poder y no usarlo.", "Ignorar al rival que lo puede reemplazar.", "Desobedecer a los parientes mayores."]}, {"titulo": "Enseñanza principal", "texto": "Si tenemos sabiduría y no la aplicamos, nos volvemos ignorantes; si tenemos poder y no lo usamos, nos volvemos holgazanes. Dime con quién andas: la compañía decide la suerte."}, {"titulo": "Relatos reunidos", "puntos": ["Lo que está más allá del intelecto. Ìdí, el adivino de la casa de Edú, preguntó: '¿Ifá hace algo que está más allá de lo humano?'. Le dijeron que ofreciera para no ser relegado a un puesto menor: cuatro palomas, 8,000 cauríes y medicina de Ifá, un baño de hojas de awùn y ọ̀mọ̀ machacadas con jabón. Cumplió.", "La gente del bajo mundo. 'Si tenemos sabiduría y no la aplicamos, nos volvemos ignorantes; si tenemos poder y no lo usamos, nos volvemos holgazanes.' Así consultaron para la gente del bajo mundo, que no se juntaba con los sabios ni con los trabajadores. Ifá les dijo que no se estaban asociando con gente digna, y que eso trae mala suerte. Les marcaron dos gallinas y 4,400 cauríes.", "Ọdún Èlà, el hijo obediente. Ifá consultó para Ọdún Èlà, el hijo de las entrañas, que preguntaba si llegaría a ser rico. Le dijeron que ofreciera y que se comportara como su padre, sin desobedecer a sus mayores. Ofreció y su vida fue tranquila.", "Òkànbí y el benefactor de lejos. Conspiraron contra Òkànbí y le dijeron que nunca sería rico, que siempre sería pobre. Ifá le dijo que ofreciera, que su benefactor vendría de muy lejos y lo haría muy rico. Ofreció con gusto y la vida le sonrió. Cantó: 'Ifá ha dicho que yo seré rico; el Ìrókò se refugia con cualquier cosa; yo practico el sacerdocio para ser rico'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra el desplazamiento: cuatro palomas, 8,000 cauríes y baño de hojas de awùn y ọ̀mọ̀ con jabón.", "La gente del bajo mundo: dos gallinas y 4,400 cauríes.", "Ọdún Èlà y Òkànbí: ofrenda por riqueza."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá favorece a quien se junta con gente de bien. Los padres y los mayores son la guía de la prosperidad."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Awùn, ọ̀mọ̀, jabón, Ìrókò."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 64.1 (yorùbá): Ìdí awo e ju ri, / Ìdí awo e ju mẹ, / Ökùnkùn de'nimolẹ bi oru awo ilé Ẹdú. / Ifá nṣe ohun ti ẹnikan mọ? / Çbọ niki a ṣe, / ki oma baa di ẹni-ẹhin ti a kii wa. / Ẹbọ: Ẹyẹlé mẹrin, ẹgbàárin owó ati ewé Ifá / Ó gbọ̀ ó rú.", "Verso 64.2 (yorùbá): Bi a lọ̀gbọ̀n ninu bi a ko loo, / aó dọ̀gbẹ̀ri, / Bi a l'ágbára ninu bi a kò loo, / ao d'ọ̀lẹ ni: / a difá fún àwọn èniyàn Mab'olọ̀gbọ̀n-rìn / Mab'aṣiṣé s'ọ̀rè ero isalẹ ayé. / lra nba ọ wi, / Ó ni: / \"Iwą ko ba ẹniire rin, / iwo ko ba ẹniire s'orẹ. / Oríburúkú niimaamu ba èniyàn\". / Ẹbọ: adiyẹ Méjì ati egbejiológún owó.", "REZO: ODI ORO ODI OFEYU MEWA YENI OBA OYU LOLO INLE ALABANIYO OMOLOGU YEKUN OMO INLE SOKUN YERE EFEYU NI AINA IYA INLE LODAFUN ASHE ASHIRI LELEO EYUERO OBA AINA ONA OBA ADO LODAFUN INLE MAFEREFUN OZAIN.", "REZO: AWO NI FALLA MOSU MOALO LA ANA ONI OMO SHANGO.", "REZO: IBIBOMO OGUORI BOMU ADIFAFUN ORO ADIE LEBO.", "REZO: ODI WORI ODI BOMU IGUORI BOMU ADIFAFUN ODI ORO.", "SUYERE: IWORIWO IWORI WORE EBA ROKO MABAYE.", "REZO: ODI ORO ODI OFOYU MOWA YENI LELE INLE ALAWA WIYE OMOLOGU YEKUN OMO INLE SOKUN YESE OYOYU NI AINA IYA INLE LODAFUN ASHE ASHIRI LELE OJUERO AINA ONA ODO LODAFUN INLE KAFEREFUN OZAIN."]}]$q$::jsonb))
update estera_sintesis e set secciones=v.sec from nuevas v where e.numero=v.numero and md5(e.secciones::text)=v.viejo returning e.numero;
